window.AULAS = window.AULAS || {};
window.AULAS["imuno-thiago-01"] = {"subtitulo": "Revisitando a imunologia básica", "pdf": "pdf/thiago/aula-01.pdf", "abas": ["resumo", "glossario", "quiz", "pdf"], "fontes": ["Aula 1 · Revisitando a Imunologia Básica (Prof. Dr. Thiago Corrêa)", "Abbas, Lichtman e Pillai, Imunologia Celular e Molecular (citado nos slides)"], "resumo": [{"titulo": "1. O que é o sistema imunológico e para que serve", "pontos": [{"t": "Conceito de imunidade", "sub": ["Imunidade é o conjunto de mecanismos que protegem o organismo de agentes infecciosos e de células ou substâncias lesivas (slide 2).", "Na prática, o sistema precisa cumprir quatro tarefas ao mesmo tempo: defender contra micro-organismos, reparar tecidos danificados, vigiar células transformadas e distinguir o próprio do não próprio (slide 3).", "Quando a defesa falha, aparecem as imunodeficiências (aulas 3 e 4); quando reage contra o próprio, aparecem autoimunidade e hipersensibilidade (aulas 5 e 8). Esse eixo organiza toda a disciplina.", "Fonte: Abbas, Lichtman e Pillai, Imunologia Celular e Molecular, 9ª ed.; Janeway's Immunobiology, 8ª ed. (citados nos slides)."]}, {"t": "Duas linhas de defesa", "sub": ["Imunidade inata: primeira resposta, em minutos a horas, com receptores codificados na linhagem germinativa. Não gera memória duradoura (slides 7 e 8).", "Imunidade adaptativa: mais lenta, mas específica, diversa e com memória. É feita por linfócitos B e T (slide 7).", "Uma infecção começa sendo contida pela inata e só depois é 'resolvida' pela adaptativa. Por isso um déficit inato e um adaptativo se manifestam de forma diferente."]}]}, {"titulo": "2. Origem das células e órgãos linfoides", "pontos": [{"t": "Hematopoese", "sub": ["Todas as células do sistema imune derivam de células-tronco hematopoéticas (CTH) da medula óssea (slide 4).", "Linhagem mieloide: neutrófilos, monócitos e macrófagos, mastócitos, eosinófilos, basófilos e células dendríticas.", "Linhagem linfoide: linfócitos B, T e NK. Os linfócitos saem da medula e precisam de órgão específico para amadurecer."]}, {"t": "Órgãos linfoides primários e secundários", "sub": ["Primários (onde as células são produzidas e amadurecem): medula óssea e timo. O timo é o local de maturação dos linfócitos T (slide 5).", "Secundários (onde a resposta acontece): linfonodos, baço e tecido linfoide associado à mucosa (MALT) (slide 5).", "Uma vez que a célula virgem encontra o antígeno no órgão secundário, ela se ativa e se multiplica ali."]}, {"t": "Leucograma", "sub": ["O leucograma, parte do hemograma, conta e classifica os leucócitos: é a medida simples da defesa celular (slide 6)."]}]}, {"titulo": "3. Imunidade inata: barreiras e reconhecimento", "pontos": [{"t": "Barreiras", "sub": ["Pele e mucosas impedem a entrada microbiana por defesa física (epitélio íntegro) e química (pH, enzimas, peptídeos antimicrobianos) (slide 9)."]}, {"t": "PAMPs e DAMPs", "sub": ["PAMPs (padrões associados a patógenos): ácidos nucleicos (ssRNA, dsRNA, CpG), proteínas (pilina, flagelina), LPS, ácido lipoteicoico, manana e glucanas (slide 8).", "DAMPs (padrões associados ao dano): DNA, HSPs, HMGB1, ATP, citocromo c e histonas, liberados por células lesadas ou necróticas (slide 8).", "Receptores como os TLR reconhecem essas moléculas. O ponto central: o receptor não vê o 'patógeno', vê o padrão, por isso a inata responde mesmo sem micro-organismo (dano estéril)."]}, {"t": "Inflamação aguda e crônica", "sub": ["Aguda: vasodilatação, aumento da permeabilidade, edema e recrutamento de neutrófilos. Sinais cardinais: calor, rubor, edema, dor e perda de função.", "Crônica: substitui a aguda quando a infecção não é eliminada ou a lesão persiste (slide 10). Predominam macrófagos e linfócitos, com fibrose possível."]}, {"t": "Citocinas", "sub": ["TNF, IL-1 e IL-6 são citocinas pró-inflamatórias centrais (slide 11). Produzidas por macrófagos e células endoteliais, elevam febre, ativam endotélio e induzem síntese hepática de proteínas de fase aguda."]}]}, {"titulo": "4. Adaptativa: anticorpos e maturação da resposta", "pontos": [{"t": "Estrutura do anticorpo", "sub": ["Duas cadeias pesadas e duas leves. As regiões variáveis (V) reconhecem o antígeno; as regiões constantes (C) determinam o isótipo e as funções efetoras (slide 12)."]}, {"t": "Maturação da resposta humoral", "sub": ["Maturação por afinidade: mutações na região variável selecionam anticorpos de maior afinidade (slide 13).", "Troca de isótipo: a mesma região variável passa a ser combinada com outra região constante (IgM para IgG, IgA ou IgE) (slide 13).", "Mudança de membrana para forma secretada: a célula B deixa de ser receptor e passa a produzir anticorpo solúvel (slide 13)."]}, {"t": "Funções efetoras", "sub": ["Neutralização, opsonização, ativação do complemento e citotoxicidade celular dependente de anticorpo (slides 14 e 15). Cada isótipo tem função preferencial."]}]}, {"titulo": "5. Apresentação antigênica e linfócitos T", "pontos": [{"t": "MHC", "sub": ["MHC de classe I: em células nucleadas. Apresenta antígenos do citosol (vírus) a linfócitos T CD8+ (slide 16).", "MHC de classe II: em células dendríticas, linfócitos B, macrófagos e células epiteliais tímicas. Apresenta antígenos endocitados a linfócitos T CD4+ (slide 16)."]}, {"t": "Processamento e ativação", "sub": ["Antígenos do citosol e internalizados são convertidos em peptídeos pelas vias de processamento (slide 17).", "Três sinais para o linfócito T virgem: (1) antígeno, que dá especificidade; (2) coestimulação (B7 com CD28); (3) citocinas, que orientam a diferenciação (slide 18; Abbas).", "Sem o segundo sinal, a célula pode entrar em anergia (aula 5)."]}, {"t": "Subpopulações efetoras", "sub": ["Th1: IFN-gama, ativa macrófagos, defesa contra intracelulares. Th2: IL-4, IL-5, IL-13, favorece IgE e eosinófilos. Th17: IL-17, recruta neutrófilos. Tfh: ajuda a célula B nos centros germinativos (slide 19).", "CTL CD8+: mata a célula infectada pela via da perforina e granzima (slide 20)."]}]}, {"titulo": "6. Como estudar esta aula", "pontos": [{"t": "Pontos de cobrança", "sub": ["Diferenças entre inata e adaptativa: especificidade, memória, tempo de resposta.", "Qual MHC apresenta o quê, e qual linfócito reconhece cada um.", "PAMP × DAMP: qual é a origem da molécula.", "Troca de isótipo × maturação por afinidade: o que muda em cada uma."]}]}], "glossario": [{"termo": "CTH (célula-tronco hematopoética)", "tecnica": "Origem das células do sistema imune", "definicao": "Célula da medula óssea que dá origem às células do sistema imune por hematopoese.", "slide": 4}, {"termo": "MALT", "tecnica": "Órgãos linfoides secundários", "definicao": "Tecido linfoide associado à mucosa, uma das categorias de órgãos linfoides secundários.", "slide": 5}, {"termo": "PAMP", "tecnica": "Reconhecimento na imunidade inata", "definicao": "Padrão molecular associado ao patógeno, como LPS, flagelina e ácidos nucleicos microbianos.", "slide": 8}, {"termo": "DAMP", "tecnica": "Reconhecimento na imunidade inata", "definicao": "Padrão molecular associado ao dano, liberado por células lesadas, como HMGB1, ATP e histonas.", "slide": 8}, {"termo": "Inflamação crônica", "tecnica": "Inflamação aguda × crônica", "definicao": "Processo que substitui a inflamação aguda quando a infecção não é eliminada ou a lesão persiste.", "slide": 10}, {"termo": "Maturação por afinidade", "tecnica": "Resposta adaptativa humoral", "definicao": "Ajuste fino do anticorpo durante a resposta imune, aumentando a afinidade pelo antígeno.", "slide": 13}, {"termo": "Troca de isotipo", "tecnica": "Resposta adaptativa humoral", "definicao": "Mudança da classe da imunoglobulina produzida, mantendo a região variável do anticorpo.", "slide": 13}, {"termo": "MHC classe I × classe II", "tecnica": "Apresentação antigênica", "definicao": "Classe I é expressa em células nucleadas; classe II, em células dendríticas, linfócitos B, macrófagos e células epiteliais tímicas.", "slide": 16}, {"termo": "Abbas (Imunologia Celular e Molecular)", "tecnica": "Fonte", "definicao": "Livro-texto de imunologia citado como referência principal da disciplina.", "slide": 18}, {"termo": "Hematopoese", "tecnica": "Origem celular", "definicao": "Formação das células do sangue e da imunidade a partir de células-tronco hematopoéticas na medula óssea.", "slide": 4}, {"termo": "Órgãos linfoides primários", "tecnica": "Órgãos", "definicao": "Medula óssea e timo, onde os linfócitos são gerados e amadurecem.", "slide": 5}, {"termo": "Órgãos linfoides secundários", "tecnica": "Órgãos", "definicao": "Linfonodos, baço e tecido linfoide associado à mucosa (MALT), onde ocorre a resposta adaptativa.", "slide": 5}, {"termo": "Leucograma", "tecnica": "Hemograma", "definicao": "Parte do hemograma que avalia os leucócitos, responsáveis pela defesa imunológica.", "slide": 6}, {"termo": "Imunidade inata × adaptativa", "tecnica": "Conceito", "definicao": "Inata: rápida, sem memória, com receptores fixos. Adaptativa: específica, com memória, por linfócitos.", "slide": 7}, {"termo": "Citocinas TNF, IL-1 e IL-6", "tecnica": "Citocinas", "definicao": "Mediadores inflamatórios da imunidade inata. Causam febre, ativação endotelial e recrutamento de células.", "slide": 11}, {"termo": "Região variável (V) e constante (C) do anticorpo", "tecnica": "Estrutura", "definicao": "A região V reconhece o antígeno. A região C medeia funções efetoras, como ativação do complemento e ligação a receptores de Fc.", "slide": 12}, {"termo": "Funções efetoras dos anticorpos", "tecnica": "Funções", "definicao": "Neutralização, opsonização, ativação do complemento e citotoxicidade celular dependente de anticorpo.", "slide": 12}, {"termo": "MHC classe I e MHC classe II", "tecnica": "Apresentação de antígeno", "definicao": "MHC I em células nucleadas apresenta antígenos a linfócitos T CD8+. MHC II em células dendríticas, B, macrófagos e epitélio tímico apresenta a T CD4+.", "slide": 16}, {"termo": "Processamento antigênico", "tecnica": "Apresentação de antígeno", "definicao": "Vias que convertem antígenos proteicos do citosol ou do meio extracelular em peptídeos para apresentação pelo MHC.", "slide": 17}, {"termo": "Linfócito T CD4+ (auxiliar)", "tecnica": "Linfócito T", "definicao": "Reconhece peptídeo no MHC II. Diferencia-se em subpopulações efetoras, como Th1, Th2, Th17 e Treg.", "slide": 19}, {"termo": "Linfócito T CD8+ (citotóxico, CTL)", "tecnica": "Linfócito T", "definicao": "Reconhece peptídeo no MHC I. Elimina células infectadas ou tumorais por morte celular.", "slide": 16}], "caso": {"titulo": "Caso: infecção bacteriana de pele", "perfil": "Imunidade inata, inflamação e primeira apresentação do antígeno.", "etapas": [{"titulo": "Etapa 1: barreira e reconhecimento", "texto": "Homem de 40 anos com ferida contaminada na perna. Bactérias Gram-negativas atravessam a barreira da pele. Macrófagos residentes detectam a bactéria e liberam citocinas.", "perguntas": [{"pergunta": "Qual molécula bacteriana é reconhecida pela imunidade inata como padrão associado ao patógeno?", "alts": ["LPS, componente da parede celular bacteriana (PAMP)", "HMGB1, liberado por células lesadas (DAMP)", "Anticorpo IgG produzido após a primeira exposição", "Histonas liberadas por necrose celular", "Linfócito T CD8+ já ativado no tecido"], "erradas": ["HMGB1 é um DAMP: sinaliza dano celular, não patógeno.", "Anticorpos exigem resposta adaptativa, que ainda não começou.", "Histonas são DAMPs, liberados por morte celular.", "Linfócitos T não são padrões moleculares."], "justificativa": "Os PAMPs incluem LPS e outras moléculas da parede celular bacteriana (slide 8)."}]}, {"titulo": "Etapa 2: citocinas e resposta", "texto": "Após algumas horas, a ferida apresenta calor, rubor e edema. Macrófagos liberam citocinas que recrutam neutrófilos. A infecção não é controlada e a inflamação persiste por dias.", "perguntas": [{"pergunta": "Qual situação descrita caracteriza a substituição da inflamação aguda por inflamação crônica?", "alts": ["A infecção não é eliminada e a lesão tecidual se prolonga", "A infecção é eliminada em poucas horas pelos neutrófilos", "A barreira epitelial recupera a integridade sem lesão", "Anticorpos neutralizam o patógeno antes da inflamação", "A citocina TNF é substituída por IL-1 no foco"], "erradas": ["Se a infecção é eliminada em horas, não há substituição por inflamação crônica.", "Com barreira íntegra e sem lesão, não há substituição.", "Os anticorpos não são citados como causa da substituição.", "TNF, IL-1 e IL-6 são citocinas citadas, sem essa substituição."], "justificativa": "A inflamação crônica substitui a aguda quando a infecção não é eliminada ou a lesão se prolonga (slide 10)."}]}]}, "questoes": [{"id": 1, "nivel": "muito_dificil", "enunciado": "Em um modelo experimental, um animal sem linfócitos B e T elimina uma bactéria extracelular em 48 horas, mas a segunda inoculação da mesma bactéria é controlada com a mesma rapidez. Qual conclusão é a única compatível com os conceitos da aula?", "alternativas": ["A eliminação depende de anticorpos residuais, que persistem após a primeira inoculação", "A eliminação é feita por linfócitos Treg, que memorizam o patógeno sem ativação", "A eliminação é feita por imunidade inata, que não depende de memória de linfócitos", "A eliminação depende de MHC de classe II em células nucleadas, sem apresentação", "A eliminação depende de DAMPs liberados pela bactéria, sem qualquer receptor do hospedeiro"], "gabarito": "C", "justificativa": "Sem linfócitos não há anticorpos nem memória clonal; a defesa vem da inata, que reconhece padrões conservados e não gera memória (Aula 1, slides 7 e 8).", "tecnica": "Inata × adaptativa", "slide": 7, "pdf": "pdf/thiago/aula-01.pdf"}, {"id": 2, "nivel": "muito_dificil", "enunciado": "Uma molécula liberada por célula necrótica ativa receptores do tipo Toll em macrófagos, mesmo sem micro-organismo presente, e o patologista quer saber se o estímulo é PAMP ou DAMP. Qual critério a aula usa para separar as duas categorias?", "alternativas": ["A capacidade de ativar TLR: PAMP ativa TLR, DAMP não ativa nenhum receptor", "O tamanho molecular: PAMP é grande e DAMP é pequeno, de até cem daltons", "A solubilidade no plasma: PAMP é solúvel e DAMP é sempre insolúvel no soro", "PAMP vem de micro-organismo; DAMP vem do próprio dano", "A presença de MHC na superfície: PAMP tem MHC e DAMP não tem MHC"], "gabarito": "D", "justificativa": "PAMPs são padrões de micro-organismos; DAMPs (HMGB1, ATP, histonas, DNA) são liberados quando células são lesadas (Aula 1, slide 8).", "tecnica": "PAMPs e DAMPs", "slide": 8, "pdf": "pdf/thiago/aula-01.pdf"}, {"id": 3, "nivel": "muito_dificil", "enunciado": "Um paciente sem timo funcional tem linfonodos palpáveis, mas poucos linfócitos T maduros no sangue. A aula distingue órgãos primários e secundários. Qual afirmação sobre esse quadro é correta?", "alternativas": ["O linfonodo é o órgão primário que maturou a T, e o timo serve apenas como órgão secundário", "A medula é o único órgão primário e, por isso, a falta de timo é compensada pela medula", "Medula e timo são primários; linfonodo, baço e MALT, secundários", "O baço é o órgão primário das células T, pois filtra o sangue e produz a maturação", "O MALT é órgão primário, pois apresenta antígenos de mucosa e gera linfócitos T maduros"], "gabarito": "C", "justificativa": "Medula óssea e timo são órgãos primários; linfonodos, baço e MALT são secundários, onde ocorre a resposta (Aula 1, slide 5).", "tecnica": "Órgãos linfoides", "slide": 5, "pdf": "pdf/thiago/aula-01.pdf"}, {"id": 4, "nivel": "muito_dificil", "enunciado": "Em uma infecção, a célula B passa a produzir anticorpos cada vez mais específicos, sem mudar a classe da imunoglobulina. Que dois processos descritos na aula estão acontecendo, e qual não está?", "alternativas": ["A troca de isótipo acontece; a maturação por afinidade não está ocorrendo", "Maturação por afinidade acontece; a troca de isótipo não está ocorrendo", "Ambos acontecem, com troca do isótipo para IgE e mudança para forma secretada", "Nenhum acontece, pois a especificidade é constante desde o primeiro contato", "A mudança de membrana para forma secretada está ocorrendo, sem afinidade alguma"], "gabarito": "B", "justificativa": "Maturação por afinidade muda a região variável; troca de isótipo muda a classe, sem alterar a especificidade do antígeno (Aula 1, slide 13).", "tecnica": "Maturação por afinidade", "slide": 13, "pdf": "pdf/thiago/aula-01.pdf"}, {"id": 5, "nivel": "muito_dificil", "enunciado": "Um linfócito T CD4+ reconhece um peptídeo originado do citosol de uma célula infectada por vírus. Pela aula, qual é a afirmação correta sobre a via de apresentação?", "alternativas": ["É exibido em MHC de classe II, pois o vírus está no citosol da célula infectada", "É exibido em MHC de classe I, somente pelas células dendríticas do linfonodo", "É exibido em MHC de classe II da própria célula nucleada, que expressa tudo", "Não é apresentado por MHC de classe II, mas de classe I", "É exibido em MHC de classe I, somente por linfócitos B de memória circulantes"], "gabarito": "D", "justificativa": "MHC de classe I apresenta antígenos do citosol; MHC de classe II é expresso por dendríticas, B, macrófagos e células epiteliais tímicas (Aula 1, slides 16 e 17).", "tecnica": "Apresentação antigênica", "slide": 16, "pdf": "pdf/thiago/aula-01.pdf"}, {"id": 6, "nivel": "muito_dificil", "enunciado": "Um linfócito T virgem é ativado com reconhecimento do antígeno, mas sem coestimulação. Segundo a aula, que destino essa célula provavelmente tem, e qual é o primeiro sinal necessário?", "alternativas": ["Não é plenamente ativada; falta coestimulação", "É ativada plenamente pelo primeiro sinal, pois o antígeno sozinho basta para a resposta completa", "Vira célula de memória imediata, sem necessidade de citocinas ou de coestimulação", "Torna-se Treg automaticamente, pois o antígeno sem coestimulação induz supressão obrigatória", "Passa a produzir IgE, pois o primeiro sinal é sempre a histamina liberada no tecido"], "gabarito": "A", "justificativa": "O antígeno é o primeiro sinal e garante especificidade; a ativação completa depende de coestimulação e citocinas (Aula 1, slide 18; Abbas).", "tecnica": "Ativação de linfócitos", "slide": 18, "pdf": "pdf/thiago/aula-01.pdf"}, {"id": 7, "nivel": "muito_dificil", "enunciado": "Uma célula T produz IFN-gama e ativa macrófagos. Outra população, em um sítio de infecção extracelular, produz IL-17 e recruta neutrófilos. Quais subpopulações efetoras CD4+ são essas?", "alternativas": ["Th2 e Th1", "Treg e Th2", "Th1 e Th17", "Th17 e Tfh", "Tfh e Treg"], "gabarito": "C", "justificativa": "Th1 produz IFN-gama e ativa macrófagos; Th17 produz IL-17 e recruta neutrófilos (Aula 1, slide 19).", "tecnica": "Subpopulações de T CD4+", "slide": 19, "pdf": "pdf/thiago/aula-01.pdf"}, {"id": 8, "nivel": "muito_dificil", "enunciado": "Uma infecção viral é controlada pela eliminação das células infectadas. Qual célula realiza essa função, qual molécula de MHC ela reconhece e qual é o alvo?", "alternativas": ["CTL CD8+, reconhece MHC de classe I e mata a célula infectada", "NK, reconhece MHC de classe II e destrói macrófagos infectados", "Th1, reconhece MHC de classe I e ativa macrófagos do foco", "Treg, reconhece MHC de classe II e suprime a infecção viral", "B de memória, reconhece MHC de classe I e secreta IgA local"], "gabarito": "A", "justificativa": "CTLs CD8+ eliminam microrganismos intracelulares pela morte das células infectadas e reconhecem antígenos em MHC de classe I (Aula 1, slide 20).", "tecnica": "CTL CD8+", "slide": 20, "pdf": "pdf/thiago/aula-01.pdf"}, {"id": 9, "nivel": "muito_dificil", "enunciado": "Uma lesão tecidual persiste por semanas, com macrófagos e linfócitos no foco e a infecção não foi eliminada. Qual fenômeno a aula descreve e qual é o seu princípio?", "alternativas": ["Inflamação aguda prolongada, que se mantém só por neutrófilos de vida curta", "Inflamação crônica, pela persistência da lesão ou infecção", "Imunidade inata isolada, que se mantém sem citocinas e sem linfócitos", "Hipersensibilidade tipo I, mantida por IgE no tecido lesado", "Imunidade adaptativa sem memória, com troca de isótipo no foco"], "gabarito": "B", "justificativa": "A inflamação crônica substitui a aguda se a infecção não for eliminada ou a lesão tecidual se prolongar (Aula 1, slide 10).", "tecnica": "Inflamação aguda × crônica", "slide": 10, "pdf": "pdf/thiago/aula-01.pdf"}, {"id": 10, "nivel": "muito_dificil", "enunciado": "Uma célula dendrítica captura um antígeno no tecido. Para qual órgão ela migra para ativar linfócitos virgens, e qual é a razão funcional desse trajeto?", "alternativas": ["Medula óssea, onde a DC é produzida e recebe o antígeno da corrente sanguínea", "Timo, onde a DC seleciona o linfócito antes que ele chegue à periferia", "Baço, única via de acesso da DC ao sangue circulante para apresentação", "Linfonodo, órgão secundário, onde a apresentação ocorre a linfócitos virgens", "MALT, que dispensa a migração da DC ao linfonodo para a apresentação"], "gabarito": "D", "justificativa": "Os órgãos linfoides secundários são onde as APCs apresentam antígeno aos linfócitos virgens (Aula 1, slide 5; Abbas).", "tecnica": "Órgãos secundários", "slide": 5, "pdf": "pdf/thiago/aula-01.pdf"}, {"id": 11, "nivel": "muito_dificil", "enunciado": "Um leucograma mostra aumento de neutrófilos e de bastões em paciente febril. Segundo a aula, o que esse exame avalia e por que ele importa para interpretar a defesa?", "alternativas": ["A concentração de IgE sérica, que define a intensidade da alergia do paciente", "A integridade dos linfonodos palpáveis, que reflete a presença de tumor", "A barreira epitelial da pele, que depende do número de mastócitos locais", "A reação de hipersensibilidade tipo IV, medida pela contagem de linfócitos T", "Os leucócitos, que refletem a defesa celular"], "gabarito": "E", "justificativa": "O leucograma avalia os leucócitos, responsáveis pela defesa imunológica do organismo (Aula 1, slide 6).", "tecnica": "Leucograma", "slide": 6, "pdf": "pdf/thiago/aula-01.pdf"}, {"id": 12, "nivel": "muito_dificil", "enunciado": "Uma bactéria Gram-negativa é reconhecida pela imunidade inata via TLR4. Qual componente da parede é o PAMP, e por que essa classificação importa para diferenciar infecção de dano estéril?", "alternativas": ["HMGB1, DAMP liberado por morte celular; diferencia infecção de dano estéril", "LPS, PAMP microbiano de Gram-negativos", "Histonas, DAMP nuclear; diferencia infecção viral de bacteriana no tecido", "ATP extracelular, DAMP de célula lesada; diferencia trauma de queimadura", "Citocromo c, DAMP mitocondrial; diferencia infecção fúngica de bacteriana"], "gabarito": "B", "justificativa": "LPS e ácido lipoteicoico são PAMPs da parede celular bacteriana; DAMPs se originam do próprio dano (Aula 1, slide 8).", "tecnica": "PAMPs", "slide": 8, "pdf": "pdf/thiago/aula-01.pdf"}, {"id": 13, "nivel": "muito_dificil", "enunciado": "Qual é a diferença essencial entre o primeiro e o segundo contato com um antígeno na resposta adaptativa?", "alternativas": ["O segundo contato ativa células de memória, com resposta mais rápida e intensa", "O segundo contato não ativa linfócitos, pois a memória dispensa qualquer antígeno", "O segundo contato ativa somente a imunidade inata, sem nenhuma especificidade", "O segundo contato gera apenas IgM, pois a troca de isótipo é bloqueada", "O segundo contato é idêntico ao primeiro, sem diferença de tempo nem intensidade"], "gabarito": "A", "justificativa": "A memória adaptativa acelera e intensifica a resposta no reencontro do antígeno (Aula 1, slide 7; Abbas).", "tecnica": "Memória adaptativa", "slide": 7, "pdf": "pdf/thiago/aula-01.pdf"}, {"id": 14, "nivel": "muito_dificil", "enunciado": "Uma célula B troca de isótipo durante uma resposta. Qual é a consequência esperada para as funções efetoras do anticorpo, pela aula?", "alternativas": ["Todos os isótipos realizam exatamente a mesma função efetora", "A troca de isótipo elimina a capacidade de ligar o antígeno original", "A troca de isótipo ocorre somente na forma de membrana da célula", "A troca de isótipo altera apenas a região variável do anticorpo", "Diferentes isótipos realizam funções efetoras distintas"], "gabarito": "E", "justificativa": "Diferentes isótipos realizam funções efetoras distintas (Aula 1, slide 15).", "tecnica": "Funções efetoras", "slide": 15, "pdf": "pdf/thiago/aula-01.pdf"}, {"id": 15, "nivel": "muito_dificil", "enunciado": "Três citocinas são citadas na aula como centrais na inflamação aguda. Qual conjunto é o correto e qual é a função dessas citocinas no foco inflamatório?", "alternativas": ["IL-4, IL-5 e IL-13, que promovem inflamação eosinofílica de fase tardia", "IL-10 e TGF-beta, que promovem inflamação e recrutamento de neutrófilos", "IFN-alfa e IFN-beta, que promovem apenas efeito antiviral sem inflamação", "IL-2 e IL-7, que promovem a diferenciação de mastócitos no tecido inflamado", "TNF, IL-1 e IL-6, que promovem inflamação e ativação do endotélio"], "gabarito": "E", "justificativa": "TNF, IL-1 e IL-6 são citocinas pró-inflamatórias centrais (Aula 1, slide 11).", "tecnica": "Citocinas inflamatórias", "slide": 11, "pdf": "pdf/thiago/aula-01.pdf"}], "id": "imuno-thiago-01", "titulo": "Aula 1", "voltar": {"href": "#/agressao/thiago", "texto": "Professor Thiago"}, "manobras": [], "imagens": [], "casos_extremos": []};
window.AULAS["imuno-thiago-02"] = {"subtitulo": "Diagnóstico imunológico", "pdf": "pdf/thiago/aula-02.pdf", "abas": ["resumo", "glossario", "quiz", "pdf"], "fontes": ["Aula 2 · Diagnóstico Imunológico (Prof. Dr. Thiago Corrêa)", "Barardi, 2010 (citado nos slides); Cinquanta et al., 2017; Tate e Ward, 2004 (referências da aula)"], "resumo": [{"titulo": "1. Por que sorologia e imunodiagnóstico", "pontos": [{"t": "Princípio", "sub": ["Sorologia é o exame que comprova a presença de anticorpos e/ou antígenos no sangue ou soro (slide 16). Toda técnica usa a mesma base: a ligação antígeno-anticorpo, revelada por um marcador.", "Uso principal: descobrir se o paciente teve contato com um agente infeccioso (slide 17). Um resultado positivo mostra exposição, mas não diz se a infecção está ativa."]}, {"t": "Janela imunológica", "sub": ["É o intervalo entre a infecção e o momento em que antígenos ou anticorpos atingem níveis detectáveis (slide 21).", "Um teste negativo no início não exclui a doença; a conduta é repetir o exame após a janela.", "Nota de revisão: o item V do slide 21 fala em risco de falso-positivo; clinicamente o risco da janela é o falso-negativo. Confirme com a turma."]}]}, {"titulo": "2. Técnicas de imunodiagnóstico", "pontos": [{"t": "Imunofluorescência indireta (IFI)", "sub": ["Soro do paciente é aplicado sobre o antígeno fixado; depois entra uma anti-imunoglobulina marcada com fluorocromo (slide 5).", "Aplicações: toxoplasmose, sífilis, doença de Chagas, anti-DNA (LES) e anticorpos antitireoide (slide 5)."]}, {"t": "ELISA", "sub": ["Antígenos ou anticorpos ficam adsorvidos à placa. Alta sensibilidade, alta especificidade e custo baixo (slide 6).", "ELISA indireto: anticorpo primário, depois anti-imunoglobulina conjugada à enzima; a enzima transforma o substrato em cromógeno colorido (slide 7).", "ELISA sanduíche: o anticorpo fixado captura o antígeno; outro anticorpo, ligado à enzima, o detecta (slide 9). É o mais específico porque exige dois sítios de reconhecimento.", "Pesquisas listadas: doenças autoimunes, alergias, Chagas, HIV, gravidez, T3, T4, marcadores tumorais e doenças infecciosas (slide 6)."]}, {"t": "CLIA (quimioluminescência)", "sub": ["Dosa antígenos ou anticorpos do paciente pela luz emitida em reação química (slides 10 e 11). Mais sensível e quantitativo."]}, {"t": "Imunocromatografia de fluxo lateral", "sub": ["Teste rápido em tira, com leitura visual, como o de COVID-19 citado (slide 12). Serve para triagem de beira de leito."]}, {"t": "Citometria de fluxo", "sub": ["As células são marcadas com fluorocromos e passam uma a uma por um feixe de luz; o aparelho identifica, quantifica e separa cada população (slide 13).", "Aplicações: leucemia linfocítica crônica, linfomas B e T, síndromes mielodisplásicas e caracterização de imunodeficiências (slide 14)."]}]}, {"titulo": "3. Como avaliar um teste", "pontos": [{"t": "Sensibilidade e especificidade", "sub": ["Sensibilidade: fração dos doentes que o teste identifica (slide 19). Especificidade: fração dos não doentes que o teste identifica como negativos (slide 19).", "Trade-off: aumentar a sensibilidade costuma reduzir a especificidade e gerar mais falsos positivos. O banco de sangue prefere alta sensibilidade para não liberar sangue contaminado (aplicação de triagem).", "Valores preditivos dependem da prevalência da doença, e não só dos dois parâmetros (complementa Abbas)."]}, {"t": "Fatores interferentes", "sub": ["Substâncias do paciente ou da amostra alteram o resultado sem relação com a doença. Reconhecê-las é essencial para interpretar corretamente (slide 20).", "Exemplos clássicos em imunoensaios: anticorpos heterófilos, fator reumatoide e biotina em altas doses (complementa a literatura de interferências)."]}]}, {"titulo": "4. Qual técnica usar", "pontos": [{"t": "Escolha prática", "sub": ["Triagem em grande escala e custo baixo: ELISA.", "Caracterização celular, leucemias, linfomas e imunodeficiências: citometria de fluxo.", "Confirmação de anticorpo específico (ex.: HIV): Western blotting, após triagem positiva (complementa Manual do Ministério da Saúde)."]}, {"t": "Para aprofundar", "sub": ["Barardi (2010) e Abbas, Lichtman e Pillai (2023), citados nos slides.", "Brasil, Ministério da Saúde, Manual técnico de diagnóstico do HIV (orientação oficial de confirmação sorológica)."]}]}, {"titulo": "5. Para prova", "pontos": [{"t": "Pontos de cobrança", "sub": ["Diferença entre ELISA indireto e sanduíche.", "Sensibilidade × especificidade e o efeito de mudar um deles.", "Janela imunológica e o que fazer com resultado negativo precoce.", "Técnica certa para cada situação clínica."]}]}], "glossario": [{"termo": "Sorologia", "tecnica": "Conceito geral", "definicao": "Exame que comprova a presença de anticorpos e/ou antígenos no sangue ou no soro.", "slide": 16}, {"termo": "Sensibilidade", "tecnica": "Parâmetro de imunoensaio", "definicao": "Capacidade do teste de identificar corretamente quem realmente tem a doença.", "slide": 19}, {"termo": "Especificidade", "tecnica": "Parâmetro de imunoensaio", "definicao": "Capacidade do teste de identificar corretamente quem não tem a doença.", "slide": 19}, {"termo": "Janela imunológica", "tecnica": "Interpretação sorológica", "definicao": "Intervalo após a infecção em que antígenos ou anticorpos ainda não atingem níveis detectáveis.", "slide": 21}, {"termo": "ELISA sanduíche", "tecnica": "Teste imunoenzimático", "definicao": "Anticorpo imobilizado na placa captura o antígeno da amostra; outro anticorpo ligado à enzima o detecta.", "slide": 9}, {"termo": "Imunocromatografia de fluxo lateral", "tecnica": "Teste rápido", "definicao": "Técnica de teste rápido usada no teste de sangue para COVID-19 citado na aula.", "slide": 12}, {"termo": "Citometria de fluxo", "tecnica": "Análise celular", "definicao": "Identifica, caracteriza, quantifica e seleciona células marcadas com substâncias fluorescentes.", "slide": 13}, {"termo": "Imunofluorescência indireta (IFI)", "tecnica": "Técnica", "definicao": "Soro do paciente é aplicado sobre antígeno fixado, seguido de anti-imunoglobulina marcada. Usada em toxoplasmose, sífilis, Chagas e anti-DNA.", "slide": 5}, {"termo": "Anticorpo monoclonal", "tecnica": "Reagente", "definicao": "Anticorpo idêntico, de um único clone. Gera menos reações cruzadas que os policlonais.", "slide": 4}, {"termo": "ELISA indireto", "tecnica": "Técnica", "definicao": "Usa anticorpo primário, anti-imunoglobulina conjugada à enzima, substrato e cromógeno.", "slide": 7}, {"termo": "CLIA (quimioluminescência)", "tecnica": "Técnica", "definicao": "Imunoensaio que mede a luz emitida por reação química. Usado para antígenos e anticorpos do paciente.", "slide": 10}, {"termo": "Fatores interferentes", "tecnica": "Parâmetro", "definicao": "Substâncias que alteram o resultado, como biotina em altas doses, que pode gerar falso-positivo.", "slide": 20}], "caso": {"titulo": "Caso: sorologia em paciente com sintomas recentes", "perfil": "Janela imunológica, sensibilidade e especificidade do exame.", "etapas": [{"titulo": "Etapa 1: exame precoce", "texto": "Paciente com sintomas há 3 dias procura o laboratório. A sorologia para IgM e IgG não é reagente. O médico pergunta se o exame descarta a infecção.", "perguntas": [{"pergunta": "Qual conclusão é mais adequada, considerando a janela imunológica?", "alts": ["O exame não descarta infecção, pois os anticorpos podem ainda não ser detectáveis", "O exame descarta a infecção, pois IgM e IgG não reagentes excluem doença", "O exame confirma a infecção, pois IgG negativo indica infecção aguda", "O exame indica imunidade, pois anticorpos ausentes mostram proteção", "O exame só é válido após 60 dias, independentemente dos sintomas"], "erradas": ["IgM e IgG não reagentes em fase precoce não excluem infecção.", "IgG negativo não confirma infecção aguda.", "Ausência de anticorpos não indica imunidade.", "A janela imunológica não exige 60 dias de espera."], "justificativa": "A janela imunológica é o intervalo em que os níveis ainda não são detectáveis (slide 21). Por isso o resultado precoce não descarta a infecção."}]}, {"titulo": "Etapa 2: escolha do teste", "texto": "Um banco de sangue precisa de um teste que quase nunca deixe de identificar um doador infectado. O laboratório avalia duas opções.", "perguntas": [{"pergunta": "Qual consequência prática um teste com sensibilidade próxima de 100% tende a ter?", "alts": ["Maior número de resultados positivos em pessoas sem a doença", "Maior número de pessoas doentes classificadas como negativas", "Aumento da especificidade, com menos resultados falsos positivos", "Redução da janela imunológica do exame, sem outras mudanças", "Aumento da confiança em todos os resultados, sem perda de desempenho"], "erradas": ["Maior sensibilidade pode gerar mais positivos em pessoas sem a doença.", "Mais falsos negativos é o oposto do que se busca com sensibilidade alta.", "Sensibilidade alta não aumenta a especificidade.", "A janela imunológica não depende da sensibilidade do teste."], "justificativa": "Sensibilidade alta identifica quem tem a doença, mas pode reduzir a especificidade (slide 19)."}]}]}, "questoes": [{"id": 1, "nivel": "muito_dificil", "enunciado": "Um paciente tem sintomas há três dias. IgM e IgG são não reagentes. Pela aula, qual é a conduta correta diante desse resultado?", "alternativas": ["Descartar a infecção, pois a ausência de anticorpos detectáveis exclui doença ativa", "Confirmar a infecção crônica, pois IgG negativo indica persistência do agente", "Indicar imunidade adquirida, pois anticorpos ausentes mostram proteção definitiva", "Repetir o exame após a janela imunológica", "Considerar falso-positivo, pois o exame só é válido após sessenta dias"], "gabarito": "D", "justificativa": "A janela imunológica é o intervalo em que antígenos ou anticorpos ainda não são detectáveis; por isso o resultado precoce não descarta infecção (Aula 2, slide 21).", "tecnica": "Janela imunológica", "slide": 21, "pdf": "pdf/thiago/aula-02.pdf"}, {"id": 2, "nivel": "muito_dificil", "enunciado": "Um teste deve identificar a maior proporção possível de doentes, mesmo que gere mais falsos positivos. Qual parâmetro está sendo maximizado e qual é a consequência prática?", "alternativas": ["Sensibilidade, com queda da especificidade e mais positivos em pessoas sem a doença", "Especificidade, com queda da sensibilidade e mais doentes classificados como negativos", "Sensibilidade, sem alteração da especificidade, porque os dois parâmetros são independentes", "Especificidade, com aumento da janela imunológica do exame realizado no paciente", "Sensibilidade, com aumento automático do valor preditivo negativo do exame em qualquer cenário"], "gabarito": "A", "justificativa": "Sensibilidade identifica quem tem a doença; aumentá-la costuma reduzir a especificidade, com mais falsos positivos (Aula 2, slide 19).", "tecnica": "Sensibilidade e especificidade", "slide": 19, "pdf": "pdf/thiago/aula-02.pdf"}, {"id": 3, "nivel": "muito_dificil", "enunciado": "No ELISA sanduíche, um antígeno de uma amostra é detectado com sinal fraco. Qual componente da placa é responsável por capturar especificamente o antígeno?", "alternativas": ["Substrato e cromógeno, que se ligam diretamente ao antígeno da amostra", "Anti-imunoglobulina conjugada à enzima, que captura o antígeno da amostra", "Anticorpo primário aplicado após a revelação com cromógeno na placa", "Fluorocromo que marca o antígeno antes da lavagem da placa de ensaio", "Anticorpo imobilizado na placa, que captura o antígeno da amostra"], "gabarito": "E", "justificativa": "No ELISA sanduíche, o anticorpo imobilizado captura o antígeno; o segundo anticorpo, ligado à enzima, faz a detecção (Aula 2, slide 9).", "tecnica": "ELISA sanduíche", "slide": 9, "pdf": "pdf/thiago/aula-02.pdf"}, {"id": 4, "nivel": "muito_dificil", "enunciado": "Um laboratório precisa de triagem barata com alta sensibilidade e especificidade para muitas doenças. Qual técnica a aula recomenda, e por que a imunocromatografia não é a escolha para esse fim?", "alternativas": ["Imunocromatografia, por ser mais sensível que o ELISA em todas as amostras clínicas", "Citometria, por ser a técnica de menor custo para triagem populacional em massa", "ELISA, com alta sensibilidade e custo baixo", "Imunofluorescência indireta, por ser automatizada e dispensar leitura por técnico", "CLIA, por ser um teste visual de fita, sem necessidade de equipamento específico"], "gabarito": "C", "justificativa": "O ELISA tem alta sensibilidade, especificidade e custo baixo (Aula 2, slide 6); a imunocromatografia é um teste rápido em tira (slide 12).", "tecnica": "Escolha de técnica", "slide": 6, "pdf": "pdf/thiago/aula-02.pdf"}, {"id": 5, "nivel": "muito_dificil", "enunciado": "Um paciente com suspeita de leucemia linfocítica crônica precisa de caracterização celular. Qual técnica a aula indica e como as células são preparadas?", "alternativas": ["Imunofluorescência indireta, com soro do paciente aplicado sobre lâmina fixada", "Citometria de fluxo, com células marcadas", "ELISA indireto, com anticorpo secundário conjugado à enzima sobre a placa", "Imunocromatografia, com tira de fluxo lateral e leitura visual do resultado", "CLIA, com quimioluminescência do antígeno tumoral dosado no soro do paciente"], "gabarito": "B", "justificativa": "A citometria identifica e caracteriza células marcadas com fluorocromos, com indicação em leucemias e linfomas (Aula 2, slides 13 e 14).", "tecnica": "Citometria de fluxo", "slide": 14, "pdf": "pdf/thiago/aula-02.pdf"}, {"id": 6, "nivel": "muito_dificil", "enunciado": "Um laboratório troca um anticorpo policlonal por monoclonal em um kit. Qual vantagem a aula atribui a essa troca, e qual limitação o monoclonal ainda pode ter?", "alternativas": ["Maior sensibilidade a qualquer epítopo; não sofre interferência de amostra alguma", "Menor custo de produção; reconhece todas as variantes do antígeno circulante", "Menor especificidade; dispensa controle de qualidade do lote de reagente", "Maior especificidade e menor reação cruzada", "Maior janela imunológica; reduz falsos negativos durante a fase aguda da doença"], "gabarito": "D", "justificativa": "Monoclonais reconhecem um único epítopo, reduzindo reações cruzadas; a restrição a um epítopo é a limitação clássica (Aula 2, slide 23, questão 7).", "tecnica": "Anticorpos monoclonais", "slide": 23, "pdf": "pdf/thiago/aula-02.pdf"}, {"id": 7, "nivel": "muito_dificil", "enunciado": "A IFI é positiva, mas o ELISA da mesma amostra é negativo. Qual etapa diferente entre as técnicas explica melhor a discordância?", "alternativas": ["Concentração do cromógeno, que é igual nas duas técnicas comparadas", "Preparo do antígeno e sistema de revelação", "Uso de citometria, aplicada somente na IFI da mesma amostra clínica", "Ausência de anti-imunoglobulina no ELISA indireto da amostra analisada", "Idade do paciente, que altera apenas a janela imunológica do exame"], "gabarito": "B", "justificativa": "A IFI usa fluorocromo sobre lâmina; o ELISA usa enzima e cromógeno sobre placa (Aula 2, slides 5 a 7).", "tecnica": "Comparação de técnicas", "slide": 5, "pdf": "pdf/thiago/aula-02.pdf"}, {"id": 8, "nivel": "muito_dificil", "enunciado": "Qual é a diferença entre a interpretação de um exame qualitativo e a de um quantitativo de anticorpos, segundo a aula?", "alternativas": ["O qualitativo mede a concentração; o quantitativo indica apenas presença ou ausência", "Ambos dão somente resultado de presença, sem nenhuma informação sobre concentração", "O quantitativo dispensa o controle da janela imunológica da coleta realizada", "Qualitativo: presença; quantitativo: concentração", "O qualitativo só é possível com citometria de fluxo aplicada ao soro do paciente"], "gabarito": "D", "justificativa": "A aula diferencia presença e quantificação; ELISA e CLIA permitem quantificação (Aula 2, slides 6 e 10).", "tecnica": "Interpretação de resultados", "slide": 10, "pdf": "pdf/thiago/aula-02.pdf"}, {"id": 9, "nivel": "muito_dificil", "enunciado": "Um paciente em uso de anticoagulante tem resultado de teste falsamente elevado. Qual categoria de interferência a aula cita, e por que ela deve ser reconhecida?", "alternativas": ["Janela imunológica, que é um erro de tempo e não de medição laboratorial do exame", "Sensibilidade do teste, que o laboratório ajusta a cada coleta individual do paciente", "Fatores interferentes, que alteram o resultado", "Especificidade, que não é afetada por nenhuma substância presente na amostra clínica", "Citometria, que elimina qualquer interferência do plasma na amostra analisada"], "gabarito": "C", "justificativa": "O reconhecimento dos fatores interferentes é essencial para interpretar corretamente os resultados (Aula 2, slide 20).", "tecnica": "Fatores interferentes", "slide": 20, "pdf": "pdf/thiago/aula-02.pdf"}, {"id": 10, "nivel": "muito_dificil", "enunciado": "Qual é o principal uso do exame sorológico, segundo a aula, e qual limite ele tem?", "alternativas": ["Medir a carga viral atual do paciente, com resposta imediata ao tratamento instituído", "Determinar se houve contato com o agente", "Definir o grupo sanguíneo ABO antes de transfusão, com alta precisão diagnóstica", "Avaliar a deficiência de imunoglobulina nas mucosas, sem relação com infecção", "Verificar se a imunidade celular está preservada, independente do anticorpo medido"], "gabarito": "B", "justificativa": "O principal uso do exame sorológico é determinar se houve contato com agente infeccioso (Aula 2, slide 17); o anticorpo não mede atividade atual.", "tecnica": "Sorologia", "slide": 17, "pdf": "pdf/thiago/aula-02.pdf"}, {"id": 11, "nivel": "muito_dificil", "enunciado": "Qual parâmetro de imunoensaio mede a capacidade de identificar corretamente quem NÃO tem a doença, e qual é o parâmetro complementar?", "alternativas": ["Sensibilidade; o complementar é a especificidade", "Janela imunológica; o complementar é o fator interferente", "Cromógeno; o complementar é o substrato enzimático", "Título; o complementar é a concentração do antígeno", "Especificidade; o complementar é a sensibilidade"], "gabarito": "E", "justificativa": "Especificidade identifica quem não tem a doença; sensibilidade identifica quem tem (Aula 2, slide 19).", "tecnica": "Parâmetros de imunoensaios", "slide": 19, "pdf": "pdf/thiago/aula-02.pdf"}, {"id": 12, "nivel": "muito_dificil", "enunciado": "A aula cita um método com enzima e substrato muito usado na triagem de autoimunidade, de alergias e de infecções. Qual é esse método?", "alternativas": ["Citometria de fluxo", "Imunocromatografia de fluxo lateral", "ELISA", "Western blotting", "Imunofluorescência direta com fluorocromo"], "gabarito": "C", "justificativa": "O ELISA é usado para autoimunidade, alergias, HIV e doenças virais, entre outras (Aula 2, slide 6).", "tecnica": "ELISA", "slide": 6, "pdf": "pdf/thiago/aula-02.pdf"}, {"id": 13, "nivel": "muito_dificil", "enunciado": "Um laboratório mede a luz emitida após reação química, em vez de absorbância. Qual técnica da aula corresponde a esse princípio?", "alternativas": ["Imunoensaio por quimioluminescência (CLIA)", "Imunofluorescência indireta com soro sobre lâmina", "ELISA indireto com cromógeno visível na placa", "Imunocromatografia de fluxo lateral em tira", "Citometria de fluxo com células marcadas"], "gabarito": "A", "justificativa": "O CLIA usa quimioluminescência para dosar antígenos ou anticorpos do paciente (Aula 2, slides 10 e 11).", "tecnica": "CLIA", "slide": 10, "pdf": "pdf/thiago/aula-02.pdf"}, {"id": 14, "nivel": "muito_dificil", "enunciado": "Quais são as etapas do ELISA indireto, na ordem descrita pela aula?", "alternativas": ["Anticorpo imobilizado, depois amostra, depois anticorpo ligado à enzima, depois substrato", "Amostra fluorescente, depois anti-imunoglobulina marcada, depois lavagem sem substrato", "Substrato, depois cromógeno, depois anticorpo primário aplicado sobre a placa", "Anti-imunoglobulina, depois antígeno fixado, depois leitura por citometria de fluxo", "Anticorpo primário, anti-imunoglobulina conjugada, substrato"], "gabarito": "E", "justificativa": "No ELISA indireto há anticorpo primário, anti-imunoglobulina conjugada, substrato e cromógeno (Aula 2, slide 7).", "tecnica": "ELISA indireto", "slide": 7, "pdf": "pdf/thiago/aula-02.pdf"}, {"id": 15, "nivel": "muito_dificil", "enunciado": "Uma amostra de soro tem anticorpos antinucleares. Qual exame da aula pesquisa anti-DNA no LES por fluorescência?", "alternativas": ["IFI, que pesquisa anti-DNA no LES", "ELISA sanduíche de antígeno de superfície celular", "Citometria de fluxo de linfócitos T CD8+ do paciente", "Imunocromatografia de fluxo lateral para HIV", "CLIA para dosagem de IgA secretora"], "gabarito": "A", "justificativa": "A IFI pesquisa anti-DNA (LES), entre toxoplasmose, sífilis, Chagas e antitireoide (Aula 2, slide 5).", "tecnica": "Imunofluorescência indireta", "slide": 5, "pdf": "pdf/thiago/aula-02.pdf"}], "id": "imuno-thiago-02", "titulo": "Aula 2", "voltar": {"href": "#/agressao/thiago", "texto": "Professor Thiago"}, "manobras": [], "imagens": [], "casos_extremos": []};
window.AULAS["imuno-thiago-03"] = {"subtitulo": "Imunodeficiências congênitas (erros inatos da imunidade)", "pdf": "pdf/thiago/aula-03.pdf", "abas": ["resumo", "glossario", "quiz", "pdf"], "fontes": ["Aula 3 · Imunodeficiências Congênitas (Prof. Dr. Thiago Corrêa)", "Abbas, Lichtman e Pillai (2019); Vieira et al. (2012); ASBAI (2023) (citados nos slides)"], "resumo": [{"titulo": "1. Erros inatos da imunidade (EII)", "pontos": [{"t": "Conceito", "sub": ["São mais de 480 doenças raras, de base genética, que comprometem o sistema imune (slide 2).", "Manifestam-se por maior suscetibilidade a infecções, muitas vezes por oportunistas, recorrentes, graves e de difícil tratamento (slide 3).", "Cada defeito atinge um componente diferente: fagócitos, adesão, linfócitos T, linfócitos B ou sinalização de citocinas. Essa é a lógica para classificar."]}, {"t": "Sinais de alerta", "sub": ["A presença de um ou mais sinais de alerta indica investigação imunológica (slide 18).", "Fonte: ASBAI (2023) e Vieira et al. (2012), citados no slide 19."]}]}, {"titulo": "2. Defeitos dos fagócitos: doença granulomatosa crônica", "pontos": [{"t": "Mecanismo", "sub": ["Mutação em componentes do complexo oxidase dos fagócitos (phox). Sem o complexo, o fagócito não produz o ânion superóxido (slide 5).", "Sem a explosão oxidativa, o macrófago não destrói o que engole e tenta isolar o material. Assim se forma o granuloma (slide 6).", "Granuloma: agregado de macrófagos que tenta isolar substâncias que o organismo não consegue eliminar (slide 6)."]}]}, {"titulo": "3. Defeito de adesão", "pontos": [{"t": "LAD tipo 1", "sub": ["Doença autossômica recessiva com expressão reduzida ou ausente de integrinas (moléculas de adesão de leucócitos e endotélio) (slide 7).", "Sem integrinas, o neutrófilo não consegue aderir ao endotélio e sair para o tecido. O resultado é infecção sem acúmulo de pus, com recrutamento ausente."]}]}, {"titulo": "4. SCID: imunodeficiências combinadas graves", "pontos": [{"t": "Quadro geral", "sub": ["Prejuízo da imunidade humoral e da mediada por células (slide 8). Sem tratamento, a criança costuma morrer nos primeiros anos por infecções graves.", "Por isso a SCID é a imunodeficiência que mais se beneficia de triagem neonatal (aula 3, questão de triagem)."]}, {"t": "Defeito da cadeia gama comum (γc)", "sub": ["γc é parte dos receptores de IL-2, IL-4, IL-7, IL-9 e IL-15 (slide 9).", "Sem γc, a sinalização de IL-7 falha e os T não amadurecem; a falta de IL-15 impede o desenvolvimento das NK (slide 9)."]}, {"t": "SCID ligada ao X (menino da bolha)", "sub": ["Ausência quase completa de T e NK, com função das células B prejudicada, mesmo quando o número de B é normal (slide 11).", "Ponto de prova: célula B presente não significa anticorpo funcionante; sem ajuda de T, a B não produz anticorpo de alta qualidade."]}]}, {"titulo": "5. Deficiências de anticorpos", "pontos": [{"t": "Agamaglobulinemia de Bruton", "sub": ["Ausência de gamaglobulinas no sangue por defeito da tirosina quinase de Bruton (BTK). A célula B não amadurece (slide 12).", "Epônimo: Bruton. Herança ligada ao X, com início de infecções após os primeiros meses de vida quando os anticorpos maternos caem (complementa Abbas)."]}, {"t": "Deficiência seletiva de IgA", "sub": ["É a deficiência de anticorpo mais comum; afeta cerca de 1 em 700 caucasianos (slide 13).", "Critério: IgA sérica abaixo de 50 μg/mL, com normal de 2 a 4 mg/mL (slide 13). Muitas pessoas são assintomáticas."]}]}, {"titulo": "6. Síndrome da hiper-IgM", "pontos": [{"t": "Mecanismo", "sub": ["Deficiência de CD40 ligante na célula T. O CD40L é o sinal que a T dá à B para trocar de isótipo (slide 14).", "Sem o sinal, a B só produz IgM. Por isso o nível de IgM está alto e o de IgG, IgA e IgE está baixo."]}, {"t": "Quadro clínico", "sub": ["Infecções piogênicas (H. influenzae e S. pneumoniae), anemia perniciosa e hemolítica, enteropatia inflamatória, artrite, tumores malignos (slide 15)."]}]}, {"titulo": "7. Investigação e tratamento", "pontos": [{"t": "Investigação", "sub": ["Exames de triagem e testes funcionais específicos (slide 19).", "Triagem neonatal por TREC e KREC para SCID, realizada antes de vacinas vivas (slide 23, questão 9)."]}, {"t": "Tratamento", "sub": ["Terapia gênica experimental restaurou e manteve a função imune em 59 de 62 crianças com ADA-SCID (slide 21).", "Reposição de imunoglobulina nas deficiências de anticorpos, com troca periódica (complementa Abbas)."]}]}], "glossario": [{"termo": "DGC (doença granulomatosa crônica)", "tecnica": "Distúrbio congênito dos fagócitos", "definicao": "Defeito no complexo oxidase (phox) com produção defeituosa do ânion superóxido.", "slide": 5}, {"termo": "Granuloma", "tecnica": "Resposta à inflamação crônica", "definicao": "Agregado de macrófagos que tenta isolar substâncias que o organismo não consegue eliminar.", "slide": 6}, {"termo": "LAD tipo 1", "tecnica": "Defeito de adesão leucocitária", "definicao": "Deficiência de adesão leucocitária com expressão reduzida ou ausente das integrinas.", "slide": 7}, {"termo": "SCID", "tecnica": "Imunodeficiência combinada grave", "definicao": "Prejuízo da imunidade humoral e mediada por células, com defeitos como a cadeia gama comum.", "slide": 8}, {"termo": "Cadeia gama comum (γc)", "tecnica": "Sinalização de citocinas", "definicao": "Cadeia dos receptores de IL-2, IL-4, IL-7, IL-9 e IL-15; mutações causam SCID.", "slide": 9}, {"termo": "Agamaglobulinemia de Bruton", "tecnica": "Deficiência de anticorpos", "definicao": "Ausência de gamaglobulinas no sangue.", "slide": 12, "epônimo": "Bruton"}, {"termo": "Síndrome da hiper-IgM", "tecnica": "Defeito de ativação da célula B", "definicao": "Falha na troca de isotipo por deficiência de CD40 ligante.", "slide": 14}, {"termo": "Agamaglobulinemia de Bruton (epônimo: Bruton)", "tecnica": "Epônimo", "definicao": "Deficiência de anticorpos ligada ao X, por defeito de BTK; leva ao bloqueio da maturação das células B.", "slide": 12, "epônimo": "Bruton"}, {"termo": "SCID ligada ao X (menino da bolha)", "tecnica": "Imunodeficiência", "definicao": "Defeito ligado ao X na γc. Ausência de T e NK, com função de B prejudicada.", "slide": 1}, {"termo": "Deficiência seletiva de IgA", "tecnica": "Deficiência de anticorpos", "definicao": "Deficiência de anticorpo mais comum, cerca de 1 em 700 caucasianos. IgA sérica abaixo de 50 μg/mL.", "slide": 18}, {"termo": "CD40L", "tecnica": "Molécula", "definicao": "Sinal da célula T à B que permite a troca de isotipo.", "slide": 14}, {"termo": "TREC e KREC (triagem neonatal)", "tecnica": "Triagem", "definicao": "Marcadores de círculos de DNA de recombinação, usados na triagem neonatal para SCID.", "slide": 23}, {"termo": "Terapia gênica do ADA-SCID", "tecnica": "Tratamento", "definicao": "Restaurou e manteve a função imune em 59 de 62 crianças com ADA-SCID.", "slide": 21}, {"termo": "Sinais de alerta de erro inato", "tecnica": "Clínica", "definicao": "Presença de um ou mais sinais indica investigação imunológica.", "slide": 18}], "caso": {"titulo": "Caso: infecções recorrentes na infância", "perfil": "Defeito humoral com infecções por bactérias encapsuladas; defeito fagocitário com granulomas.", "etapas": [{"titulo": "Etapa 1: lactente com infecções recorrentes", "texto": "Lactente de 1 ano com otites e pneumonias recorrentes por Streptococcus pneumoniae e Haemophilus influenzae. Não há sinais de imunodeficiência celular grave. A imunoglobulina sérica está muito reduzida.", "perguntas": [{"pergunta": "Qual defeito imunológico explica melhor esse quadro?", "alts": ["Deficiência da imunidade humoral, com ausência ou redução de anticorpos", "Defeito de adesão leucocitária, com integrinas ausentes nos leucócitos", "Defeito do complexo phox, com superóxido reduzido nos fagócitos", "Mutação na cadeia gama comum, com ausência de células NK", "Deficiência de IgA seletiva, com níveis normais de IgG e IgM"], "erradas": ["Defeito de adesão causa infecções, mas sem a falha de anticorpos descrita.", "Defeito do phox leva a granulomas e infecções por fagócitos, não à falha de anticorpos.", "A cadeia gama comum compromete linfócitos T e NK, com quadro mais amplo.", "IgA seletiva não explica níveis muito reduzidos de todas as imunoglobulinas."], "justificativa": "A agamaglobulinemia e as deficiências de anticorpo se manifestam com infecções por bactérias encapsuladas (slides 12 e 23)."}]}, {"titulo": "Etapa 2: granulomas e fagócitos", "texto": "Adolescente com abscessos de repetição e granulomas em linfonodos. A cultura mostra infecção por catalase-positivos. O exame aponta defeito de produção de superóxido.", "perguntas": [{"pergunta": "Por que esse paciente tende a desenvolver granulomas?", "alts": ["Os macrófagos tentam isolar substâncias que não conseguem eliminar, pelo defeito do phox", "Os linfócitos B deixam de produzir IgA, levando à formação de nódulos", "A adesão leucocitária está aumentada, prendendo células no tecido", "A cadeia gama comum estimula excessivamente os linfócitos T", "As células NK destroem macrófagos, formando agregados no tecido"], "erradas": ["IgA não é o mecanismo descrito para granulomas na DGC.", "Adesão reduzida, e não aumentada, é o defeito descrito para LAD tipo 1.", "A cadeia gama comum se relaciona com SCID, não com granulomas.", "Não há destruição de macrófagos por NK descrita para granulomas."], "justificativa": "Na DGC, o defeito de superóxido leva macrófagos a formarem granulomas para isolar o que não é eliminado (slides 5 e 6)."}]}]}, "questoes": [{"id": 1, "nivel": "muito_dificil", "enunciado": "Um lactente de 9 meses com infecções por bactérias encapsuladas tem IgG muito baixa, mas a contagem de linfócitos B circulantes é normal. Pela aula, qual defeito é mais provável e por que a contagem de B não exclui o diagnóstico?", "alternativas": ["Hiper-IgM: a B existe e produz IgM em excesso, mas nunca produz IgG por falta de CD40 ligante", "Agamaglobulinemia de Bruton, por defeito de BTK", "DGC: a B é normal e o superóxido é o que falta para a produção de anticorpos", "LAD tipo 1: a B é normal, mas não sai da medula por ausência de integrinas", "SCID por falha de γc: a B é normal, mas a IL-7 impede sua maturação"], "gabarito": "B", "justificativa": "Na agamaglobulinemia de Bruton o defeito de BTK bloqueia a maturação da B mesmo com células B identificáveis; a ausência de gamaglobulinas é o critério (Aula 3, slide 12; questão 7 do slide 23).", "tecnica": "Deficiências de anticorpo", "slide": 12, "pdf": "pdf/thiago/aula-03.pdf"}, {"id": 2, "nivel": "muito_dificil", "enunciado": "Um paciente tem abscessos por catalase-positivos, granulomas no pulmão e teste de redução do superóxido anormal. Se a mutação for no complexo phox, por que os granulomas se formam mesmo sem excesso de antígeno?", "alternativas": ["Porque o superóxido em excesso ativa linfócitos B que formam imunocomplexos no pulmão", "Porque a falta de superóxido aumenta a adesão dos neutrófilos e forma agregados fixos", "Porque a IL-7 ausente faz os macrófagos proliferarem sem controle no tecido pulmonar", "Porque o CD40 ligante em falta libera IgE que cria nódulos de eosinófilos no tecido", "O macrófago não destrói e isola o material"], "gabarito": "E", "justificativa": "A DGC resulta de produção deficiente de superóxido; o macrófago não elimina o que engole e forma granuloma para isolar (Aula 3, slides 5 e 6).", "tecnica": "Doença granulomatosa crônica", "slide": 6, "pdf": "pdf/thiago/aula-03.pdf"}, {"id": 3, "nivel": "muito_dificil", "enunciado": "Uma criança tem infecções de pele com pouco pus e cicatrização umbilical tardia. Por que o neutrófilo não consegue exercer função nesse caso, segundo a aula?", "alternativas": ["Integrinas reduzidas, sem adesão ao endotélio", "Porque o superóxido está em excesso, destruindo a própria membrana do neutrófilo", "Porque o CD40 ligante impede a diferenciação do neutrófilo em macrófago no tecido", "Porque a cadeia gama comum bloqueia a produção de IL-7 pelo neutrófilo", "Porque o BTK ausente impede a produção de gamaglobulinas pelo neutrófilo local"], "gabarito": "A", "justificativa": "Na LAD tipo 1 há expressão reduzida ou ausente de integrinas nos leucócitos, prejudicando a adesão e a migração (Aula 3, slide 7).", "tecnica": "Defeitos de adesão", "slide": 7, "pdf": "pdf/thiago/aula-03.pdf"}, {"id": 4, "nivel": "muito_dificil", "enunciado": "Um lactente com SCID ligada ao X tem linfócitos B quantificados como normais, mas sem produção de anticorpos. A aula descreve quais células estão quase ausentes. Qual é o conjunto correto?", "alternativas": ["Linfócitos T e NK quase ausentes; a função das células B está prejudicada", "Linfócitos B ausentes; a função de T e NK permanece preservada no lactente", "Neutrófilos e monócitos ausentes; linfócitos T e B permanecem normais", "Eosinófilos e mastócitos ausentes; linfócitos B e T permanecem normais", "Plaquetas e hemácias ausentes; linfócitos B e NK permanecem normais"], "gabarito": "A", "justificativa": "A aula descreve ausência quase completa de T e NK, com prejuízo da função das células B (Aula 3, slide 11).", "tecnica": "SCID ligada ao X", "slide": 11, "pdf": "pdf/thiago/aula-03.pdf"}, {"id": 5, "nivel": "muito_dificil", "enunciado": "Um paciente tem IgA sérica de 20 μg/mL, IgG e IgM normais e é assintomático. Qual é o critério numérico da aula e qual é a frequência aproximada em caucasianos?", "alternativas": ["IgA abaixo de 500 μg/mL; cerca de 1 em 70 indivíduos", "IgA abaixo de 5 μg/mL; cerca de 1 em 7000 indivíduos", "IgE acima de 500 μg/mL; cerca de 1 em 700 indivíduos", "IgA abaixo de 50 mg/mL; cerca de 1 em 7 indivíduos", "IgA abaixo de 50 μg/mL; cerca de 1 em 700 indivíduos"], "gabarito": "E", "justificativa": "Deficiência seletiva de IgA: IgA abaixo de 50 μg/mL, afetando cerca de 1 em 700 caucasianos (Aula 3, slide 13).", "tecnica": "Deficiência seletiva de IgA", "slide": 13, "pdf": "pdf/thiago/aula-03.pdf"}, {"id": 6, "nivel": "muito_dificil", "enunciado": "Um adolescente tem infecções piogênicas, anemia hemolítica e enteropatia inflamatória. Ele tem IgM alta e IgG baixa. Qual é o defeito molecular e qual sinal da célula T está ausente?", "alternativas": ["Deficiência de IL-2, que é o sinal que a T dá à B para produzir IgM", "Excesso de CD40 ligante, que impede a B de produzir IgM e IgG juntos", "Deficiência de integrina, que impede a T de produzir CD40 na superfície", "Deficiência de CD40 ligante, que é o sinal que a T dá à B para trocar de isótipo", "Excesso de superóxido, que bloqueia a troca de isótipo na célula B do adolescente"], "gabarito": "D", "justificativa": "Na hiper-IgM há deficiência de CD40 ligante na célula T, com prejuízo da troca de isótipo; IgM fica alta e IgG baixa (Aula 3, slide 14).", "tecnica": "Síndrome da hiper-IgM", "slide": 14, "pdf": "pdf/thiago/aula-03.pdf"}, {"id": 7, "nivel": "muito_dificil", "enunciado": "Pela aula, um paciente com suspeita de erro inato da imunidade tem apenas um sinal de alerta isolado. Qual conduta a aula indica?", "alternativas": ["Investigação imunológica, pois um sinal de alerta já indica investigação", "Observação por seis meses, pois são necessários três sinais para investigar", "Nenhuma conduta, pois apenas a combinação de sinais justifica investigação", "Dosagem de IgE, como única investigação, antes de qualquer outra avaliação", "Vacinação com vírus vivos, para testar a resposta imune antes da investigação"], "gabarito": "A", "justificativa": "A presença de um ou mais sinais de alerta indica investigação imunológica (Aula 3, slide 18).", "tecnica": "Sinais de alerta", "slide": 18, "pdf": "pdf/thiago/aula-03.pdf"}, {"id": 8, "nivel": "muito_dificil", "enunciado": "Um recém-nascido de mãe sem doença tem suspeita de SCID e vai receber vacina viva. Qual exame a aula cita antes da vacina viva, e qual é o seu objetivo?", "alternativas": ["Dosagem de IgE sérica, para identificar anafilaxia antes da vacina inativada", "Citometria de NK, para identificar hiper-IgM antes de qualquer vacina", "Triagem neonatal por TREC e KREC", "Western blotting, para confirmar infecção por HIV antes da vacina viva", "Teste de integrinas, para confirmar LAD tipo 1 antes da vacina inativada"], "gabarito": "C", "justificativa": "A triagem neonatal por TREC e KREC é citada como medida antes de vacinas vivas (Aula 3, slide 23, questão 9).", "tecnica": "Triagem de SCID", "slide": 23, "pdf": "pdf/thiago/aula-03.pdf"}, {"id": 9, "nivel": "muito_dificil", "enunciado": "A aula cita o tratamento de ADA-SCID com terapia gênica. Qual é o número de crianças com restauração e de quantas foram tratadas?", "alternativas": ["62 de 59 crianças", "30 de 62 crianças", "59 de 95 crianças", "59 de 62 crianças", "12 de 62 crianças"], "gabarito": "D", "justificativa": "A aula cita terapia gênica com restauração em 59 de 62 crianças com ADA-SCID (Aula 3, slide 21).", "tecnica": "Tratamento das EII", "slide": 21, "pdf": "pdf/thiago/aula-03.pdf"}, {"id": 10, "nivel": "muito_dificil", "enunciado": "Um paciente com EII tem infecções graves e recorrentes por oportunistas. Qual é a classificação epidemiológica dos EII descrita na aula, e qual característica clínica decorre dela?", "alternativas": ["Mais de 48 doenças comuns adquiridas, com infecções leves e de fácil tratamento", "Mais de 4800 doenças raras, com alergias graves e urticária recorrente", "Doenças comuns de adultos, com autoimunidade sistêmica e de difícil tratamento", "Mais de 480 doenças raras, de base genética", "Doenças de origem nutricional, com infecções leves e autolimitadas na infância"], "gabarito": "D", "justificativa": "A aula descreve mais de 480 doenças raras de base genética, com maior suscetibilidade a infecções graves e de difícil tratamento (Aula 3, slides 2 e 3).", "tecnica": "Erros inatos da imunidade", "slide": 3, "pdf": "pdf/thiago/aula-03.pdf"}, {"id": 11, "nivel": "muito_dificil", "enunciado": "Um paciente com DGC desenvolve granuloma. Qual é o nome da estrutura formada pelos macrófagos e o que ela tenta fazer com o agente que não foi eliminado?", "alternativas": ["Imunocomplexo, um depósito de antígeno com anticorpo que ativa o complemento", "Folículo linfoide, um agregado de linfócitos B que produz anticorpos no tecido", "Sincício, uma fusão celular que destrói o agente e forma um tecido novo", "Abscesso, uma coleção de neutrófilos que liquefaz o tecido sem isolar o agente", "Granuloma, um agregado de macrófagos que tenta isolar o agente não eliminado"], "gabarito": "E", "justificativa": "Granuloma é um agregado de macrófagos que tenta isolar substâncias que o organismo não consegue eliminar (Aula 3, slide 6).", "tecnica": "Granuloma", "slide": 6, "pdf": "pdf/thiago/aula-03.pdf"}, {"id": 12, "nivel": "muito_dificil", "enunciado": "Um paciente tem falha de maturação de NK e de T, com defeito de sinalização de IL-7 e IL-15. Qual cadeia de receptor, comum a cinco citocinas, está mutada?", "alternativas": ["Cadeia alfa da IL-1, que faz parte dos receptores de TNF e de IL-6 nos macrófagos", "Cadeia gama comum (γc), que faz parte dos receptores de IL-2, IL-4, IL-7, IL-9 e IL-15", "Cadeia beta da IL-10, que faz parte dos receptores de TGF-beta nos linfócitos Treg", "Cadeia do CD40, que faz parte dos receptores de IFN-gama nas células dendríticas", "Cadeia da integrina beta-2, que faz parte dos receptores de quimiocina nos neutrófilos"], "gabarito": "B", "justificativa": "γc faz parte dos receptores de IL-2, IL-4, IL-7, IL-9 e IL-15; a mutação causa maturação deficiente de T (IL-7) e NK (IL-15) (Aula 3, slide 9).", "tecnica": "Sinalização de citocinas", "slide": 9, "pdf": "pdf/thiago/aula-03.pdf"}, {"id": 13, "nivel": "muito_dificil", "enunciado": "Um menino tem agamaglobulinemia. Qual padrão de herança e qual defeito molecular estão no quadro clássico descrito na aula?", "alternativas": ["Autossômica dominante, com excesso de IgE e eosinofilia periférica", "Ligada ao X, com defeito de BTK e ausência de gamaglobulinas", "Ligada ao X, com excesso de IgG por defeito da cadeia gama comum", "Autossômica recessiva, com deficiência de IgM por defeito do complexo phox", "Autossômica recessiva, com ausência de IgA por defeito de integrina"], "gabarito": "B", "justificativa": "A agamaglobulinemia de Bruton é ausência de gamaglobulinas por defeito de BTK, forma clássica ligada ao X (Aula 3, slide 12; complementa Abbas).", "tecnica": "Agamaglobulinemia", "slide": 12, "pdf": "pdf/thiago/aula-03.pdf"}, {"id": 14, "nivel": "muito_dificil", "enunciado": "Qual dado a aula cita como evidência de eficácia de uma abordagem terapêutica nas EII?", "alternativas": ["Transfusão de hemácias restaurou a função imune em todas as crianças tratadas", "Corticoide manteve a contagem de T normal em todas as crianças tratadas", "Terapia gênica restaurou a função imune em 59 de 62 crianças com ADA-SCID", "Vacinação com vírus vivos restaurou a função T em metade das crianças", "Antibioticoprofilaxia isolada eliminou todos os sinais de SCID nos pacientes"], "gabarito": "C", "justificativa": "Terapia gênica para ADA-SCID: 59 de 62 crianças (Aula 3, slide 21).", "tecnica": "Tratamento", "slide": 21, "pdf": "pdf/thiago/aula-03.pdf"}, {"id": 15, "nivel": "muito_dificil", "enunciado": "Um lactente com sinal de alerta de erro inato chega com suspeita de defeito imune. Pela aula, qual é a sequência diagnóstica, e o que ela precisa identificar antes de indicar tratamento?", "alternativas": ["Dosagem de imunoglobulinas como único exame, pois o nível sérico define o defeito e a conduta", "Biópsia de medula óssea como primeiro exame, para contar as células e definir a linhagem afetada", "Triagem laboratorial, seguida de testes funcionais específicos para identificar o defeito", "Teste de tuberculina e radiografia, já que infecções de repetição costumam ser micobacterianas", "Sorologia para HIV e, se negativa, descarte de qualquer imunodeficiência primária antes de tratar"], "gabarito": "C", "justificativa": "A investigação de EII combina exames laboratoriais de triagem com testes funcionais específicos, que identificam o componente afetado (Aula 3, slide 19). O tratamento só se define depois disso (slide 20). Os demais exames não definem o defeito.", "tecnica": "Investigação e tratamento", "slide": 19, "pdf": "pdf/thiago/aula-03.pdf"}], "id": "imuno-thiago-03", "titulo": "Aula 3", "voltar": {"href": "#/agressao/thiago", "texto": "Professor Thiago"}, "manobras": [], "imagens": [], "casos_extremos": []};
window.AULAS["imuno-thiago-04"] = {"subtitulo": "Imunodeficiências secundárias (HIV, desnutrição, obesidade e imunossupressão)", "pdf": "pdf/thiago/aula-04.pdf", "abas": ["resumo", "glossario", "quiz", "pdf"], "fontes": ["Aula 4 · Imunodeficiências Secundárias (Prof. Dr. Thiago Corrêa)", "Franchini et al. (2013), Manual técnico de diagnóstico do HIV; Ministério da Saúde (2022); Chavakis et al. (2023); Burak et al. (2024); Cain e Cidlowski (2017) (citados nos slides)", "Resumo integrado da Prova 2 (Agressão e Defesa II): conteúdo das aulas de Imunologia, Microbiologia e Farmacologia, lido página por página."], "resumo": [{"titulo": "1. Conceito de imunodeficiência secundária", "pontos": [{"t": "Diferença para as primárias", "sub": ["Imunodeficiência secundária é adquirida ao longo da vida, não de origem genética (slide 2).", "Causas comuns: desnutrição, obesidade, uso de imunossupressores e infecção pelo HIV. A pessoa tinha o sistema íntegro e perdeu a função."]}]}, {"titulo": "2. Desnutrição e obesidade", "pontos": [{"t": "Desnutrição proteico-calórica", "sub": ["Infecções comuns são a principal causa de morte (slide 3).", "A falta de proteína e energia reduz a produção de anticorpos, de citocinas e de células de defesa. O intestino também perde barreira, favorecendo infecções gastrointestinais (complementa a literatura de nutrição e imunidade)."]}, {"t": "Obesidade como estresse imunometabólico", "sub": ["Estado de estresse imunometabólico crônico (slide 4).", "Cascata: expansão e estresse dos adipócitos geram inflamação crônica de baixo grau e resistência à insulina (slide 5). O tecido adiposo passa a secretar citocinas inflamatórias.", "Fonte: Chavakis, Alexaki e Ferrante Jr., Nature Immunology (2023); Burak et al., Am J Clin Nutr (2024), citados no slide 27."]}]}, {"titulo": "3. Imunossupressão farmacológica", "pontos": [{"t": "Glicocorticoides", "sub": ["Atuam no receptor citoplasmático e modulam a transcrição de genes inflamatórios. Reduzem citocinas e a proliferação de linfócitos T (slides 6 e 7; Cain e Cidlowski, 2017)."]}, {"t": "Ciclosporina", "sub": ["Inibe a calcineurina, impedindo a transcrição da IL-2 no linfócito T. Sem IL-2, o T não prolifera (slide 7; aula 9, slide 14)."]}]}, {"titulo": "4. HIV e AIDS", "pontos": [{"t": "Alvos celulares", "sub": ["Células com CD4: linfócitos T CD4+, macrófagos, monócitos e células dendríticas (slide 9).", "A entrada exige CD4 e um correceptor de quimiocina (CCR5 ou CXCR4) (complementa Franchini et al., 2013)."]}, {"t": "Patogênese", "sub": ["Infecção aguda, só parcialmente controlada pela imunidade (slide 12).", "Dendríticas transmitem o vírus ao T CD4+ por contato direto (slide 13).", "Morte de T CD4+: liberação de muitas partículas virais, formação de sincícios e morte por T CD8+ (slides 14 e 15).", "Evolução para infecção crônica, com queda progressiva de T CD4+ (slide 17)."]}, {"t": "Diagnóstico e classificação", "sub": ["Triagem por ELISA e confirmação por Western blotting (slide 18).", "Testes sorológicos não são válidos em recém-nascidos de mães HIV+ até o 8º mês (slide 18).", "AIDS: T CD4+ abaixo de 200 células/µl, independentemente de sintomas (slide 19)."]}, {"t": "Terapia antirretroviral", "sub": ["Inibidores da transcriptase reversa (análogos de nucleosídeos) e outras classes atuando em etapas diferentes do ciclo viral (slides 20 e 21).", "Fonte: Brunton e Hilal-Dandan, Goodman & Gilman (citado no slide 26)."]}]}, {"titulo": "5. Pontes com outras aulas: imunossupressão, granuloma e HIV", "pontos": [{"t": "Imunossupressão farmacológica", "sub": ["Glicocorticoides inibem a produção de citocinas em várias células e induzem apoptose linfocitária; o efeito depende de dose e tempo de uso.", "Ciclosporina e tacrolimo inibem a calcineurina e bloqueiam a transcrição de IL-2; rapamicina inibe mTOR (ver aula 9).", "Anti-TNF retira um sinal necessário para manter o granuloma: quem usa anti-TNF pode reativar tuberculose latente."]}, {"t": "Granuloma e reativação da tuberculose", "sub": ["Mycobacterium tuberculosis sobrevive no macrófago e forma granuloma: Th1 secreta IFN-γ, que ativa o macrófago; o granuloma tem células epitelioides, células gigantes e necrose caseosa central.", "O granuloma tuberculoso é hipersensibilidade tipo IV, o mesmo mecanismo do teste tuberculínico (ver aula 8).", "Sem IFN-γ e sem TNF, o granuloma não se mantém: essa é a explicação mais provável da reativação sob anti-TNF ou imunossupressão."]}, {"t": "HIV e câncer", "sub": ["A perda de CD4+ no HIV reduz indiretamente a defesa antitumoral, porque o CD4+ auxilia a ativação do CD8+ (ver aula 10). Por isso a prevalência de tumores é elevada na aids."]}]}, {"titulo": "6. Para prova", "pontos": [{"t": "Pontos de cobrança", "sub": ["Causa secundária × primária (adquirida × genética).", "Por que o CD4 é o alvo do HIV.", "Corte de T CD4+ de 200 células/µl para AIDS."]}]}], "glossario": [{"termo": "AIDS", "tecnica": "Definição de imunossupressão pelo HIV", "definicao": "Imunossupressão grave, com infecções oportunistas e tumores malignos; critério laboratorial: T CD4+ abaixo de 200 células/µl.", "slide": 8}, {"termo": "Linfócito T CD4+", "tecnica": "Alvo principal do HIV", "definicao": "Célula que expressa CD4, alvo do HIV; sua destruição leva à imunossupressão.", "slide": 9}, {"termo": "Sincício", "tecnica": "Mecanismo de morte de T CD4+", "definicao": "Formação de células fundidas, uma das formas de destruição de linfócitos T CD4+ pelo HIV.", "slide": 15}, {"termo": "Transcriptase reversa", "tecnica": "Alvo da terapia antirretroviral", "definicao": "Enzima viral alvo dos análogos de nucleosídeos inibidores.", "slide": 20}, {"termo": "Western blotting", "tecnica": "Confirmação do HIV", "definicao": "Teste confirmatório após ELISA positivo.", "slide": 18}, {"termo": "Estresse imunometabólico", "tecnica": "Obesidade e imunidade", "definicao": "Estado inflamatório crônico associado à expansão e ao estresse dos adipócitos.", "slide": 4}, {"termo": "Desnutrição proteico-calórica", "tecnica": "Imunodeficiência secundária", "definicao": "Causa comum de imunodeficiência secundária. Infecções comuns são as principais causas de morte.", "slide": 3}, {"termo": "Obesidade como estresse imunometabólico", "tecnica": "Imunodeficiência secundária", "definicao": "Expansão e estresse dos adipócitos geram inflamação crônica e resistência à insulina.", "slide": 4}, {"termo": "Glicocorticoides", "tecnica": "Imunossupressor", "definicao": "Inibem a expressão de citocinas e a proliferação de linfócitos T.", "slide": 6}, {"termo": "Ciclosporina", "tecnica": "Imunossupressor", "definicao": "Inibe a calcineurina e a produção de IL-2 pelo linfócito T.", "slide": 7}, {"termo": "HIV e gp120/gp41", "tecnica": "Vírus", "definicao": "gp120 se liga ao CD4 e ao correceptor. gp41 medeia a fusão da membrana viral com a célula.", "slide": 18}, {"termo": "Receptor CD4 e correceptores CCR5 e CXCR4", "tecnica": "Receptor", "definicao": "CD4 é o receptor principal do HIV, nos linfócitos T CD4+, macrófagos e dendríticas. CCR5 e CXCR4 são os correceptores.", "slide": 9}, {"termo": "Terapia antirretroviral", "tecnica": "Tratamento", "definicao": "Análogos de nucleosídeos e outros fármacos que atuam em diferentes etapas do ciclo do HIV.", "slide": 20}, {"termo": "Testes sorológicos em recém-nascidos", "tecnica": "Diagnóstico", "definicao": "Não são válidos em filhos de mães HIV+ até o oitavo mês de vida.", "slide": 18}], "caso": {"titulo": "Caso: perda de peso e infecção oportunista", "perfil": "Diagnóstico e classificação da infecção pelo HIV.", "etapas": [{"titulo": "Etapa 1: triagem positiva", "texto": "Homem de 32 anos com perda de peso e candidíase oral recorrente. O ELISA para HIV é positivo. O médico pede confirmação antes de qualquer conclusão.", "perguntas": [{"pergunta": "Qual é o teste confirmatório indicado após o ELISA positivo, segundo a aula?", "alts": ["Western blotting", "Citometria de fluxo com marcadores de superfície", "Imunofluorescência indireta com soro do paciente", "Quimioluminescência do antígeno isolado", "Hemograma com contagem de leucócitos"], "erradas": ["Citometria mede células, não confirma a sorologia do HIV.", "IFI é uma técnica de triagem sorológica, não confirmatória do HIV.", "Quimioluminescência é um imunoensaio, não o confirmatório citado.", "Hemograma avalia leucócitos, mas não confirma o diagnóstico."], "justificativa": "O ELISA positivo deve ser confirmado com Western blotting (slide 18)."}]}, {"titulo": "Etapa 2: contagem de linfócitos", "texto": "A confirmação é positiva. A contagem de linfócitos T CD4+ é de 180 células/µl. O paciente não tem sintomas graves no momento.", "perguntas": [{"pergunta": "Qual classificação a aula dá para esse paciente, segundo a contagem de linfócitos T CD4+?", "alts": ["Portador de AIDS, pela contagem abaixo de 200 células/µl", "Infecção aguda controlada, pela contagem acima de 500 células/µl", "Imunidade preservada, pois não há sintomas graves", "Janela imunológica, pois a contagem ainda não é detectável", "Imunodeficiência primária, pela contagem de células T CD4+"], "erradas": ["Infecção aguda não se define por essa contagem nem por contagem acima de 500.", "Ausência de sintomas não preserva a imunidade pelo critério citado.", "Janela imunológica se refere à detecção de anticorpos, não a essa contagem.", "A imunodeficiência é secundária ao HIV, não primária."], "justificativa": "T CD4+ abaixo de 200 células/µl define portador de AIDS, independentemente de sintomas (slide 19)."}]}]}, "questoes": [{"id": 1, "nivel": "muito_dificil", "enunciado": "Um paciente em uso de anti-TNF para artrite reumatoide tem reativação de tuberculose pulmonar. Qual é a explicação imunológica mais coerente?", "alternativas": ["O anti-TNF aumenta a produção de IgE, que destrói diretamente o bacilo dentro do macrófago infectado na mucosa respiratória", "O anti-TNF bloqueia o receptor de IL-2 e impede a expansão clonal de linfócitos B de memória produtores de anticorpos", "O anti-TNF estimula a fusão do fagossomo com o lisossomo, liberando o bacilo para o citosol e ativando a apoptose celular", "O bloqueio do TNF desfaz a manutenção do granuloma, que depende de Th1, IFN-γ e macrófago ativado", "O anti-TNF induz apoptose de neutrófilos, que representam a única linha de defesa eficaz contra o M. tuberculosis"], "gabarito": "D", "justificativa": "O granuloma é hipersensibilidade tipo IV: Th1 secreta IFN-γ, que ativa o macrófago. Sem TNF e IFN-γ o granuloma não se mantém e a infecção latente reativa (resumo: Imunodeficiências secundárias, ponte com granuloma).", "tecnica": "Imunossupressão e granuloma", "slide": null}, {"id": 2, "nivel": "muito_dificil", "enunciado": "Uma mulher com obesidade grave e infecções de repetição tem contagem linfocitária normal. Qual é a melhor interpretação do quadro?", "alternativas": ["Inflamação metabólica crônica de baixo grau, que compromete a função imune mesmo sem queda na contagem de linfócitos", "Imunodeficiência congênita de células B, com ausência de imunoglobulinas detectáveis no soro desde a infância", "Erro inato do fagócito, com defeito da NADPH oxidase e ausência total de burst respiratório em neutrófilos circulantes", "Defeito de adesão leucocitária do tipo LAD I, com neutrofilia intensa e ausência de formação de pus nas lesões", "Síndrome da hiper-IgM, com níveis elevados de IgM sérica e ausência completa de IgG em todas as amostras"], "gabarito": "A", "justificativa": "Na obesidade há inflamação crônica de baixo grau, que compromete a função imune mesmo com contagens normais. Resposta semelhante aparece na questão 13 do 1.º bimestre (resumo: Imunodeficiências secundárias, desnutrição e obesidade).", "tecnica": "Obesidade e imunidade", "slide": null}, {"id": 3, "nivel": "muito_dificil", "enunciado": "Em um paciente com aids, por que a defesa antitumoral cai mesmo sem perda direta de CD8+?", "alternativas": ["O HIV infecta diretamente o CD8+ e impede a expressão de MHC de classe I nas células tumorais do paciente", "O HIV aumenta a produção de IgE, que bloqueia o receptor de IFN-γ nos macrófagos residentes do tecido tumoral", "O HIV inibe a apresentação antigênica pelas células B, que deixam de expressar MHC de classe II em qualquer tecido", "O CD4+ perdido deixa de auxiliar a ativação do CD8+, principal efetor antitumoral", "O HIV estimula células NK a secretar IL-10 e TGF-β, que inibem a ativação do CD8+ no microambiente tumoral"], "gabarito": "D", "justificativa": "O CD4+ auxilia a ativação do CD8+. Com a perda de CD4+ o CD8+ fica menos ativado e a imunovigilância cai, o que explica a alta prevalência de tumores na aids (resumo: Imunodeficiências secundárias e Imunologia dos tumores).", "tecnica": "HIV e câncer", "slide": null}, {"id": 4, "nivel": "muito_dificil", "enunciado": "Um transplantado em uso de ciclosporina e corticoide apresenta pneumonia por fungo oportunista. Qual combinação de mecanismos explica melhor a imunossupressão?", "alternativas": ["Ciclosporina ativa a calcineurina, aumentando a produção de IL-2; corticoide bloqueia a fagocitose por neutrófilos e macrófagos", "Ciclosporina bloqueia o CD28 pelo B7 da APC; corticoide estimula a produção de IgE pelos plasmócitos da mucosa pulmonar", "Ciclosporina inibe a calcineurina e a IL-2; corticoide inibe citocinas e induz apoptose de linfócitos", "Ciclosporina inibe o TNF e a IL-1 no endotélio; corticoide inibe a via mTOR e a proliferação de células B de memória", "Ciclosporina inibe o complemento via C3; corticoide inibe a PLA2 e a produção de anticorpos IgM específicos"], "gabarito": "C", "justificativa": "Ciclosporina e tacrolimo inibem a calcineurina e bloqueiam a transcrição de IL-2, sem expansão clonal de T. Glicocorticoides inibem citocinas em várias células e induzem apoptose linfocitária (resumo: Imunodeficiências secundárias e Transplante).", "tecnica": "Imunossupressão farmacológica", "slide": null}, {"id": 5, "nivel": "muito_dificil", "enunciado": "Em um estudo sobre imunodeficiência secundária, um grupo de pacientes apresenta maior risco de infecção oportunista. Qual característica define uma imunodeficiência secundária em relação a uma congênita?", "alternativas": ["É sempre herdada de forma autossômica recessiva e se manifesta já no período neonatal, com quadro grave desde o nascimento", "Surge em indivíduo sem defeito genético prévio, por causa externa como desnutrição, infecção ou fármaco", "Decorre de mutação em gene de célula-tronco que impede a diferenciação de linfócitos T durante o desenvolvimento embrionário", "É caracterizada por ausência total de imunoglobulinas desde o nascimento, sem causa identificável em nenhum exame realizado", "Surge apenas em pacientes submetidos a transplante de medula, por doença do enxerto contra o hospedeiro na fase aguda"], "gabarito": "B", "justificativa": "Imunodeficiência secundária é adquirida, por causa externa (desnutrição, obesidade, HIV, imunossupressão farmacológica), enquanto a congênita é genética (resumo: Imunodeficiências secundárias).", "tecnica": "Conceito", "slide": null}, {"id": 6, "nivel": "muito_dificil", "enunciado": "Um paciente com HIV tem contagem de CD4+ de 150 células/mm³. Qual alteração do sistema imune explica melhor a predisposição a infecções por patógenos intracelulares?", "alternativas": ["Excesso de IgE com degranulação de mastócitos, que destrói patógenos intracelulares na mucosa respiratória e digestiva", "Queda da imunidade celular dependente de Th1 e IFN-γ, que ativa macrófagos", "Aumento de células B de memória, que bloqueia a apresentação antigênica pelo MHC de classe I nos macrófagos ativados", "Ativação excessiva de neutrófilos com liberação de enzimas que lesam os próprios tecidos do hospedeiro na fase inicial", "Déficit de complemento da via das lectinas, que impede a opsonização de bactérias extracelulares em fluidos corporais"], "gabarito": "B", "justificativa": "Patógenos intracelulares dependem da imunidade celular Th1/IFN-γ. Com a queda de CD4+ esse eixo falha, e infecções como tuberculose e criptococose se tornam mais prováveis (resumo: Imunodeficiências secundárias, HIV).", "tecnica": "HIV e imunidade celular", "slide": null}, {"id": 7, "nivel": "muito_dificil", "enunciado": "Por que o uso de glicocorticoide em alta dose e por longo prazo aumenta o risco de infecção, mesmo sem alterar a contagem de linfócitos?", "alternativas": ["Inibe citocinas e induz apoptose linfocitária, reduzindo a resposta efetora", "Ativa a calcineurina e aumenta a transcrição de IL-2, esgotando os linfócitos T auxiliares em circulação e nos tecidos", "Bloqueia a rapamicina e impede a proliferação de neutrófilos na medula óssea, reduzindo o estoque de células de defesa", "Estimula a produção de IgE pelos plasmócitos, levando à degranulação de mastócitos e lesão de mucosas em vias aéreas", "Inibe a fagocitose por macrófagos pela ligação ao receptor de histamina H2, que é expresso em todas as células imunes"], "gabarito": "A", "justificativa": "Glicocorticoides agem amplamente: inibem citocinas em diversas células e induzem apoptose de linfócitos. O grau de imunossupressão depende de dose e tempo de uso (resumo: Imunodeficiências secundárias e Transplante).", "tecnica": "Glicocorticoides", "slide": null}, {"id": 8, "nivel": "muito_dificil", "enunciado": "Um paciente vai iniciar anti-TNF e precisa de rastreio antes do início. Qual raciocínio fundamenta esse rastreio?", "alternativas": ["O TNF é necessário para a produção de IgE, e a infecção por Schistosoma é a mais comum antes do início do tratamento", "O TNF ativa a calcineurina, e o rastreio serve para detectar precocemente linfoma de células T em fase inicial", "O TNF inibe a via mTOR, e o rastreio evita a rejeição de enxerto hepático em pacientes com cirrose descompensada", "O TNF mantém o granuloma, e a infecção latente por M. tuberculosis pode reativar sem ele", "O TNF é consumido pelo complemento, e o rastreio avalia a deficiência de C5 e de properdina hereditária"], "gabarito": "D", "justificativa": "O TNF, junto com IFN-γ, mantém o granuloma tuberculoso. O bloqueio pode reativar infecção latente, por isso o rastreio de tuberculose é obrigatório antes de anti-TNF (resumo: Imunodeficiências secundárias, ponte com granuloma).", "tecnica": "Anti-TNF e tuberculose", "slide": null}, {"id": 9, "nivel": "muito_dificil", "enunciado": "Em um paciente desnutrido grave, a resposta a vacinas vivas atenuadas é comprometida. Qual é o raciocínio mais correto sobre a segurança dessas vacinas em imunodeficiência secundária?", "alternativas": ["Vacinas vivas são mais seguras em imunocomprometidos, porque contêm antígeno insuficiente para causar doença clínica", "Vacinas vivas perdem a capacidade de replicar com desnutrição, portanto não há nenhum risco envolvido no procedimento", "Sem freio imunológico, a replicação ultrapassa a faixa de estímulo e causa a própria doença", "Vacinas vivas são inativadas pelos anticorpos maternos e por isso não têm efeito em nenhuma faixa etária de risco", "Vacinas vivas só são contraindicadas em pacientes com HIV, não em outras imunodeficiências secundárias de origem nutricional"], "gabarito": "C", "justificativa": "Vacinas vivas são contraindicadas em imunocomprometidos porque, sem o freio imunológico, a replicação ultrapassa a faixa de estímulo e causa a doença. A contraindicação é mecanística (resumo: Vacinas, janela da replicação, e Imunodeficiências secundárias).", "tecnica": "Vacinas em imunodeficiência", "slide": null}, {"id": 10, "nivel": "muito_dificil", "enunciado": "Qual sequência descreve corretamente a relação entre HIV, CD4+ e a resposta antitumoral?", "alternativas": ["HIV reduz CD8+ diretamente; o CD4+ permanece normal, mas deixa de expressar MHC de classe II nos tumores", "HIV aumenta CD4+, que passa a secretar IL-10 e impede a ativação de NK contra células tumorais de origem epitelial", "HIV reduz CD4+, que deixa de auxiliar o CD8+; o CD8+ enfraquecido elimina menos células transformadas", "HIV reduz células NK, que deixam de executar ADCC, mas o CD8+ e o CD4+ permanecem intactos e funcionais no organismo", "HIV reduz linfócitos B, que deixam de produzir anticorpos anti-HER2, e a imunovigilância antitumoral não se altera"], "gabarito": "C", "justificativa": "O CD4+ perdido não auxilia a ativação do CD8+, o principal efetor antitumoral. Por isso a aids eleva a prevalência de tumores mesmo sem queda direta do CD8+ (resumo: Imunodeficiências secundárias e Imunologia dos tumores).", "tecnica": "HIV, CD4+ e tumores", "slide": null}, {"id": 11, "nivel": "muito_dificil", "enunciado": "Um professor afirma: 'Imunodeficiência secundária é sempre irreversível, porque não há correção do fator causador.' Qual é a crítica mais precisa?", "alternativas": ["A afirmação é verdadeira apenas para desnutrição, mas falsa para obesidade, porque a obesidade não altera o sistema imune de forma clinicamente relevante", "A causa externa pode ser retirada ou tratada, e a resposta imune pode se recuperar", "A afirmação é verdadeira para todas as causas, porque toda imunodeficiência adquirida tem base genética que não pode ser modificada", "A afirmação é falsa porque imunodeficiências secundárias só ocorrem em crianças pequenas, e a recuperação é sempre espontânea", "A afirmação é verdadeira porque o sistema imune não se regenera após qualquer agressão, inclusive a medicamentosa e a infecciosa"], "gabarito": "B", "justificativa": "Imunodeficiências secundárias têm causa externa identificável (desnutrição, obesidade, HIV, fármacos). Retirada ou tratamento da causa permite recuperação parcial ou total da resposta (resumo: Imunodeficiências secundárias).", "tecnica": "Conceito e reversibilidade", "slide": null}, {"id": 12, "nivel": "muito_dificil", "enunciado": "Uma criança com desnutrição grave tem resposta humoral reduzida. Qual é o principal efeito dessa condição sobre a resposta vacinal?", "alternativas": ["Aumento da geração de anticorpos IgE, que prolonga a memória e melhora a resposta a vacinas conjugadas em lactentes", "Aumento da zona marginal do baço, que facilita a resposta T-independente a polissacarídeos encapsulados de bactérias", "Aumento da apresentação antigênica por células dendríticas, que torna a vacina mais imunogênica em todas as faixas etárias", "Ausência de efeito, porque a memória depende exclusivamente de células NK, que não são afetadas pelo estado nutricional do paciente", "Menor geração de anticorpos e de memória, porque a falta de nutrientes compromete a proliferação e a diferenciação linfocitária"], "gabarito": "E", "justificativa": "A desnutrição compromete a proliferação e diferenciação de linfócitos, reduzindo anticorpos e memória. Por isso a resposta vacinal pode ser menor (resumo: Imunodeficiências secundárias, desnutrição).", "tecnica": "Desnutrição e resposta vacinal", "slide": null}, {"id": 13, "nivel": "muito_dificil", "enunciado": "Qual alternativa descreve corretamente a diferença entre imunossupressão farmacológica seletiva e inespecífica?", "alternativas": ["Ciclosporina atua sobre todos os leucócitos da mesma forma, sem seletividade, enquanto glicocorticoide atua apenas sobre linfócitos B pela via do receptor de IL-2 específico", "Glicocorticoide atua apenas sobre neutrófilos circulantes; ciclosporina atua apenas sobre o complemento, bloqueando a via clássica no fígado", "Ambos atuam exclusivamente sobre mastócitos, bloqueando a liberação de histamina e de triptase nos tecidos periféricos inflamados", "Ciclosporina bloqueia o receptor de histamina H1; glicocorticoide bloqueia a via mTOR de forma seletiva em macrófagos residentes", "Ciclosporina age preferencialmente sobre linfócitos T via calcineurina; glicocorticoide age amplamente sobre citocinas e apoptose"], "gabarito": "E", "justificativa": "Ciclosporina inibe a calcineurina, com efeito preferencial sobre linfócitos T. Glicocorticoides têm ação ampla, sobre citocinas e apoptose linfocitária (resumo: Imunodeficiências secundárias, Transplante).", "tecnica": "Seletividade da imunossupressão", "slide": null}, {"id": 14, "nivel": "muito_dificil", "enunciado": "Em um paciente com HIV, a vacina contra HPV é indicada. Qual justificativa imunológica e epidemiológica é mais adequada?", "alternativas": ["Vacinas contra HPV são vivas atenuadas e, por isso, são seguras e indicadas em qualquer imunodeficiência, inclusive grave", "Vacinas contra HPV ativam diretamente o CD8+ e dispensam a resposta de CD4+ em qualquer situação clínica de imunossupressão", "A vacina contra HPV reduz a carga de HIV no sangue e aumenta o número de células NK circulantes no paciente tratado", "A vacina contra HPV é indicada apenas após o diagnóstico de câncer, como tratamento adjuvante, sem efeito preventivo", "Prevenir a infecção reduz a prevalência de tumores associados, e a vacina deve ser feita antes do início da vida sexual"], "gabarito": "E", "justificativa": "HPV é infecção sexualmente transmissível e a vacina é prevenção primária de câncer, feita antes da vida sexual e em ambos os sexos. A vacina é do tipo não viva e segura em imunocomprometidos (resumo: Vacinas e Imunologia dos tumores).", "tecnica": "HPV e prevenção", "slide": null}, {"id": 15, "nivel": "muito_dificil", "enunciado": "Um estudante conclui que todo paciente em uso de imunossupressor deve ser tratado como imunodeficiente congênito. Qual é o erro conceitual nesse raciocínio?", "alternativas": ["Imunossupressão farmacológica é causa adquirida e geralmente reversível; a congênita tem origem genética", "Imunossupressores causam apenas aumento de IgE, enquanto imunodeficiências congênitas causam aumento de IgM sérica em todos os casos", "Imunodeficiências congênitas são sempre tratadas com glicocorticoide, o que as torna equivalentes aos quadros secundários", "Não há diferença, porque ambas as condições têm sempre origem genética e são irreversíveis mesmo com tratamento adequado", "A imunodeficiência congênita só ocorre em adultos após contato com fármacos, nunca desde o nascimento do indivíduo"], "gabarito": "A", "justificativa": "A diferença central é a origem: congênita é genética e presente desde o nascimento; secundária é adquirida, por causa externa como fármaco, desnutrição ou HIV (resumo: Imunodeficiências secundárias e Imunodeficiências congênitas).", "tecnica": "Congênita × secundária", "slide": null}], "id": "imuno-thiago-04", "titulo": "Aula 4", "voltar": {"href": "#/agressao/thiago", "texto": "Professor Thiago"}, "manobras": [], "imagens": [], "casos_extremos": []};
window.AULAS["imuno-thiago-05"] = {"subtitulo": "Tolerância e mecanismos de autoimunidade", "pdf": "pdf/thiago/aula-05.pdf", "abas": ["resumo", "glossario", "quiz", "pdf"], "fontes": ["Aula 5 · Tolerância e Mecanismos de Autoimunidade (Prof. Dr. Thiago Corrêa)", "Abbas, Lichtman e Pillai (2019); Murphy (2014); Katsarou et al. (2017) (citados nos slides)", "Resumo integrado da Prova 2 (Agressão e Defesa II): conteúdo das aulas de Imunologia, Microbiologia e Farmacologia, lido página por página."], "resumo": [{"titulo": "1. Tolerância: o problema que o sistema resolve", "pontos": [{"t": "Conceito", "sub": ["Autotolerância é a capacidade de não reagir contra os próprios antígenos. Discriminar próprio e não próprio é propriedade fundamental do sistema imune normal (slide 2).", "Sem tolerância, cada linfócito que reconhece um antígeno do próprio corpo viraria um agressor. A tolerância ocorre em dois momentos: no desenvolvimento (central) e na vida adulta (periférica) (slide 3)."]}]}, {"titulo": "2. Tolerância central (no órgão gerador)", "pontos": [{"t": "Seleção negativa", "sub": ["Timócitos imaturos apresentam peptídeos próprios. Os que reconhecem com alta avidez entram em apoptose (deleção) (slide 5).", "Parte dos timócitos autorreativos é desviada para células Treg, em vez de morrer (slide 5)."]}, {"t": "AIRE", "sub": ["O gene AIRE faz o timo expressar antígenos de tecidos periféricos, para que os linfócitos autorreativos sejam deletados (slide 7).", "Mutação no AIRE causa síndrome poliendócrina autoimune tipo 1, com lesões em paratireoides, adrenais e ilhotas pancreáticas (slide 8). O quadro mostra que a tolerância central é essencial."]}]}, {"titulo": "3. Tolerância periférica (na vida adulta)", "pontos": [{"t": "Mecanismos para células T", "sub": ["Linfócito T maduro que reconhece autoantígeno periférico se torna Treg ou morre (slide 9).", "Treg: subpopulação de T CD4+ que suprime respostas e mantém a autotolerância, por IL-10 e TGF-beta; expressam FOXP3 (slide 10; Abbas).", "Anergia: a célula não morre, mas fica não responsiva, porque recebeu o sinal 1 sem o sinal 2 de coestimulação (slides 11 e 12)."]}]}, {"titulo": "4. Tolerância de linfócitos B", "pontos": [{"t": "Edição do receptor e deleção", "sub": ["Linfócito B imaturo que reconhece autoantígeno com alta afinidade na medula pode trocar a cadeia leve do receptor (edição), mudando a especificidade, ou ser deletado (slide 13)."]}]}, {"titulo": "5. Por que a autoimunidade surge", "pontos": [{"t": "Genética", "sub": ["Alelos HLA, especialmente de classe II (DR e DQ), estão associados a doenças autoimunes (slide 16). O HLA define quais peptídeos são apresentados aos T."]}, {"t": "Ambiente", "sub": ["Mimetismo molecular: epítopos de agentes infecciosos parecidos com estruturas próprias (slide 18).", "Reatividade cruzada: anticorpos contra agentes infecciosos reagem com tecidos do hospedeiro (slide 19).", "Antígeno sequestrado: tecido que nunca teve contato com linfócitos é exposto após lesão (slide 20).", "Ativação inespecífica: uma infecção ativa T ou B sem especificidade para o patógeno, quebrando a tolerância (slide 21).", "Etiologia multifatorial: genética predisposta interage com tabagismo e radiação UV (slide 22)."]}]}, {"titulo": "6. Doenças autoimunes: lúpus, artrite reumatoide, esclerose múltipla e diabetes tipo 1", "pontos": [{"t": "Lúpus eritematoso sistêmico (tipo III)", "sub": ["Doença crônica, multissistêmica e recidivante; proporção de cerca de 10 mulheres para 1 homem.", "Caracteriza-se por anticorpos antinucleares e anti-DNA, ou seja, contra histonas, proteínas nucleares e o próprio DNA.", "Gatilho ambiental mais bem documentado: radiação ultravioleta, que induz apoptose em larga escala e libera antígenos nucleares que antes eram tolerados.", "TLR7 e TLR9 participam da ativação de linfócitos B específicos para antígenos nucleares.", "O predomínio feminino é atribuído ao perfil hormonal, mas o mecanismo é incerto.", "Anemia hemolítica e plaquetopenia no lúpus são de tipo II; a lesão renal, vascular e articular é de tipo III."]}, {"t": "Artrite reumatoide (tipo IV e autorreatividade T)", "sub": ["Componente genético: variantes em genes do HLA, muitas na fenda de ligação do MHC; elas aumentam a intensidade do sinal entregue ao linfócito T e favorecem linfócitos T autorreativos.", "Componente ambiental principal: tabagismo (e algumas infecções), que induz citrulinação: arginina vira citrulina e a proteína deixa de ser reconhecida como própria.", "As proteínas citrulinadas estão nas articulações, onde se instala a inflamação. Sinoviócitos ativados liberam colagenases e outras enzimas que degradam cartilagem e osso.", "Marcador laboratorial: anti-CCP."]}, {"t": "Esclerose múltipla", "sub": ["Linfócitos T CD4+ das subpopulações Th1 e Th17 reagem contra autoantígenos da bainha de mielina, com desmielinização.", "Acomete sobretudo adultos jovens.", "COMPLEMENTO EXTERNO: a associação robusta na literatura é com o vírus Epstein-Barr (coorte de mais de 10 milhões de militares norte-americanos; Bjornevik et al., Science, 2022;375:296-301). Hepatite B, citada em aula, não é o melhor exemplo. O princípio (infecção viral prévia como gatilho) permanece válido."]}, {"t": "Diabetes mellitus tipo 1", "sub": ["Destruição imunomediada das células β das ilhotas pancreáticas por CD8+, com participação de CD4+ e autoanticorpos.", "A destruição é seletiva: só as células produtoras de insulina são eliminadas; as que produzem glucagon são poupadas.", "Como o paciente perde a célula, depende de insulina exógena para sempre. No tipo 2 a célula β existe, mas o hormônio não exerce sua função (resistência insulínica)."]}]}, {"titulo": "7. Mimetismo molecular e autoimunidade por infecção", "pontos": [{"t": "Princípio", "sub": ["Mimetismo molecular: anticorpo ou linfócito formado contra um antígeno microbiano reage com um antígeno próprio semelhante.", "Exemplo clássico: febre reumática, com proteína M do Streptococcus pyogenes semelhante à miosina cardíaca (ver aula 8).", "Também explica os anticorpos naturais anti-A e anti-B: bactérias da microbiota expressam carboidratos semelhantes e estimulam esses anticorpos (ver aula 9).", "Espere a mesma lógica em qualquer autoimunidade: predisposição genética (HLA) somada a um fator ambiental, como infecção ou tabagismo."]}]}, {"titulo": "8. Para prova", "pontos": [{"t": "Pontos de cobrança", "sub": ["Tolerância central × periférica: local e mecanismo.", "Papel do AIRE e síndrome associada.", "Mimetismo × reatividade cruzada × antígeno sequestrado: cada um é um mecanismo ambiental distinto."]}]}], "glossario": [{"termo": "AIRE", "tecnica": "Tolerância central", "definicao": "Gene que induz a expressão, no timo, de antígenos proteicos próprios de tecidos periféricos. Sua mutação causa poliendocrinopatia autoimune.", "slide": 7}, {"termo": "Seleção negativa (deleção)", "tecnica": "Tolerância central", "definicao": "Morte por apoptose de timócitos que reconhecem autoantígenos com alta avidez.", "slide": 5}, {"termo": "Treg", "tecnica": "Tolerância periférica", "definicao": "Subpopulação de T CD4+ que suprime respostas imunes e mantém a autotolerância.", "slide": 10}, {"termo": "Anergia", "tecnica": "Tolerância periférica", "definicao": "Estado de não responsividade ao antígeno, sem morte da célula autorreativa.", "slide": 12}, {"termo": "Mimetismo molecular", "tecnica": "Fatores ambientais", "definicao": "Semelhança entre epítopos de agentes infecciosos e substâncias próprias do organismo.", "slide": 18}, {"termo": "Antígeno sequestrado", "tecnica": "Fatores ambientais", "definicao": "Antígeno sem contato prévio com linfócitos, exposto após lesão tecidual.", "slide": 20}, {"termo": "Edição do receptor", "tecnica": "Tolerância de B", "definicao": "Troca da cadeia leve do receptor do linfócito B para reduzir a autorreatividade.", "slide": 1}], "caso": {"titulo": "Caso: falência de tolerância", "perfil": "Síndrome poliendócrina autoimune e desencadeamento por infecção.", "etapas": [{"titulo": "Etapa 1: múltiplas endocrinopatias", "texto": "Jovem de 25 anos com hipoparatireoidismo, insuficiência adrenal e diabetes em investigação. Há candidíase oral de repetição. A família relata irmã com quadro semelhante.", "perguntas": [{"pergunta": "Qual defeito de tolerância central melhor explica o quadro, segundo a aula?", "alts": ["Mutação no gene AIRE, com falha na expressão de antígenos periféricos no timo", "Excesso de células NK que destroem as ilhotas pancreáticas", "Deficiência de IgA seletiva com infecções mucosas recorrentes", "Defeito do complexo phox nos fagócitos com superóxido reduzido", "Ausência de linfócitos B na medula, com anticorpos ausentes"], "erradas": ["Células NK não são o defeito descrito na tolerância central.", "IgA seletiva não causa lesões endócrinas múltiplas.", "O complexo phox leva à DGC, sem endocrinopatias múltiplas.", "A falta de linfócitos B não explica lesões endócrinas múltiplas."], "justificativa": "Mutações no gene AIRE causam a síndrome poliendócrina autoimune tipo 1 (slide 8)."}]}, {"titulo": "Etapa 2: infecção desencadeante", "texto": "A paciente tem uma infecção viral que precede a piora do quadro. Ela não sabe qual antígeno do vírus pode estar envolvido, mas a equipe investiga a relação com a autoimunidade.", "perguntas": [{"pergunta": "Qual mecanismo a aula descreve para uma infecção desencadear autoimunidade?", "alts": ["Mimetismo molecular entre epítopos do agente e substâncias próprias", "Seleção negativa de timócitos com TCR de baixa avidez", "Reação de hipersensibilidade tipo I, com IgE contra o vírus", "Deficiência de CD40 ligante com troca de isotipo prejudicada", "Ativação de células NK pela perda de MHC de classe II"], "erradas": ["Seleção negativa elimina autorreativos, o oposto de desencadear autoimunidade.", "Hipersensibilidade tipo I é alergia mediada por IgE, não o mecanismo descrito.", "Deficiência de CD40 ligante é um defeito de imunodeficiência, não de autoimunidade.", "Perda de MHC de classe II não é o mecanismo citado para a infecção desencadear autoimunidade."], "justificativa": "Mimetismo molecular entre epítopos de agentes infecciosos e substâncias próprias pode desencadear autoimunidade (slide 18)."}]}]}, "questoes": [{"id": 1, "nivel": "muito_dificil", "enunciado": "No lúpus eritematoso sistêmico, a radiação ultravioleta é um gatilho bem documentado. Qual é o mecanismo que liga a exposição solar à autoimunidade?", "alternativas": ["A radiação ultravioleta ativa diretamente a calcineurina nos linfócitos T CD8+ e aumenta a produção de IL-2 na pele", "A radiação ultravioleta inibe a fagocitose de células mortas por macrófagos, deixando o DNA livre no soro", "A radiação ultravioleta bloqueia o receptor de histamina H1 nos mastócitos da pele, aumentando a liberação de IgE", "A radiação ultravioleta destrói as células B de memória, impedindo a eliminação de autoantígenos da circulação", "Apoptose em larga escala libera antígenos nucleares que antes eram tolerados por estarem dentro do núcleo"], "gabarito": "E", "justificativa": "A UV induz apoptose em larga escala, liberando antígenos nucleares. Antígenos que estavam protegidos no núcleo deixam de ser tolerados quando expostos (resumo: Tolerância e autoimunidade; Hipersensibilidade II–IV).", "tecnica": "Gatilho ambiental do lúpus", "slide": null}, {"id": 2, "nivel": "muito_dificil", "enunciado": "Na artrite reumatoide, variantes de HLA na fenda de ligação ao MHC predispõem à doença. Qual é o mecanismo molecular proposto?", "alternativas": ["Impedem a expressão de MHC de classe II, de modo que nenhum linfócito T CD4+ reconhece o autoantígeno articular", "Aumentam a intensidade do sinal entregue ao linfócito T, ativando células que deveriam permanecer inativas", "Substituem a citrulina por arginina nas proteínas articulares, tornando-as invisíveis ao sistema imune do paciente", "Aumentam a produção de IgE pelos plasmócitos, o que provoca degranulação de mastócitos no tecido sinovial", "Inibem a calcineurina nos linfócitos B, bloqueando a produção de anticorpos anti-CCP pelo paciente"], "gabarito": "B", "justificativa": "Variantes de HLA na fenda do MHC aumentam o sinal ao linfócito T; células que deveriam ficar inativas diante de autoantígenos são ativadas (resumo: Tolerância e autoimunidade, artrite reumatoide).", "tecnica": "Genética da artrite reumatoide", "slide": null}, {"id": 3, "nivel": "muito_dificil", "enunciado": "Um paciente tabagista desenvolve artrite reumatoide. Qual modificação proteica explica por que o organismo passa a reconhecer as proteínas articulares como estranhas?", "alternativas": ["Glicosilação de resíduos de serina, que aumenta a solubilidade da proteína e facilita sua difusão no tecido sinovial", "Fosforilação de resíduos de tirosina, que ativa a fosfolipase A2 e libera ácido araquidônico nas articulações", "Citrulinação: arginina convertida em citrulina, e a proteína deixa de ser reconhecida como própria", "Hidroxilação de prolina, que transforma o colágeno em um hapteno capaz de se ligar a IgE mastocitária", "Metilação de histonas, que silencia genes de MHC de classe I nos sinoviócitos e impede a apresentação"], "gabarito": "C", "justificativa": "Tabagismo e algumas infecções induzem citrulinação: a arginina vira citrulina e a proteína modificada não é reconhecida como própria. O anti-CCP é o marcador laboratorial (resumo: Tolerância e autoimunidade).", "tecnica": "Citrulinação", "slide": null}, {"id": 4, "nivel": "muito_dificil", "enunciado": "Na esclerose múltipla, a lesão é desmielinização mediada por linfócitos T. Quais subpopulações são descritas como principais nessa doença?", "alternativas": ["Th2 e Tfh, que produzem IgE contra autoantígenos da bainha de mielina", "Treg e NK, que suprimem a mielinização e induzem apoptose de oligodendrócitos", "Células B de memória, que produzem anticorpos contra a glicoproteína do capsídeo viral", "Th1 e Th17, reagindo contra autoantígenos da bainha de mielina", "Mastócitos e eosinófilos, que liberam triptase e MBP sobre as fibras nervosas"], "gabarito": "D", "justificativa": "Linfócitos T CD4+ Th1 e Th17 reagem contra autoantígenos da mielina, com desmielinização. A doença acomete sobretudo adultos jovens (resumo: Tolerância e autoimunidade).", "tecnica": "Subpopulações na esclerose múltipla", "slide": null}, {"id": 5, "nivel": "muito_dificil", "enunciado": "No diabetes mellitus tipo 1, a destruição das células β é seletiva. Por que o paciente depende de insulina exógena permanentemente?", "alternativas": ["Porque a célula β existe, mas não responde ao sinal de glicose, e o hormônio não exerce sua função", "Porque a célula produtora de insulina é destruída, e não apenas o hormônio deixa de agir", "Porque o glucagon é destruído junto e o fígado deixa de sintetizar glicose a partir de aminoácidos", "Porque os anticorpos bloqueiam o receptor de insulina no músculo, impedindo a captação de glicose", "Porque o IFN-γ inibe a transcrição do gene da insulina, mas a célula permanece viva e funcional"], "gabarito": "B", "justificativa": "Na DM1, CD8+ com participação de CD4+ e autoanticorpos destroem as células β produtoras de insulina; as células de glucagon são poupadas. No tipo 2 a célula existe, mas o hormônio não funciona (resumo: Tolerância e autoimunidade).", "tecnica": "DM1 × DM2", "slide": null}, {"id": 6, "nivel": "muito_dificil", "enunciado": "Quando uma infecção bacteriana induz anticorpos que reagem com antígenos próprios, o fenômeno é chamado de mimetismo molecular. Qual é o exemplo clássico estudado em aula?", "alternativas": ["Doença do soro por penicilina, com complexos formados pela penicilina ligada à albumina sérica", "Anemia hemolítica autoimune, com IgG contra antígenos do grupo Rh em hemácias circulantes", "Febre reumática, com proteína M de Streptococcus pyogenes semelhante à miosina cardíaca", "Miastenia gravis, com anticorpos contra o receptor de TSH nos folículos tireoidianos", "Dermatite atópica, com IgE contra proteínas do ácaro presentes na poeira doméstica"], "gabarito": "C", "justificativa": "A proteína M do S. pyogenes é estruturalmente semelhante à miosina cardíaca; o anticorpo contra a bactéria reage com o miocárdio, causando miocardite e artrite (resumo: Tolerância e autoimunidade; Hipersensibilidade II–IV).", "tecnica": "Mimetismo molecular", "slide": null}, {"id": 7, "nivel": "muito_dificil", "enunciado": "Por que a tolerância central é insuficiente para evitar autoimunidade, exigindo também tolerância periférica?", "alternativas": ["Porque o timo elimina apenas linfócitos B, deixando os linfócitos T autorreativos livres para circular na periferia", "Nem todo autoantígeno é expresso no timo ou na medula; alguns autorreativos escapam", "Porque a tolerância central depende de IgE, que não se forma em indivíduos sem alergia prévia a antígenos ambientais", "Porque a tolerância periférica ocorre apenas no fígado, onde os linfócitos recebem o sinal de célula dendrítica imatura", "Porque a apoptose central elimina todos os linfócitos autorreativos, e a tolerância periférica serve apenas para reforço"], "gabarito": "B", "justificativa": "A tolerância central ocorre no órgão gerador e não cobre todos os autoantígenos; linfócitos autorreativos podem escapar, e por isso a tolerância periférica é necessária (resumo: Tolerância e autoimunidade).", "tecnica": "Tolerância central e periférica", "slide": null}, {"id": 8, "nivel": "muito_dificil", "enunciado": "Uma doença autoimune crônica se distingue de uma reação a medicamento transitória. Qual é a diferença mecanística mais importante?", "alternativas": ["Na autoimunidade o complemento não é ativado; na reação a medicamento ele é ativado pela via clássica", "Na autoimunidade só há anticorpos IgE; na reação a medicamento só há anticorpos IgG com memória", "Na autoimunidade há apenas Th2 ativadas; na reação a medicamento há apenas Th1 e IFN-γ em excesso", "Na autoimunidade o antígeno é solúvel e transitório; na reação a medicamento o antígeno é fixo na membrana", "Na autoimunidade não se consegue remover o autoantígeno; na reação a medicamento basta retirar o antígeno"], "gabarito": "E", "justificativa": "A doença do soro por penicilina é transitória porque o antígeno é retirado; a autoimunidade é crônica porque o autoantígeno não pode ser removido, só se reduz a produção de anticorpos (resumo: Hipersensibilidade III e Tolerância).", "tecnica": "Crônico × transitório", "slide": null}, {"id": 9, "nivel": "muito_dificil", "enunciado": "No lúpus, TLR7 e TLR9 participam da ativação de linfócitos B específicos para antígenos nucleares. Qual é o papel desses receptores?", "alternativas": ["Reconhecem ácidos nucleicos e ativam linfócitos B autorreativos contra antígenos nucleares", "Reconhecem lipopolissacarídeo e induzem a apoptose de neutrófilos, reduzindo a inflamação sistêmica", "Reconhecem IgE e impedem a degranulação de mastócitos, o que previne a anafilaxia no paciente", "Reconhecem o peptídeo do MHC de classe I e bloqueiam a apresentação antigênica para o CD8+", "Reconhecem o TNF e inibem a expressão de CD40 nas células dendríticas do tecido linfoide"], "gabarito": "A", "justificativa": "TLR7 e TLR9 reconhecem ácidos nucleicos e participam da ativação de linfócitos B autorreativos contra antígenos nucleares (resumo: Tolerância e autoimunidade, lúpus).", "tecnica": "TLR no lúpus", "slide": null}, {"id": 10, "nivel": "muito_dificil", "enunciado": "Uma mulher jovem tem lúpus, com anticorpos antinucleares e anti-DNA. Por que o predomínio feminino é atribuído, em parte, ao perfil hormonal?", "alternativas": ["Porque o mecanismo do predomínio feminino permanece incerto, e a hipótese hormonal ainda não foi comprovada", "Porque estrogênio inibe completamente a apoptose e impede a liberação de antígenos nucleares em qualquer contexto clínico", "Porque androgênios ativam a calcineurina nos linfócitos B, o que bloqueia a produção de anticorpos antinucleares", "Porque a progesterona estimula IgE e degranulação de mastócitos, causando lesão renal e cutânea nas mulheres", "Porque o hormônio feminino induz a expressão de MHC de classe II em hemácias, tornando-as alvos de linfócitos"], "gabarito": "A", "justificativa": "O predomínio feminino é atribuído ao perfil hormonal, mas o mecanismo permanece incerto, como o próprio professor reconheceu (resumo: Tolerância e autoimunidade, lúpus).", "tecnica": "Lúpus e sexo", "slide": null}, {"id": 11, "nivel": "muito_dificil", "enunciado": "Um estudante associa a esclerose múltipla à hepatite B, como dito em aula. Qual correção mais precisa deve ser feita, mantendo o princípio correto?", "alternativas": ["A associação é com o HPV, que é o vírus mais estudado na desmielinização desde a década de 1990", "A associação é com o citomegalovírus, que não tem relação com o sistema imune de células T CD8+", "A associação robusta é com o vírus Epstein-Barr; a infecção viral prévia como gatilho permanece válida", "Não existe associação viral; a esclerose múltipla decorre apenas de mutação genética no gene do HLA-DR", "A associação é com o vírus da raiva, que induz mielina e destrói os oligodendrócitos de forma direta"], "gabarito": "C", "justificativa": "A associação robusta na literatura é com o EBV (Bjornevik et al., Science, 2022). O princípio, infecção viral prévia como gatilho ambiental, permanece válido (resumo: Tolerância e autoimunidade, complemento externo).", "tecnica": "Esclerose múltipla e EBV", "slide": null}, {"id": 12, "nivel": "muito_dificil", "enunciado": "Por que a autoimunidade deve ser entendida como predisposição genética somada a um fator ambiental, e não apenas como um dos dois?", "alternativas": ["Porque o ambiente sozinho é suficiente para causar autoimunidade em qualquer indivíduo, sem nenhuma predisposição genética", "Porque a genética sozinha causa autoimunidade de forma completa, e o ambiente apenas modula a intensidade da lesão", "Porque o HLA só afeta a imunidade inata, e o ambiente só afeta a imunidade adaptativa sem nenhuma interação", "Porque o HLA aumenta a chance de reagir ao autoantígeno, e o ambiente dispara a resposta", "Porque a predisposição genética é irrelevante para a esclerose múltipla, que depende apenas do vírus Epstein-Barr"], "gabarito": "D", "justificativa": "A autoimunidade costuma exigir predisposição (HLA) e gatilho ambiental (infecção, tabagismo, UV). Essa lógica se repete em todas as autoimunidades da aula (resumo: Tolerância e autoimunidade).", "tecnica": "Genética e ambiente", "slide": null}, {"id": 13, "nivel": "muito_dificil", "enunciado": "Em um paciente com autoimunidade, qual dos autoanticorpos abaixo está corretamente associado à sua doença?", "alternativas": ["Anti-CCP, marcador laboratorial da artrite reumatoide", "Anti-TSH, marcador da miastenia gravis e da doença de Graves", "Anti-CD20, marcador da esclerose múltipla em adultos jovens", "Anti-insulina IgE, marcador do lúpus eritematoso sistêmico", "Anti-histona IgM, marcador da febre reumática com miocardite"], "gabarito": "A", "justificativa": "Anti-CCP é o marcador laboratorial da artrite reumatoide. No lúpus, o marcador é o anti-DNA e antinuclear; na miastenia, anticorpo contra o receptor de acetilcolina (resumo: Tolerância e autoimunidade).", "tecnica": "Autoanticorpos e doenças", "slide": null}, {"id": 14, "nivel": "muito_dificil", "enunciado": "Por que a infecção pela cepa de Streptococcus pyogenes causa febre reumática mesmo depois de a bactéria ser eliminada pelo antibiótico?", "alternativas": ["Porque a bactéria permanece no coração em forma de L, sem cultura, e continua ativando o complemento", "Porque o antibiótico aumenta a expressão de MHC de classe I, o que torna as células cardíacas alvos de CD8+", "Porque a febre reumática é uma imunodeficiência secundária, causada pela queda de IgG após a infecção", "Porque a bactéria induz apoptose de neutrófilos, e o acúmulo de células mortas no coração desencadeia a doença", "Porque o anticorpo formado contra a proteína M reage com a miosina cardíaca, em reação cruzada que persiste"], "gabarito": "E", "justificativa": "No mimetismo molecular, os anticorpos contra a proteína M reagem com o miocárdio mesmo após a eliminação da bactéria. A doença surge após faringoamigdalite mal tratada, entre 5 e 15 anos (resumo: Tolerância e autoimunidade).", "tecnica": "Febre reumática", "slide": null}, {"id": 15, "nivel": "muito_dificil", "enunciado": "Em um paciente com doença autoimune, a tolerância de linfócitos B é rompida. Qual característica dos autoantígenos nucleares explica por que eles escapam mais facilmente da tolerância?", "alternativas": ["São sempre proteínas de baixo peso molecular, abaixo de 5 kDa, que não são reconhecidas pelo sistema imune", "São sempre carboidratos que se ligam à IgE e ativam diretamente mastócitos no tecido conjuntivo", "São expressos somente em células tumorais, e por isso a tolerância não se aplica a eles em nenhum tecido", "Permanecem tolerados enquanto dentro do núcleo, mas tornam-se imunogênicos quando liberados por apoptose", "São produzidos apenas no timo durante a infância e são eliminados por completo antes da puberdade"], "gabarito": "D", "justificativa": "Autoantígenos nucleares são tolerados enquanto estão dentro do núcleo; a apoptose os expõe e os torna imunogênicos (resumo: Tolerância e autoimunidade, lúpus).", "tecnica": "Autoantígeno nuclear", "slide": null}], "id": "imuno-thiago-05", "titulo": "Aula 5", "voltar": {"href": "#/agressao/thiago", "texto": "Professor Thiago"}, "manobras": [], "imagens": [], "casos_extremos": []};
window.AULAS["imuno-thiago-06"] = {"subtitulo": "Imunização por vacinas virais e bacterianas", "pdf": "pdf/thiago/aula-06.pdf", "abas": ["resumo", "glossario", "quiz", "pdf"], "fontes": ["Aula 6 · Imunização por Vacinas Virais e Bacterianas (Prof. Dr. Thiago Corrêa)", "Delves, Martin, Burton e Roitt (2018); Pollard e Bijker (2021); Mbow, De Gregorio e Ulmer (2011) (citados nos slides)", "Resumo integrado da Prova 2 (Agressão e Defesa II): conteúdo das aulas de Imunologia, Microbiologia e Farmacologia, lido página por página."], "resumo": [{"titulo": "1. Origem e impacto da vacinação", "pontos": [{"t": "Jenner e a origem", "sub": ["Vacinar é expor o sistema imune a um antígeno para gerar memória adaptativa (slide 2).", "Epônimo: Edward Jenner (1749–1823) mostrou que a inoculação com vacínia, vírus pouco virulento, protegia contra a varíola (slide 2)."]}, {"t": "Impacto populacional", "sub": ["Estima-se 2 a 3 milhões de vidas salvas por ano, com redução da mortalidade em menores de 5 anos (slide 3).", "Os ensaios medem prevenção de infecção, redução da gravidade e redução da hospitalização (slide 4)."]}]}, {"titulo": "2. O que a vacina contém e como protege", "pontos": [{"t": "Componente", "sub": ["Na maioria das vacinas, o componente essencial é um ou mais antígenos proteicos do patógeno (slide 4).", "Adjuvantes (sais de alumínio, emulsões, lipossomos) ampliam a resposta das vacinas não vivas (slide 9)."]}, {"t": "Duas bases de proteção", "sub": ["Anticorpos preexistentes, que agem sem nova estimulação celular, e células B de memória, que se expandem no novo contato (slide 5).", "Anticorpos são os principais mediadores da imunidade esterilizante; a maioria das vacinas também induz células T (slide 13)."]}]}, {"titulo": "3. Tipos de vacina", "pontos": [{"t": "Vivas atenuadas", "sub": ["Cepa replicante atenuada, que se multiplica pouco no hospedeiro: sarampo, caxumba, rubéola, rotavírus, pólio oral e BCG (slide 6).", "Dão imunidade forte, mas são perigosas em imunossupressão grave."]}, {"t": "Não vivas (inativadas ou de componentes)", "sub": ["Componentes ou organismos mortos: hepatite B, polissacarídeos pneumocócicos, toxoides (difteria e tétano), coqueluche de células inteiras e gripe inativada (slides 6 e 10)."]}]}, {"titulo": "4. Memória, população e fatores de resposta", "pontos": [{"t": "Pecado antigênico original", "sub": ["Falha em gerar resposta contra nova cepa após exposição a cepa relacionada (slide 15). A resposta foi moldada pela primeira cepa.", "Estratégias: adjuvantes e vacinas com mais variantes (bivalente, trivalente) (slide 15)."]}, {"t": "Imunidade de rebanho", "sub": ["Sem vacinação, o patógeno circula; com cobertura abaixo do limiar, ainda se propaga; acima do limiar, a infecção não se sustenta e suscetíveis são protegidos indiretamente (slides 16 e 17)."]}, {"t": "Fatores que alteram a resposta", "sub": ["Idade, anticorpos maternos, exposição prévia e esquema vacinal (slide 18). Na infância, os nichos da medula para células B são limitados (slide 18)."]}]}, {"titulo": "5. Polissacarídica × conjugada: a diferença que cai", "pontos": [{"t": "Polissacarídica pura", "sub": ["Resposta T-independente: sem memória de células B, anticorpos de curta duração e sem maturação por afinidade (slide 19).", "Em menores de 2 anos não há resposta, porque a resposta T-independente depende da zona marginal do baço, que só amadurece por volta de 18 meses (slide 19)."]}, {"t": "Conjugada", "sub": ["O polissacarídeo é ligado a uma proteína carreadora. Células T reconhecem a proteína e ajudam a célula B que reconhece o polissacarídeo (slide 20).", "Gera maturação por afinidade, memória e anticorpos de longa duração; protege contra meningite infantil e pneumonia (slide 20)."]}]}, {"titulo": "6. Imunossuprimidos e calendário (fonte nacional)", "pontos": [{"t": "Regra geral", "sub": ["Vacinas vivas atenuadas podem ser perigosas em imunossupressão grave: BCG, rotavírus, pólio oral, febre amarela, sarampo-caxumba-rubéola e varicela estão contraindicadas nesse caso (SBIm, calendário para pacientes especiais).", "Vacinas inativadas podem ser usadas sem aumento de eventos adversos.", "Quem vai iniciar imunossupressão deve, se possível, receber as vivas antes do início.", "Fonte: SBIm, Calendário de Vacinação para Pacientes Especiais (2025); Instrução Normativa do Calendário Nacional 2026 (Ministério da Saúde). Confira a versão vigente."]}]}, {"titulo": "7. Memória e proteção: os dois compartimentos", "pontos": [{"t": "Conceito-chave", "sub": ["A vacina reproduz, de forma controlada, o encontro com o patógeno: simula infecção intensa o bastante para ativar a adaptativa, mas insuficiente para causar doença.", "Proteção vem de dois compartimentos: anticorpos circulantes preexistentes, que impedem a proliferação do patógeno e previnem a infecção; e células B de memória residentes na medula, que não impedem a infecção, mas reduzem a resposta humoral de 7–10 dias para 3–4 dias.", "Uma vacina pode gerar os dois ou apenas um. Títulos baixos de anticorpo não significam falha vacinal se houver memória.", "Corrida entre o período de incubação e o tempo de reativação da memória: incubação longa e resposta rápida favorecem o hospedeiro; incubação curta ou resposta lenta levam à doença, mesmo no vacinado. Isso explica por que a vacina funciona na média populacional, mas não em todos."]}]}, {"titulo": "8. Eficácia: o que o ensaio clínico mede", "pontos": [{"t": "Desenho e desfechos", "sub": ["Desenho obrigatório: ensaio clínico randomizado, controlado e duplo-cego.", "Três desfechos distintos: prevenção da infecção (melhor cenário, sem infecção não há doença nem transmissão), redução da gravidade e redução da hospitalização.", "Uma vacina que não evita a infecção continua eficaz se reduzir gravidade ou hospitalização."]}]}, {"titulo": "9. Vivas atenuadas × inativadas e a janela da replicação", "pontos": [{"t": "Comparação", "sub": ["Vivas atenuadas: patógeno enfraquecido com replicação limitada; imunogenicidade alta, pois a replicação amplifica o estímulo; contraindicadas em imunocomprometidos e gestantes. Exemplos: BCG, tríplice e tetra viral, rotavírus, pólio oral, febre amarela, varicela, herpes-zóster atenuada.", "Não vivas (inativadas): micro-organismo morto ou frações; imunogenicidade menor, costumam exigir adjuvante e mais doses; seguras mesmo em imunocomprometidos. Exemplos: hepatite A e B, pólio injetável, HPV, raiva, influenza, DTP, meningocócicas, pneumocócicas, Haemophilus influenzae b, coronavírus."]}, {"t": "Ênfase do professor: a janela da replicação", "sub": ["Pense numa faixa de estímulo: abaixo dela não há proteção, dentro dela há imunidade, acima dela há doença.", "No imunocompetente, o vírus atenuado replica e estaciona dentro da faixa. No imunocomprometido, sem freio imunológico, ultrapassa a faixa e causa a doença que deveria prevenir.", "Esse é o motivo mecanístico da contraindicação. A analogia vale para a intensidade do estímulo, não para farmacocinética."]}]}, {"titulo": "10. Polissacarídica × conjugada: o mecanismo completo", "pontos": [{"t": "Por que a conjugada é melhor", "sub": ["Antígeno polissacarídico puro é T-independente: ativa o linfócito B diretamente. Gera resposta funcional, porém sem centro germinativo, sem maturação de afinidade, sem troca de classe e sem memória, com anticorpos de curta duração.", "A resposta depende da zona marginal do baço, que só amadurece por volta dos 18 meses; por isso crianças abaixo de 2 anos ficavam desprotegidas contra meningite e pneumonia por bactérias encapsuladas.", "Conjugada: o linfócito B captura o conjunto pelo BCR (reconhece o açúcar), processa e apresenta peptídeos da proteína carreadora no MHC de classe II; o linfócito T auxiliar fornece o segundo sinal.", "Resposta T-dependente: maturação de afinidade, troca de classe, anticorpos duradouros, memória, e funciona em lactentes sem depender do baço maduro."]}, {"t": "Ênfase do professor", "sub": ["Dito em aula: \"quando eu só tenho carboidrato, eu vou ter uma resposta T-independente — fica ligado para a prova\"."]}, {"t": "Correlação clínica: esplenectomia", "sub": ["O esplenectomizado perde a zona marginal e, com ela, a resposta T-independente e a depuração fagocítica de bactérias opsonizadas.", "Risco elevado de sepse fulminante por S. pneumoniae, N. meningitidis e H. influenzae b. Por isso esses pacientes recebem vacinas conjugadas."]}]}, {"titulo": "11. Adjuvantes, plataformas de produção e mRNA", "pontos": [{"t": "Adjuvantes", "sub": ["Adjuvante (do latim adiuvare, ajudar) compensa a baixa imunogenicidade das vacinas não vivas estimulando a imunidade inata; quanto melhor a inata, melhor a adaptativa.", "Exemplos: sais de alumínio (alume), emulsões, lipossomos e complexos imunoestimulantes."]}, {"t": "Plataformas", "sub": ["Microrganismo inteiro morto.", "Toxoide: toxina atenuada, quando a doença é causada pela toxina.", "Subunidade purificada ou recombinante.", "Partícula semelhante a vírus (VLP), usada no HPV; muito segura porque não contém vírus.", "Conjugada.", "Vetor viral: vírus inócuo carregando o gene da proteína-alvo, como na vacina para ebola.", "RNA mensageiro: uma vesícula lipídica entrega a molécula no citoplasma; o ribossomo traduz; a célula passa a produzir a proteína viral, apresentada em MHC de classe I e II."]}, {"t": "Mito do mRNA", "sub": ["O RNA é degradado rapidamente, não entra no núcleo e não tem maquinaria para editar o genoma. Editar DNA exige endonucleases como as do sistema CRISPR-Cas9."]}]}, {"titulo": "12. Imunidade de rebanho e fatores que limitam a resposta", "pontos": [{"t": "Rebanho e antigenicidade", "sub": ["Imunidade de rebanho protege indiretamente quem não pode se vacinar (gestantes, imunocomprometidos). O limiar sobe com a transmissibilidade: o sarampo exige cobertura próxima de 95%.", "Pecado antigênico original: falha em montar resposta contra uma cepa nova após exposição a uma cepa próxima. Contornos: vacinas multivalentes e adjuvantes."]}, {"t": "Fatores que limitam a resposta", "sub": ["Extremos de idade: nichos medulares imaturos no lactente; imunossenescência no idoso.", "Anticorpos maternos, que se ligam ao antígeno vacinal e bloqueiam o estímulo.", "Esquema vacinal incompleto e variabilidade genética."]}]}, {"titulo": "13. Para prova", "pontos": [{"t": "Pontos de cobrança", "sub": ["Dupla base da proteção: anticorpo preexistente e memória B.", "Por que a criança pequena precisa da conjugada.", "O que acontece abaixo e acima do limiar de imunidade de rebanho."]}]}], "glossario": [{"termo": "Vacina viva atenuada", "tecnica": "Tipos de vacina", "definicao": "Vacina com cepas replicantes atenuadas do patógeno, como sarampo, caxumba, rubéola e BCG.", "slide": 6}, {"termo": "Vacina inativada (não viva)", "tecnica": "Tipos de vacina", "definicao": "Vacina com componentes do patógeno ou organismos mortos, como hepatite B e polissacarídeos.", "slide": 6}, {"termo": "Adjuvante", "tecnica": "Imunogenicidade", "definicao": "Substância que aumenta a capacidade da vacina de induzir resposta imune, como sais de alumínio e emulsões.", "slide": 9}, {"termo": "Pecado antigênico original", "tecnica": "Memória imunológica", "definicao": "Falha em gerar resposta contra nova cepa de um patógeno após exposição prévia a cepa relacionada.", "slide": 15}, {"termo": "Imunidade de rebanho", "tecnica": "Proteção populacional", "definicao": "Proteção indireta de suscetíveis quando a cobertura vacinal está acima do limiar.", "slide": 17}, {"termo": "Vacina conjugada", "tecnica": "Polissacarídica × conjugada", "definicao": "Vacina que une polissacarídeo a uma proteína carreadora, gerando resposta T-dependente e memória.", "slide": 20}, {"termo": "Zona marginal do baço", "tecnica": "Resposta T-independente", "definicao": "Estrutura necessária para a resposta a antígenos T-independentes, que só se desenvolve por volta de 18 meses.", "slide": 19}, {"termo": "Vacinação (origem)", "tecnica": "Epônimo", "definicao": "Inoculação de vacínia, vírus pouco virulento, que protegeu contra a varíola; base histórica da vacinação.", "slide": 2, "epônimo": "Edward Jenner"}, {"termo": "Vacina inativada ou de componentes", "tecnica": "Tipo de vacina", "definicao": "Componentes ou micro-organismos mortos, como hepatite B, toxoides e polissacarídeos.", "slide": 9}, {"termo": "Edward Jenner (epônimo: Jenner)", "tecnica": "Origem", "definicao": "Mostrou que a inoculação com vacínia protegia contra a varíola.", "slide": 2}, {"termo": "Anticorpos maternos", "tecnica": "Fatores de resposta", "definicao": "Anticorpos passados ao feto que podem interferir na resposta vacinal do lactente.", "slide": 18}, {"termo": "Vacina de imunossuprimidos", "tecnica": "Calendário", "definicao": "Vacinas vivas são contraindicadas em imunossupressão grave. Inativadas podem ser usadas.", "slide": 1}], "caso": {"titulo": "Caso: escolha da vacina em lactente", "perfil": "Idade, tipo de vacina e memória imunológica.", "etapas": [{"titulo": "Etapa 1: lactente de 6 meses", "texto": "Mãe de lactente de 6 meses pergunta sobre a vacina contra pneumococo. Há a opção de vacina polissacarídica pura e de vacina conjugada, que une o polissacarídeo a uma proteína carreadora.", "perguntas": [{"pergunta": "Qual vacina tende a gerar melhor memória e proteção em lactentes, segundo a aula?", "alts": ["Conjugada, que recruta células T pela proteína carreadora e gera memória", "Polissacarídica pura, que gera memória de células B de longa duração", "Polissacarídica pura, pois é T-dependente e não exige zona marginal", "Viva atenuada, pois dispensa a resposta de células T em lactentes", "Qualquer uma, pois a idade não influencia a resposta vacinal"], "erradas": ["Polissacarídica pura não gera memória de células B, segundo a aula.", "Polissacarídica é T-independente, e não T-dependente.", "Viva atenuada não é a vacina discutida neste caso.", "A idade influencia a resposta, conforme citado no slide 18."], "justificativa": "A conjugada gera maturação por afinidade, memória de células B e anticorpos de longa duração (slide 20)."}]}, {"titulo": "Etapa 2: creche e cobertura vacinal", "texto": "Uma creche tem cobertura vacinal de 60%, abaixo do limiar local. Surto de uma doença preveniível atinge crianças não vacinadas, e a equipe discute a proteção coletiva.", "perguntas": [{"pergunta": "Por que a cobertura abaixo do limiar favorece a propagação, segundo a aula?", "alts": ["A infecção ainda passa a suscetíveis, sem proteção de rebanho", "A cobertura baixa induz imunidade esterilizante em todas as crianças", "Os vacinados transmitem o patógeno com mais facilidade", "Anticorpos maternos impedem a vacinação de qualquer criança", "O pecado antigênico original elimina a memória das crianças"], "erradas": ["Cobertura baixa não induz imunidade esterilizante em todos.", "Vacinados não transmitem mais; a aula fala em proteção indireta.", "Anticorpos maternos afetam a proteção, mas não impedem a vacinação.", "O pecado antigênico original é outro conceito, sobre cepas novas."], "justificativa": "Com cobertura abaixo do limiar, a infecção ainda pode passar a suscetíveis e se espalhar (slide 16)."}]}]}, "questoes": [{"id": 1, "nivel": "muito_dificil", "enunciado": "Um adulto vacinado tem título de anticorpo baixo, dez anos após a vacinação. Qual é a interpretação mais correta, segundo o conceito de dois compartimentos?", "alternativas": ["Não há falha vacinal se houver células B de memória que reduzam a resposta de 7–10 para 3–4 dias", "Há falha vacinal, porque títulos baixos indicam ausência total de memória e de proteção futura", "Há falha vacinal, porque a vacina sem anticorpos circulantes não pode gerar nenhum tipo de imunidade", "Não há proteção nenhuma, porque anticorpos circulantes são a única forma de memória imunológica", "Há falha vacinal apenas se o paciente for imunocomprometido, porque a memória só funciona nesse grupo"], "gabarito": "A", "justificativa": "Anticorpos circulantes previnem a infecção; células B de memória na medula não impedem a infecção, mas aceleram a resposta. Título baixo não significa falha se houver memória (resumo: Imunização por vacinas).", "tecnica": "Memória vacinal", "slide": null}, {"id": 2, "nivel": "muito_dificil", "enunciado": "Uma vacina reduz hospitalizações, mas não impede a infecção. Segundo o desenho de ensaio clínico descrito em aula, como essa vacina deve ser classificada?", "alternativas": ["Ineficaz, porque a prevenção da infecção é o único desfecho aceito no ensaio clínico randomizado", "Eficaz apenas se for viva atenuada, porque só vacinas vivas reduzem a hospitalização de forma comprovada", "Ineficaz, porque ensaios não avaliam hospitalização, e sim apenas a produção de anticorpos neutralizantes", "Eficaz, porque reduz gravidade ou hospitalização, mesmo sem evitar a infecção", "Eficaz somente em estudo não randomizado, porque o duplo-cego impede a medida de hospitalização"], "gabarito": "D", "justificativa": "O ensaio randomizado, controlado e duplo-cego mede três desfechos: prevenção da infecção, redução da gravidade e redução da hospitalização. Uma vacina que não evita a infecção pode ser eficaz (resumo: Imunização por vacinas).", "tecnica": "Desfechos de eficácia", "slide": null}, {"id": 3, "nivel": "muito_dificil", "enunciado": "Por que vacinas vivas atenuadas são contraindicadas em imunocomprometidos, mesmo quando são seguras em imunocompetentes?", "alternativas": ["Sem freio imunológico, a replicação ultrapassa a faixa de estímulo", "A replicação viral é inibida pelos anticorpos maternos, o que torna o vírus perigoso para o próprio paciente", "A vacina viva é inativada pelo complemento em pacientes imunocomprometidos, liberando endotoxina no sangue", "A vacina viva perde a imunogenicidade quando o paciente tem baixa contagem de linfócitos B circulantes", "A vacina viva ativa apenas células NK, que em imunocomprometidos produzem IgE em excesso e causam anafilaxia"], "gabarito": "A", "justificativa": "No imunocompetente, o vírus atenuado replica dentro da faixa de estímulo. No imunocomprometido, sem o freio imunológico, ele ultrapassa a faixa e causa doença (resumo: Imunização, janela da replicação).", "tecnica": "Janela da replicação", "slide": null}, {"id": 4, "nivel": "muito_dificil", "enunciado": "Por que a vacina polissacarídica pura não gera memória em crianças pequenas, enquanto a conjugada gera?", "alternativas": ["O polissacarídeo ativa apenas o linfócito T citotóxico, que não forma memória; a conjugada ativa o linfócito NK", "Ativa o B sem auxílio de T; a conjugada traz o segundo sinal do T auxiliar", "O polissacarídeo é degradado pelo complemento antes de atingir o linfócito; a conjugada escapa à degradação", "O polissacarídeo estimula IgE, que suprime a memória; a conjugada estimula apenas IgG de longa duração", "O polissacarídeo só age na zona marginal, que é ativada por células dendríticas; a conjugada age no timo"], "gabarito": "B", "justificativa": "Polissacarídeo puro é T-independente e não gera centro germinativo nem memória. A conjugada é T-dependente: o linfócito B apresenta peptídeos da proteína carreadora no MHC II ao T auxiliar (resumo: Imunização, polissacarídica × conjugada).", "tecnica": "Polissacarídica × conjugada", "slide": null}, {"id": 5, "nivel": "muito_dificil", "enunciado": "Por que a zona marginal do baço limita a resposta a polissacarídeos em lactentes?", "alternativas": ["Porque o baço do lactente produz IgE em excesso, o que bloqueia a ativação do complemento na zona marginal", "Porque a zona marginal é formada por linfócitos T regulatórios que suprimem qualquer resposta a polissacarídeos", "Porque o lactente não tem baço funcional, e a resposta depende exclusivamente de células NK no fígado", "Porque a zona marginal só responde a antígenos proteicos, e não a estruturas de carboidrato encapsulado", "Porque só amadurece por volta dos 18 meses, deixando desprotegidas crianças abaixo de 2 anos"], "gabarito": "E", "justificativa": "A zona marginal do baço só amadurece por volta de 18 meses. Por isso crianças menores de 2 anos ficavam sem proteção contra bactérias encapsuladas, o que motivou as vacinas conjugadas (resumo: Imunização, polissacarídica × conjugada).", "tecnica": "Zona marginal e lactente", "slide": null}, {"id": 6, "nivel": "muito_dificil", "enunciado": "Uma vacina é feita com adjuvante de sal de alumínio. Qual é a função desse adjuvante, segundo o conceito apresentado em aula?", "alternativas": ["Substituir o antígeno, que passa a ser reconhecido diretamente pelo linfócito T CD8+ sem apresentação", "Impedir a replicação do patógeno no tecido, funcionando como antiviral de ação local e sem efeito imune", "Estimular a imunidade inata, e uma inata mais bem estimulada gera melhor resposta adaptativa", "Aumentar a produção de IgE para prolongar a memória, que é a principal função dos adjuvantes modernos", "Bloquear o CTLA-4 nos linfócitos T para ativar a resposta contra o antígeno vacinal de forma imediata"], "gabarito": "C", "justificativa": "Adjuvante (do latim adiuvare, ajudar) compensa a baixa imunogenicidade das vacinas não vivas ao estimular a inata; quanto melhor a inata, melhor a adaptativa (resumo: Imunização, adjuvantes).", "tecnica": "Adjuvantes", "slide": null}, {"id": 7, "nivel": "muito_dificil", "enunciado": "A vacina contra o HPV é feita com partículas semelhantes a vírus (VLP). Por que essa plataforma é considerada muito segura?", "alternativas": ["Contém o vírus inteiro inativado com formol, que é destruído pelo complemento antes de atingir a circulação", "Contém um vetor de adenovírus que integra o genoma ao DNA do hospedeiro e expressa a proteína de forma permanente", "Contém toxina atenuada, que induz apenas anticorpos antitoxina sem resposta celular de nenhum tipo", "Contém RNA mensageiro que é editado no núcleo pela endonuclease CRISPR-Cas9 antes da tradução", "Não contém material genético viral, e portanto não há vírus capaz de replicar no vacinado"], "gabarito": "E", "justificativa": "VLP é uma partícula semelhante a vírus, sem material genético, portanto não replica. É plataforma usada na vacina do HPV (resumo: Imunização, plataformas de produção).", "tecnica": "Plataformas", "slide": null}, {"id": 8, "nivel": "muito_dificil", "enunciado": "Um estudante afirma que a vacina de mRNA altera o genoma do vacinado. Qual é a correção mais precisa?", "alternativas": ["O mRNA entra no núcleo e integra-se ao cromossomo 6, onde se mantém por toda a vida do vacinado", "Não entra no núcleo, não edita DNA e é degradado após traduzir a proteína", "O mRNA é editado pela enzima telomerase, que altera permanentemente a sequência do DNA dos linfócitos", "O mRNA é replicado pela RNA polimerase II no núcleo e transmitido à descendência por via germinativa", "O mRNA é convertido em DNA por transcriptase reversa, que se insere no genoma das células musculares"], "gabarito": "B", "justificativa": "O mRNA é entregue no citoplasma por vesícula lipídica, traduzido pelo ribossomo e degradado. Editar DNA exigiria endonucleases como as do CRISPR-Cas9 (resumo: Imunização, mRNA).", "tecnica": "mRNA e genoma", "slide": null}, {"id": 9, "nivel": "muito_dificil", "enunciado": "Uma vacina de mRNA produz proteína viral, que é apresentada em MHC de classe I e II. Qual é a consequência imunológica dessa dupla apresentação?", "alternativas": ["Ativação exclusiva de linfócitos B, sem envolvimento de nenhum linfócito T, de modo que não há memória celular", "Supressão da resposta humoral pela ativação de células T regulatórias, que bloqueiam a produção de anticorpos", "Liberação de IgE pelos mastócitos, que degranulam sobre a proteína viral e causam reação alérgica sistêmica", "Ativação de linfócitos T CD8+ citotóxicos e de linfócitos T CD4+ auxiliares, o que favorece resposta completa", "Inibição da via do complemento pela proteína viral, que se liga ao C3b e impede a opsonização"], "gabarito": "D", "justificativa": "Apresentação em MHC I ativa o CD8+ e em MHC II ativa o CD4+ auxiliar, o que completa a resposta adaptativa (resumo: Imunização, plataformas e mRNA).", "tecnica": "Apresentação antigênica da vacina", "slide": null}, {"id": 10, "nivel": "muito_dificil", "enunciado": "O sarampo exige cobertura vacinal próxima de 95% para imunidade de rebanho. Por que o limiar é tão alto para esse agente?", "alternativas": ["Porque o sarampo é uma imunodeficiência congênita, e a vacina precisa cobrir todos os portadores de HLA alterado", "Porque o sarampo é altamente transmissível, e o limiar de imunidade de rebanho sobe com a transmissibilidade", "Porque a vacina do sarampo é inativada pelo calor, e precisa de cobertura quase total para compensar a perda", "Porque o sarampo é causado por bactéria encapsulada, e a cápsula exige cobertura total da população infantil", "Porque o sarampo tem resposta apenas T-independente, que só é eficaz quando todos os indivíduos são vacinados"], "gabarito": "B", "justificativa": "A imunidade de rebanho protege quem não pode se vacinar. O limiar sobe com a transmissibilidade do agente; o sarampo exige cobertura próxima de 95% (resumo: Imunização, memória de rebanho).", "tecnica": "Imunidade de rebanho", "slide": null}, {"id": 11, "nivel": "muito_dificil", "enunciado": "Um lactente recebe vacina com antígeno proteico, mas a resposta é menor que a esperada. Qual fator materno explica melhor essa falha?", "alternativas": ["Excesso de células NK maternas, que destroem as células dendríticas do lactente antes da apresentação antigênica", "Presença de IgE materna, que se liga ao MHC de classe II e impede a apresentação do antígeno", "Ausência de complemento materno, que impede a formação de centro germinativo nos linfonodos do lactente", "Presença de linfócitos T regulatórios maternos, que migram para o timo e bloqueiam a seleção positiva", "Anticorpos maternos que se ligam ao antígeno vacinal e bloqueiam o estímulo do sistema imune"], "gabarito": "E", "justificativa": "Anticorpos maternos transferidos ao lactente se ligam ao antígeno vacinal e bloqueiam o estímulo. Esse é um dos fatores que limitam a resposta vacinal (resumo: Imunização, fatores que limitam a resposta).", "tecnica": "Fatores limitantes", "slide": null}, {"id": 12, "nivel": "muito_dificil", "enunciado": "Um idoso recebe vacina e tem resposta reduzida. Qual fator explica melhor essa limitação, segundo a aula?", "alternativas": ["Ausência de medula óssea funcional, que impede a produção de linfócitos B em qualquer faixa etária acima de 60 anos", "Excesso de anticorpos maternos circulantes, que se mantêm no idoso por décadas após o nascimento", "Presença de linfócitos B de memória em número excessivo, que suprime a resposta a novos antígenos vacinais", "Imunossenescência, com perda de eficiência do sistema imune no extremo da idade", "Predominância de IgE sérica, que bloqueia os receptores de complemento nas células dendríticas do idoso"], "gabarito": "D", "justificativa": "Os extremos de idade limitam a resposta: no lactente, nichos medulares imaturos; no idoso, imunossenescência (resumo: Imunização, fatores que limitam a resposta).", "tecnica": "Extremos de idade", "slide": null}, {"id": 13, "nivel": "muito_dificil", "enunciado": "Por que a imunidade de rebanho pode falhar mesmo com boa cobertura, quando surge uma cepa nova próxima de cepa já exposta?", "alternativas": ["Pelo pecado antigênico original: a resposta é direcionada à cepa conhecida e falha contra a nova", "Porque a cepa nova é sempre resistente ao complemento, e a resposta com anticorpo não consegue opsonizá-la", "Porque a memória de rebanho desaparece após um ano, mesmo em indivíduos vacinados e saudáveis", "Porque a cepa nova não expressa antígenos, e portanto não é reconhecida por nenhuma célula do sistema imune", "Porque o linfócito T CD8+ é inibido pela cepa anterior, que expressa PD-1 em todas as suas superfícies"], "gabarito": "A", "justificativa": "O pecado antigênico original descreve falha em montar resposta contra cepa nova após exposição a cepa próxima. Estratégias de contorno: vacinas multivalentes e adjuvantes (resumo: Imunização, memória de rebanho).", "tecnica": "Pecado antigênico original", "slide": null}, {"id": 14, "nivel": "muito_dificil", "enunciado": "Por que o toxoide é a plataforma indicada quando a doença é causada pela toxina e não pelo micro-organismo inteiro?", "alternativas": ["Porque o toxoide é o próprio micro-organismo vivo, capaz de replicar e de produzir memória celular duradoura", "Porque o toxoide evita a produção de anticorpos, o que impede reações alérgicas à toxina em pacientes com asma", "Porque a toxina atenuada induz anticorpos neutralizantes contra a toxina, que é o mecanismo de dano da doença", "Porque o toxoide contém RNA mensageiro que codifica a toxina, sendo editado pela endonuclease CRISPR", "Porque o toxoide é um vetor viral que integra a toxina no genoma das células musculares do vacinado"], "gabarito": "C", "justificativa": "Toxoide é toxina atenuada, usada quando a doença é causada pela toxina. Induz anticorpos antitoxina, base das vacinas de tétano e difteria (resumo: Imunização, plataformas de produção).", "tecnica": "Toxoide", "slide": null}, {"id": 15, "nivel": "muito_dificil", "enunciado": "Um professor diz que 'a vacina funciona na média, mas não em todos'. Qual conceito de aula explica essa variabilidade individual?", "alternativas": ["A diferença de sexo nos títulos de anticorpo, em que mulheres sempre apresentam resposta menor que homens", "A presença de IgE, que impede a apresentação do antígeno vacinal às células dendríticas do linfonodo", "A corrida entre o período de incubação do patógeno e o tempo de reativação da memória do indivíduo", "A dose de adjuvante de alumínio, que varia conforme a massa corporal e não conforme a imunidade do paciente", "A ausência de linfócitos NK, que determina sozinha se a vacina será eficaz ou não em cada paciente"], "gabarito": "C", "justificativa": "A proteção depende da corrida entre incubação e reativação da memória. Incubação longa e resposta rápida favorecem o hospedeiro; incubação curta ou resposta lenta levam à doença, mesmo no vacinado (resumo: Imunização, memória e proteção).", "tecnica": "Variabilidade individual", "slide": null}], "id": "imuno-thiago-06", "titulo": "Aula 6", "voltar": {"href": "#/agressao/thiago", "texto": "Professor Thiago"}, "manobras": [], "imagens": [], "casos_extremos": []};
window.AULAS["imuno-thiago-07"] = {"subtitulo": "Hipersensibilidade tipo I (alergia)", "pdf": "pdf/thiago/aula-07.pdf", "abas": ["resumo", "glossario", "quiz", "pdf"], "fontes": ["Aula 7 · Hipersensibilidade Tipo I (Prof. Dr. Thiago Corrêa)", "Abbas, Lichtman e Pillai (2019); Murphy (2014); Yu, Freeland e Nadeau (2016); Nuñez-Borque et al. (2022) (citados nos slides)", "Resumo integrado da Prova 2 (Agressão e Defesa II): conteúdo das aulas de Imunologia, Microbiologia e Farmacologia, lido página por página."], "resumo": [{"titulo": "1. Visão geral da hipersensibilidade tipo I", "pontos": [{"t": "Definição", "sub": ["Resposta imune exagerada a antígenos ambientais não microbianos, chamada alergia ou atopia (slide 3). Afeta cerca de 30% da população.", "Tem base genética: a predisposição à produção de IgE é herdada. Os sintomas vão de erupção a broncoconstrição e choque (slide 3)."]}, {"t": "Antígenos (alérgenos)", "sub": ["Proteínas ou compostos ligados a proteínas, de 5 a 70 kDa, estáveis e solúveis nos fluidos corporais (slide 5).", "Exemplos: pólen, ácaros, amendoim, frutos do mar e penicilina (slide 5)."]}]}, {"titulo": "2. Sensibilização: o primeiro contato", "pontos": [{"t": "Sequência de passos", "sub": ["1: a célula dendrítica captura o alérgeno no tecido e migra ao linfonodo.", "2 e 3: células T virgens se diferenciam em Th2 e Tfh.", "4: a Tfh ativa a célula B, que troca para IgE.", "5: a IgE secretada se fixa ao receptor de alta afinidade FcεRI dos mastócitos (slide 11)."]}, {"t": "Papel das citocinas", "sub": ["IL-4 induz a troca para IgE e a expressão de VCAM-1; IL-21 ativa a célula B; IL-5 ativa eosinófilos; IL-13 aumenta a produção de muco (slide 12)."]}]}, {"titulo": "3. Reexposição e degranulação", "pontos": [{"t": "Ativação do mastócito", "sub": ["Um antígeno multivalente liga-se a duas ou mais IgE fixadas, fazendo ligação cruzada dos receptores. O mastócito então degranula (slide 14).", "A ativação também sintetiza mediadores lipídicos e citocinas (complementa a revisão de mastócitos)."]}, {"t": "Mediadores", "sub": ["Pré-formados, liberados em minutos: histamina, proteases e fatores quimiotáticos, armazenados em grânulos (slide 15).", "Neoformados, sintetizados na hora: leucotrienos e prostaglandinas (lipídios) e citocinas (slide 15).", "Efeitos: histamina e prostaglandinas causam vasodilatação e extravasamento; no músculo liso, contração brônquica e intestinal (slide 17)."]}]}, {"titulo": "4. Fase imediata × fase tardia", "pontos": [{"t": "Fase imediata", "sub": ["Começa em minutos após o contato e é mediada pela degranulação do mastócito (slides 10 e 17).", "No teste intradérmico, aparece como pápula e eritema."]}, {"t": "Fase tardia", "sub": ["Começa 2 a 4 horas após o contato (slides 10 e 18).", "Infiltrado de neutrófilos, eosinófilos, basófilos e Th2 (slide 18), mantido pelos mediadores lipídicos e citocinas (IL-3, IL-5, leucotrienos) (complementa Abbas)."]}]}, {"titulo": "5. Anafilaxia e doenças alérgicas", "pontos": [{"t": "Anafilaxia", "sub": ["Reação imediata sistêmica, com edema em muitos tecidos e queda da pressão arterial (slide 20). É emergência.", "Adrenalina é o fármaco de escolha (aula 5 de Gilmar, farmacologia dos adrenérgicos)."]}, {"t": "Asma, rinite, alergia alimentar e urticária", "sub": ["Asma: obstrução recorrente e reversível do fluxo aéreo, com hiperresponsividade do músculo liso brônquico (slide 21).", "Rinite: edema de mucosa, secreção e espirros (slide 22). Alergia alimentar: vômito, diarreia e peristaltismo aumentado (slide 23).", "Urticária: pápula e eritema por mediadores de mastócitos (slide 24). A dermatite atópica compõe a tríade atópica com rinite e asma."]}]}, {"titulo": "6. Alérgeno, mediadores e tempo de cada fase", "pontos": [{"t": "O alérgeno", "sub": ["Alérgeno típico: proteína, ou composto químico ligado a proteína (ex.: penicilina acoplada à albumina).", "Tem baixo peso molecular (5–70 kDa), é estável, glicosilado e muito solúvel, o que facilita a difusão pelos tecidos.", "O tipo I é resposta a antígenos ambientais inócuos e afeta cerca de 30% da população.", "As hipersensibilidades são classificadas pelo mecanismo efetor (Gell e Coombs), não pela doença. São condições crônicas de controle, não de cura, porque em regra o antígeno não é eliminado."]}, {"t": "Citocinas e mediadores", "sub": ["IL-4: troca de classe para IgE; expressão de VCAM-1 no endotélio.", "IL-5: ativação de eosinófilos (eosinofilia no hemograma).", "IL-13: produção excessiva de muco.", "IL-21 (Tfh): ativação e sobrevivência do linfócito B.", "IL-31: prurido intenso, relevante na dermatite atópica.", "Histamina (pré-formada): vasodilatação, aumento de permeabilidade, prurido, broncoconstrição.", "Triptase (pré-formada): dano e lesão tecidual; por isso crises repetidas deixam sequela.", "Prostaglandina D2: vasodilatação e relaxamento do músculo liso.", "Leucotrienos C4/D4/E4: broncoconstrição prolongada, principal responsável.", "PAF e TNF: agregação plaquetária e manutenção da inflamação."]}, {"t": "Fase imediata × fase tardia", "sub": ["Imediata (minutos, até cerca de 2 h): mastócito; mediadores pré-formados e lipídicos (histamina, prostaglandinas, leucotrienos); clínica de pápula e eritema; exemplos: urticária e prick test.", "Tardia (2–4 h após a imediata): neutrófilo, eosinófilo, basófilo e Th2; mediadores são citocinas, que precisam ser sintetizadas; edema maior e sustentado; exemplos: dermatite atópica e asma crônica.", "Consequência terapêutica: o anti-histamínico resolve a fase imediata, mas é inútil contra a crise sustentada por citocinas, que exige corticosteroide."]}]}, {"titulo": "7. Locais de contato e doenças alérgicas", "pontos": [{"t": "Via de contato", "sub": ["Inalado: rinite alérgica e asma.", "Ingerido: vômito e diarreia, por aumento do peristaltismo e edema da mucosa.", "Injetado, ou alimento de absorção muito rápida (amendoim, crustáceos): efeito sistêmico."]}, {"t": "Anafilaxia", "sub": ["Ativação mastocitária generalizada → vasodilatação difusa e aumento de permeabilidade → edema em vários tecidos, queda da pressão e broncoconstrição → choque.", "Tratamento: adrenalina, antagonista fisiológico (vasoconstritor α1 e broncodilatador β2), e não bloqueador do receptor de histamina."]}, {"t": "Asma", "sub": ["Obstrução recorrente e reversível do fluxo aéreo, com hiper-responsividade do músculo liso brônquico, hipertrofia muscular, hipersecreção de muco e infiltrado de eosinófilos e linfócitos.", "Salbutamol é medicação de resgate (agonista β2 broncodilatador). Tratamento de manutenção: corticoide inalatório, porque a doença é sustentada por citocinas."]}, {"t": "Alergia à proteína do leite × intolerância à lactose", "sub": ["Alergia: reação imunológica contra a proteína; costuma ser grave e ocorre com quantidades mínimas.", "Intolerância: deficiência de lactase, problema digestivo, dose-dependente.", "O mecanismo da alergia é o mesmo da defesa antiparasitária (Th2, IgE, eosinófilo, muco, peristaltismo); por isso a clínica é semelhante e a história ajuda a diferenciar diarreia alérgica de parasitose."]}]}, {"titulo": "8. Correção científica e pegadinhas", "pontos": [{"t": "Correções", "sub": ["Em aula, o salbutamol foi chamado de \"vasodilatador\". Ele é broncodilatador, agonista β2-adrenérgico seletivo que relaxa o músculo liso brônquico. Confira em Farmacologia (agonistas β2).", "Reexposição precisa ser ao mesmo alérgeno: sensibilização a ácaro não produz crise ao pólen."]}]}, {"titulo": "9. Para prova", "pontos": [{"t": "Pontos de cobrança", "sub": ["Quem produz a IgE e onde ela se fixa.", "Fase imediata × tardia: tempo, células e mediadores.", "Mediador pré-formado × neoformado."]}]}], "glossario": [{"termo": "Atopia", "tecnica": "Conceito geral", "definicao": "Predisposição genética a responder com IgE a antígenos ambientais, como pólen, ácaros e alimentos.", "slide": 3}, {"termo": "Mastócito", "tecnica": "Efetor da alergia", "definicao": "Célula que possui IgE fixada aos receptores Fc e libera mediadores quando ativada.", "slide": 14}, {"termo": "Mediadores pré-formados", "tecnica": "Mediadores do mastócito", "definicao": "Aminas vasoativas e macromoléculas armazenadas nos grânulos, como a histamina.", "slide": 15}, {"termo": "Reação de fase tardia", "tecnica": "Hipersensibilidade tipo I", "definicao": "Inflamação de 2 a 4 horas após o contato, com neutrófilos, eosinófilos, basófilos e Th2.", "slide": 18}, {"termo": "Anafilaxia", "tecnica": "Reação sistêmica", "definicao": "Reação imediata sistêmica, com edema tecidual e diminuição da pressão arterial.", "slide": 20}, {"termo": "Tríade atópica", "tecnica": "Doenças alérgicas", "definicao": "Associação de dermatite atópica, rinite alérgica e asma.", "slide": 24}, {"termo": "IgE", "tecnica": "Imunoglobulina", "definicao": "Anticorpo que se liga aos mastócitos e basófilos e medeia a hipersensibilidade tipo I.", "slide": 3}, {"termo": "Histamina", "tecnica": "Mediador pré-formado", "definicao": "Amina que causa vasodilatação, aumento de permeabilidade e contração de músculo liso.", "slide": 18}, {"termo": "Leucotrienos e prostaglandinas", "tecnica": "Mediadores neoformados", "definicao": "Lipídios produzidos após a ativação, que sustentam a fase tardia da reação.", "slide": 18}], "caso": {"titulo": "Caso: criança com chiado e reação após alimento", "perfil": "Sensibilização, reexposição e mediadores do mastócito.", "etapas": [{"titulo": "Etapa 1: chiado após exposição a ácaros", "texto": "Criança de 7 anos com crises de chiado e espirros, principalmente em dias de limpeza da casa. Há histórico familiar de asma e rinite. Os testes mostram IgE específica para ácaros.", "perguntas": [{"pergunta": "Qual conjunto de achados melhor descreve a doença desta criança, segundo a aula?", "alts": ["Tríade atópica, com rinite, asma e predisposição genética à alergia", "Hipersensibilidade tipo II, com anticorpos contra antígenos teciduais", "Hipersensibilidade tipo IV, com linfócitos T citotóxicos destruindo células", "Imunodeficiência primária, com ausência de IgA sérica", "Doença do enxerto contra o hospedeiro, com células T do doador"], "erradas": ["Tipo II envolve anticorpos contra antígenos teciduais, não ácaros inalados.", "Tipo IV é mediado por linfócitos T, sem IgE.", "Imunodeficiência primária não explica IgE contra ácaros.", "DECH ocorre após transplante de células-tronco, fora deste caso."], "justificativa": "A tríade atópica inclui dermatite atópica, rinite alérgica e asma, com predisposição genética (slides 3 e 24)."}]}, {"titulo": "Etapa 2: reação após amendoim", "texto": "A mesma criança, já sensibilizada, come amendoim pela primeira vez. Em minutos apresenta urticária, edema de lábios e queda da pressão arterial.", "perguntas": [{"pergunta": "Qual mecanismo explica a reação imediata e sistêmica nessa segunda exposição?", "alts": ["Ligação cruzada do alérgeno à IgE dos mastócitos, com liberação de mediadores", "Destruição direta das células-alvo por linfócitos T citotóxicos", "Deposição de imunocomplexos nos vasos e ativação do complemento", "Apresentação do antígeno por MHC de classe I sem anticorpos", "Ação de anticorpos contra receptores que bloqueiam sua função"], "erradas": ["Destruição direta por T citotóxico é o mecanismo do tipo IV.", "Imunocomplexos são o mecanismo do tipo III.", "Apresentação por MHC de classe I não explica a reação imediata.", "Bloqueio de receptores é o mecanismo do tipo II."], "justificativa": "Na reexposição, o alérgeno liga-se à IgE dos mastócitos, que degranulam, levando a anafilaxia (slides 14 e 20)."}]}]}, "questoes": [{"id": 1, "nivel": "muito_dificil", "enunciado": "Um paciente é sensibilizado a ácaro e depois tem crise de asma ao contato com pólen. Qual é a explicação imunológica mais correta?", "alternativas": ["A IgE anti-ácaro reconhece o pólen por reação cruzada e ativa o mastócito, desde que haja IL-5 suficiente", "O pólen ativa diretamente o linfócito Th1, que produz IFN-γ e libera histamina no tecido brônquico do paciente", "A reexposição precisa ser ao mesmo alérgeno; a IgE anti-ácaro não ativa mastócitos sensibilizados ao pólen", "A sensibilização ao ácaro gera células B de memória que reconhecem pólen e liberam triptase imediatamente", "O pólen induz a troca de classe para IgG4, que se liga ao receptor FcεRI do mastócito e causa degranulação"], "gabarito": "C", "justificativa": "Reexposição ao mesmo alérgeno é o que dispara a degranulação, porque a IgE se liga ao alérgeno multivalente e faz ligação cruzada. Sensibilização a ácaro não produz crise ao pólen (resumo: Hipersensibilidade tipo I, pegadinha).", "tecnica": "Reexposição", "slide": null}, {"id": 2, "nivel": "muito_dificil", "enunciado": "Em um paciente recém-exposto a um alérgeno, qual evento ocorre na fase de sensibilização, antes de qualquer sintoma?", "alternativas": ["O mastócito é carregado de IgE, sem degranulação e sem manifestação clínica", "O mastócito degranula imediatamente, liberando histamina e triptase na primeira exposição ao alérgeno", "Os linfócitos Th1 produzem IFN-γ, que destrói o alérgeno e impede a formação de IgE", "Os eosinófilos são recrutados em massa para o tecido, causando edema e prurido nas primeiras horas", "O alérgeno é fagocitado por neutrófilos, que liberam leucotrienos e causam broncoconstrição aguda"], "gabarito": "A", "justificativa": "Na sensibilização, a célula dendrítica apresenta o alérgeno, a célula Th2 e a Tfh induzem IgE, e o mastócito é apenas armado. A degranulação exige reexposição (resumo: Hipersensibilidade tipo I).", "tecnica": "Sensibilização", "slide": null}, {"id": 3, "nivel": "muito_dificil", "enunciado": "Na sequência da sensibilização, a IL-4 tem papel central. Qual é o efeito dessa citocina sobre a célula B e sobre o endotélio?", "alternativas": ["Induz a troca de classe para IgA e expressão de MHC de classe II no endotélio vascular", "Induz a apoptose de linfócitos B e a expressão de E-selectina no endotélio ativado", "Induz a troca de classe para IgM e liberação de histamina pré-formada pelos mastócitos", "Induz a troca de classe para IgE e expressão de VCAM-1 no endotélio", "Induz a troca de classe para IgG3 e expressão de CD40L nas células endoteliais do capilar"], "gabarito": "D", "justificativa": "IL-4 induz troca de classe para IgE e a expressão de VCAM-1 no endotélio (resumo: Hipersensibilidade tipo I, citocinas e mediadores).", "tecnica": "IL-4", "slide": null}, {"id": 4, "nivel": "muito_dificil", "enunciado": "Qual citocina é responsável pela ativação e pela manutenção de eosinófilos, e como isso aparece no hemograma?", "alternativas": ["IL-4, com basofilia no hemograma e aumento de linfócitos T CD8+", "IL-5, com eosinofilia no hemograma", "IL-13, com neutrofilia no hemograma e leucocitose de origem medular", "IL-31, com trombocitose no hemograma e anemia de caráter hemolítico", "IL-21, com linfopenia no hemograma e queda acentuada de plaquetas"], "gabarito": "B", "justificativa": "IL-5 ativa eosinófilos, resultando em eosinofilia no hemograma. IL-13 aumenta a produção de muco; IL-31 causa prurido intenso (resumo: Hipersensibilidade tipo I, citocinas).", "tecnica": "IL-5 e eosinófilos", "slide": null}, {"id": 5, "nivel": "muito_dificil", "enunciado": "Em uma crise de asma, o mediador responsável pela broncoconstrição prolongada é o leucotrieno. Qual é o tipo de mediador e como ele é produzido?", "alternativas": ["Amina pré-formada armazenada em grânulos do mastócito, liberada em segundos após a degranulação", "Proteína de estoque armazenada no grânulo do eosinófilo, liberada apenas na fase tardia da reação", "Citocina sintetizada no núcleo do linfócito Th2, que precisa de horas para ser transcrita e traduzida", "Enzima de degradação da matriz extracelular, produzida pelo fibroblasto após a ativação por IL-31", "Lipídeo sintetizado sob demanda a partir do ácido araquidônico, pela via da lipoxigenase"], "gabarito": "E", "justificativa": "Leucotrienos são lipídios sintetizados sob demanda a partir do ácido araquidônico, pela via da lipoxigenase. São os principais responsáveis pela broncoconstrição prolongada (resumo: Hipersensibilidade tipo I, citocinas).", "tecnica": "Leucotrienos", "slide": null}, {"id": 6, "nivel": "muito_dificil", "enunciado": "Por que o anti-histamínico resolve a urticária imediata, mas não controla uma crise de dermatite atópica sustentada?", "alternativas": ["A histamina só atua na fase tardia, e a urticária imediata depende exclusivamente de IgG bloqueante", "O anti-histamínico bloqueia a IgE, mas não atua sobre citocinas, que são produzidas apenas pelos neutrófilos", "Histamina é pré-formada e liberada de imediato; a crise tardia exige citocinas", "A dermatite atópica é causada por IgG4, que não é ativada pela histamina nem por nenhum anti-H1 disponível", "A urticária é causada por IL-5, que o anti-histamínico não consegue bloquear por ser uma citocina"], "gabarito": "C", "justificativa": "Histamina é estocada no grânulo e liberada de imediato; citocinas precisam ser sintetizadas, por isso a fase tardia exige corticosteroide (resumo: Hipersensibilidade tipo I, fase imediata × tardia).", "tecnica": "Fase imediata × tardia", "slide": null}, {"id": 7, "nivel": "muito_dificil", "enunciado": "Um paciente tem reação alérgica após ingestão de amendoim, com queda de pressão e broncoconstrição. Qual é o fármaco de escolha e por que ele funciona?", "alternativas": ["Difenidramina, que bloqueia o receptor H1 e impede a histamina de se ligar à célula endotelial", "Cromoglicato, que estabiliza o mastócito e impede a degranulação em toda a circulação sistêmica", "Corticosteroide, que inibe a síntese de citocinas e reduz a degranulação em poucos segundos", "Salbutamol, que é vasodilatador e relaxa a musculatura lisa vascular pelo bloqueio de α2", "Adrenalina, pelo efeito oposto: vasoconstrição α1 e broncodilatação β2"], "gabarito": "E", "justificativa": "Na anafilaxia, a adrenalina é o fármaco de escolha. Não bloqueia receptor de histamina; produz efeitos opostos (vasoconstrição α1 e broncodilatação β2) (resumo: Hipersensibilidade tipo I, anafilaxia).", "tecnica": "Anafilaxia", "slide": null}, {"id": 8, "nivel": "muito_dificil", "enunciado": "Uma alergia alimentar por ingestão de amendoim tem efeito sistêmico, enquanto uma alergia por inalação costuma ser localizada. Qual critério determina essa diferença?", "alternativas": ["A cor do alérgeno, porque pigmentos escuros ativam mais mastócitos do que pigmentos claros no mesmo tecido", "Via de contato e velocidade de absorção do alérgeno", "O peso molecular do alérgeno, porque moléculas acima de 200 kDa ativam apenas o sistema nervoso central", "O número de eosinófilos circulantes, porque pacientes com mais eosinófilos sempre têm reação sistêmica", "A idade do paciente, porque crianças têm mastócitos que só degranulam na fase tardia da reação alérgica"], "gabarito": "B", "justificativa": "O local de contato determina o tecido onde mastócitos e Th2 são ativados. Alimentos de absorção muito rápida (amendoim, crustáceos) produzem efeito sistêmico (resumo: Hipersensibilidade tipo I, doenças alérgicas).", "tecnica": "Via de contato", "slide": null}, {"id": 9, "nivel": "muito_dificil", "enunciado": "Um paciente com asma tem obstrução reversível, hipertrofia muscular e infiltrado de eosinófilos. Por que o corticoide inalatório é preferido ao salbutamol como tratamento de manutenção?", "alternativas": ["Porque o salbutamol aumenta a produção de IgE, o que piora a sensibilização e a degranulação de mastócitos", "A inflamação é sustentada por citocinas, que o broncodilatador não controla", "Porque o corticoide inibe a PLA2 apenas nas vias aéreas e não tem efeito sobre o restante do organismo", "Porque o salbutamol bloqueia o receptor β2 e impede a broncodilatação em pacientes com hiper-responsividade", "Porque o corticoide é broncodilatador potente, e o salbutamol serve apenas para aliviar a dor torácica"], "gabarito": "B", "justificativa": "Salbutamol é medicação de resgate. A asma é sustentada por inflamação e citocinas, por isso o tratamento de manutenção é corticoide inalatório (resumo: Hipersensibilidade tipo I, asma).", "tecnica": "Asma e corticoide", "slide": null}, {"id": 10, "nivel": "muito_dificil", "enunciado": "Um estudante diz que a intolerância à lactose é uma alergia, porque ambas causam diarreia após o leite. Qual é a correção mais precisa?", "alternativas": ["Alergia e intolerância são sinônimas, e a diferença é apenas o tempo de início dos sintomas após a ingestão", "Intolerância é imunológica e grave, enquanto a alergia é digestiva e sempre leve, com dose mínima tolerada", "Ambas são deficiências de IgE, que impedem a absorção de lactose e de proteína no intestino delgado", "Alergia é imunológica contra a proteína; intolerância é deficiência de lactase", "Ambas são causadas por bactérias do cólon que produzem histamina, e a diferença está apenas no antibiótico"], "gabarito": "D", "justificativa": "Alergia à proteína do leite é imunológica, grave e ocorre com quantidades mínimas. Intolerância à lactose é deficiência de lactase, com gravidade dose-dependente (resumo: Hipersensibilidade tipo I, correlação clínica).", "tecnica": "Alergia × intolerância", "slide": null}, {"id": 11, "nivel": "muito_dificil", "enunciado": "Por que a histamina causa edema e pápula, enquanto a prostaglandina D2 causa vasodilatação sem edema proeminente?", "alternativas": ["Porque a histamina aumenta a produção de muco, e o muco retém água no interstício tecidual", "Porque a prostaglandina D2 bloqueia a apresentação antigênica pelo endotélio e impede a extravasação", "Porque a histamina é sintetizada no núcleo do linfócito, e a prostaglandina D2 é liberada pelo fígado", "Porque a histamina atua sobre H1 e separa as células endoteliais, aumentando a permeabilidade vascular", "Porque a prostaglandina D2 ativa apenas a via do complemento, e a histamina ativa somente a via alternativa"], "gabarito": "D", "justificativa": "Histamina atua em H1, dilata vênulas pós-capilares e separa células endoteliais, causando edema e pápula. PGD2 causa vasodilatação e relaxamento de músculo liso (resumo: Hipersensibilidade tipo I, mediadores).", "tecnica": "Histamina e edema", "slide": null}, {"id": 12, "nivel": "muito_dificil", "enunciado": "Qual relação entre citocinas e mediadores está correta na hipersensibilidade tipo I?", "alternativas": ["IL-21 ativa o linfócito B, enquanto a IL-13 aumenta a produção de muco nas vias aéreas", "IL-21 ativa o mastócito, enquanto a IL-13 induz a troca de classe para IgE no linfócito B", "IL-13 ativa eosinófilos, enquanto a IL-5 aumenta a produção de muco e de prostaglandina D2", "IL-31 aumenta a broncoconstrição, enquanto o leucotrieno C4 causa prurido intenso na pele", "IL-4 causa edema por separação endotelial, enquanto a triptase induz troca de classe para IgG"], "gabarito": "A", "justificativa": "IL-21 (Tfh) ativa e mantém o linfócito B; IL-13 aumenta a produção de muco; IL-5 ativa eosinófilos; IL-31 causa prurido (resumo: Hipersensibilidade tipo I, citocinas).", "tecnica": "Citocinas e funções", "slide": null}, {"id": 13, "nivel": "muito_dificil", "enunciado": "Um alérgeno típico é descrito como 'proteína ou composto ligado a proteína, com baixo peso molecular'. Qual faixa de peso molecular é descrita em aula e por que ela facilita a difusão?", "alternativas": ["200 a 500 kDa; moléculas grandes e insolúveis se acumulam nos linfonodos e não se difundem", "1 a 5 kDa; moléculas muito pequenas são sempre destruídas pelo complemento antes da apresentação", "70 a 150 kDa; moléculas médias se ligam ao receptor FcεRI e não se difundem pelos tecidos", "Acima de 1.000 kDa; apenas polímeros gigantes atravessam o epitélio e alcançam a célula dendrítica", "5 a 70 kDa; moléculas pequenas, estáveis e solúveis se difundem bem pelos tecidos"], "gabarito": "E", "justificativa": "O alérgeno típico tem 5–70 kDa, é estável, glicosilado e muito solúvel, o que facilita a difusão pelos tecidos (resumo: Hipersensibilidade tipo I, alérgeno).", "tecnica": "Propriedades do alérgeno", "slide": null}, {"id": 14, "nivel": "muito_dificil", "enunciado": "Por que a adrenalina é mais eficaz na anafilaxia do que o bloqueador de receptor H1, mesmo quando ambos reduzem sintomas?", "alternativas": ["Adrenalina tem efeitos opostos aos da histamina, sem bloquear seu receptor", "Porque o bloqueador H1 impede a degranulação do mastócito, enquanto a adrenalina atua apenas sobre a IgE circulante", "Porque a adrenalina é anti-histamínica de primeira geração e impede a ligação da histamina a todos os receptores", "Porque o bloqueador H1 é broncodilatador β2, e a adrenalina é apenas um antiarrítmico sem efeito vascular", "Porque o bloqueador H1 aumenta a permeabilidade vascular, e a adrenalina reduz a permeabilidade do endotélio"], "gabarito": "A", "justificativa": "Adrenalina é antagonista fisiológico: vasoconstrição α1 e broncodilatação β2. Anti-H1 bloqueia o receptor, mas não reverte o choque com a mesma eficácia (resumo: Hipersensibilidade tipo I, anafilaxia).", "tecnica": "Adrenalina × anti-H1", "slide": null}, {"id": 15, "nivel": "muito_dificil", "enunciado": "Por que a fase tardia da reação alérgica tende a causar lesão tecidual mais duradoura do que a fase imediata?", "alternativas": ["Porque a histamina pré-formada se acumula no tecido e não é degradada, o que mantém o edema por horas", "Porque a IgE é destruída, e a ausência de IgE impede o fechamento do processo inflamatório agudo", "Neutrófilo, eosinófilo e Th2 mantêm a inflamação com citocinas sintetizadas", "Porque o mastócito deixa de degranular e acumula triptase, que se torna tóxica para os fibroblastos locais", "Porque o endotélio cicatriza com fibrose imediata, o que prende o alérgeno dentro do tecido por dias"], "gabarito": "C", "justificativa": "Na fase tardia, neutrófilo, eosinófilo, basófilo e Th2 mantêm a inflamação com citocinas sintetizadas. A triptase, pré-formada e liberada, causa dano tecidual e deixa sequela após crises repetidas (resumo: Hipersensibilidade tipo I).", "tecnica": "Fase tardia e sequela", "slide": null}], "id": "imuno-thiago-07", "titulo": "Aula 7", "voltar": {"href": "#/agressao/thiago", "texto": "Professor Thiago"}, "manobras": [], "imagens": [], "casos_extremos": []};
window.AULAS["imuno-thiago-08"] = {"subtitulo": "Reações de hipersensibilidade tipo II, III e IV", "pdf": "pdf/thiago/aula-08.pdf", "abas": ["resumo", "glossario", "quiz", "tabela", "pdf"], "fontes": ["Aula 8 · Reações de Hipersensibilidade Tipo II, III e IV (Prof. Dr. Thiago Corrêa)", "Abbas, Lichtman e Pillai (2019); Murphy (2014); Katsarou et al. (2017); Osmosis (2022) (citados nos slides)", "Resumo integrado da Prova 2 (Agressão e Defesa II): conteúdo das aulas de Imunologia, Microbiologia e Farmacologia, lido página por página."], "tabela": {"titulo": "Comparativo dos quatro tipos de hipersensibilidade", "colunas": ["", "Tipo I", "Tipo II", "Tipo III", "Tipo IV"], "linhas": [["Quem causa a lesão", "IgE nos mastócitos", "Anticorpos contra antígenos teciduais", "Imunocomplexos (antígeno solúvel + anticorpo)", "Linfócitos T (Th1, Th17 e T citotóxico)"], ["Alvo", "Antígenos ambientais não microbianos", "Antígenos de células ou tecidos do próprio corpo", "Antígenos solúveis, próprios ou estranhos", "Autoantígenos nas doenças citadas"], ["Mecanismo principal", "Degranulação de mastócitos e mediadores", "Opsonização, inflamação por complemento e alteração fisiológica", "Ativação do complemento e receptores Fc nos leucócitos", "Citocinas inflamatórias e destruição direta das células-alvo"], ["Exemplos citados", "Rinite, asma, anafilaxia, urticária", "Doença de Graves, miastenia grave, febre reumática", "Lúpus eritematoso sistêmico, glomerulonefrite", "Artrite reumatoide, esclerose múltipla, diabetes tipo 1"], ["Slides", "Aula 7", "3 a 8", "10 a 16", "18 a 25"]]}, "resumo": [{"titulo": "1. Hipersensibilidade tipo II: anticorpo contra célula ou tecido", "pontos": [{"t": "Mecanismos de lesão", "sub": ["Opsonização e fagocitose: o anticorpo marca a célula e os fagócitos a destroem (slide 3).", "Inflamação: a ativação do complemento libera C5a e C3a, que recrutam neutrófilos e macrófagos (slide 4).", "Alteração fisiológica: o anticorpo ativa ou bloqueia um receptor, sem inflamação e sem destruição (slides 6 e 7)."]}, {"t": "Exemplos", "sub": ["Doença de Graves (epônimo: Graves): anticorpo ativa o receptor do TSH no folículo tireoidiano, com hipertireoidismo (slides 5 e 6).", "Miastenia gravis: anticorpo bloqueia o receptor de acetilcolina na placa motora; fraqueza flutuante, sem inflamação (slide 7).", "Febre reumática: reação cruzada entre anticorpo anti-estreptococo e tecido do miocárdio (slide 8)."]}]}, {"titulo": "2. Hipersensibilidade tipo III: imunocomplexos", "pontos": [{"t": "Mecanismo", "sub": ["Antígeno solúvel, próprio ou estranho (microbiano ou medicamento), forma imunocomplexos com anticorpo (slides 10 e 13).", "Os complexos se depositam em vasos, membrana sinovial, membrana basal glomerular e plexos coroides (slide 10).", "A lesão vem da ativação do complemento e dos receptores Fc de leucócitos (slides 11 e 12)."]}, {"t": "Lúpus eritematoso sistêmico", "sub": ["Doença crônica, multissistêmica e recidivante, predominante em mulheres (10:1), com anticorpos antinucleares (slide 15).", "Manifestações: erupções, artrite, glomerulonefrite, anemia hemolítica, trombocitopenia e envolvimento do SNC (slide 15).", "TLR7 e TLR9 ativam células B específicas para autoantígenos nucleares (slide 16)."]}]}, {"titulo": "3. Hipersensibilidade tipo IV: mediada por linfócitos T", "pontos": [{"t": "Mecanismos", "sub": ["Lesão por citocinas inflamatórias de Th1 e Th17, ou por destruição direta pelo T citotóxico (slides 18 a 20).", "Th1 produz IFN-gama, que ativa macrófagos; Th17 produz IL-17, que recruta neutrófilos (slide 20)."]}, {"t": "Exemplos", "sub": ["Artrite reumatoide: tabagismo e algumas infecções induzem citrulinação de proteínas próprias; as células sinoviais produzem colagenases (slides 22 e 23).", "Esclerose múltipla: Th1 e Th17 atacam a mielina (slide 24).", "Diabetes tipo 1: destruição das células β das ilhotas pancreáticas (slide 25)."]}]}, {"titulo": "4. Quadro comparativo", "pontos": [{"t": "Diferenças-chave", "sub": ["II: anticorpo contra antígeno celular ou tecidual; lesão localizada.", "III: antígeno solúvel e imunocomplexos; lesão sistêmica nos vasos.", "IV: linfócitos T, sem anticorpo como mediador principal (slide 27).", "Mnemônico: II = alvo fixo; III = complexo circulante; IV = T."]}]}, {"titulo": "5. Quadro integrado das quatro hipersensibilidades", "pontos": [{"t": "Mediador, antígeno e distribuição", "sub": ["Tipo I: mediador IgE; antígeno ambiental e inócuo; degranulação do mastócito; lesão local ou sistêmica (rinite, asma, anafilaxia, urticária).", "Tipo II: mediador IgG/IgM; antígeno fixo à membrana celular ou à matriz extracelular; opsonização, complemento ou alteração funcional; lesão tecido-específica (anemia hemolítica autoimune, Graves, miastenia gravis, febre reumática).", "Tipo III: mediador IgG/IgM; antígeno solúvel e circulante; imunocomplexo deposita, complemento, neutrófilo degranula; lesão sistêmica (lúpus, doença do soro, glomerulonefrite pós-estreptocócica, poliarterite nodosa).", "Tipo IV: mediador linfócito T; antígeno próprio ou microbiano apresentado no MHC; citocinas (Th1 → macrófago; Th17 → neutrófilo) ou citotoxicidade CD8+; lesão tecido-específica (artrite reumatoide, esclerose múltipla, diabetes tipo 1, doença celíaca)."]}, {"t": "Conceito-chave", "sub": ["Toda doença autoimune é reação de hipersensibilidade, mas nem toda hipersensibilidade é autoimune: a alergia é o contraexemplo.", "Um mesmo paciente pode ter dois tipos ao mesmo tempo: o lúpus é modelo de tipo III, mas sua anemia hemolítica e plaquetopenia são de tipo II.", "Regra da prova: antígeno fixo produz lesão localizada; antígeno solúvel produz doença sistêmica."]}]}, {"titulo": "6. Tipo II em detalhe: três mecanismos", "pontos": [{"t": "(1) Opsonização e fagocitose", "sub": ["IgG e IgM revestem a célula e, com C3b, funcionam como opsoninas; o fagócito reconhece pelos receptores Fc e de complemento e destrói a célula. Exemplo: anemia hemolítica autoimune; a anemia é imunológica, não carencial."]}, {"t": "(2) Inflamação", "sub": ["O anticorpo ligado ativa o complemento pela via clássica (C1 reconhece a porção Fc). C3a e C5a atuam como quimiocinas e recrutam neutrófilos e macrófagos; a degranulação desses leucócitos lesa o tecido."]}, {"t": "(3) Alteração funcional, sem inflamação", "sub": ["O autoanticorpo se liga a um receptor e altera sua função, sem destruir a célula.", "Doença de Graves: anticorpo estimula o receptor de TSH; produção autônoma de T3 e T4; TSH suprimido; hipermetabolismo, emagrecimento, irritabilidade.", "Miastenia gravis: anticorpo bloqueia o receptor nicotínico de acetilcolina na placa motora; a ACh é produzida, mas não encontra receptor livre; fraqueza flutuante que piora com esforço e melhora com repouso; ptose, diplopia, fala anasalada, disfagia."]}, {"t": "Pegadinhas", "sub": ["No Graves o TSH está baixo, não alto: o folículo já é estimulado pelo autoanticorpo e não depende mais do TSH.", "Miastenia gravis não é doença neurodegenerativa: não há morte neuronal, só bloqueio do receptor. Piridostigmina (anticolinesterásico) compensa o quadro (ver Farmacologia, aula 4)."]}, {"t": "Febre reumática e mimetismo molecular (já caiu)", "sub": ["Começa como infecção e termina como autoimunidade: a proteína M do S. pyogenes é estruturalmente semelhante à miosina cardíaca; o anticorpo contra a bactéria reage com o miocárdio.", "Surgem miocardite e artrite, tipicamente entre 5 e 15 anos, após faringoamigdalite mal tratada.", "Ênfase do professor: mimetismo molecular foi cobrado na questão 12 do 1.º bimestre; o enunciado pedia a interação entre predisposição genética (HLA) e fator ambiental (infecção). Esse eixo deve reaparecer em artrite reumatoide ou lúpus."]}]}, {"titulo": "7. Tipo III: imunocomplexos em detalhe", "pontos": [{"t": "Formação e depósito", "sub": ["Antígeno solúvel forma com o anticorpo aglomerados (imunocomplexos). Produzimos imunocomplexos rotineiramente e os depuramos sem adoecer; a doença aparece quando a concentração ultrapassa um limiar.", "Grandes e pesados, precipitam e se depositam em vasos, membrana sinovial, membrana basal glomerular e plexos coroides. Por poderem parar em qualquer lugar, a doença é sistêmica.", "Sequência: depósito → complemento pela via clássica → C3a/C5a recrutam neutrófilos → o complexo é grande demais para fagocitose → o neutrófilo degranula sobre ele, liberando enzimas proteolíticas e espécies reativas de oxigênio → lesão do próprio tecido → vasculite, glomerulonefrite, artrite."]}, {"t": "Pegadinha: a curva da doença por imunocomplexos", "sub": ["Logo após a injeção do antígeno ainda não há anticorpos; o complemento é ativado pela via alternativa. A via clássica entra depois, quando os anticorpos aparecem e os complexos se formam.", "As lesões sobem e descem com a curva do imunocomplexo: sem complexo, não há doença. Por isso a doença do soro por penicilina é transitória (retira-se o antígeno), e a autoimunidade é crônica (não se remove o autoantígeno)."]}]}, {"titulo": "8. Tipo IV: mediada por linfócitos T", "pontos": [{"t": "Dois mecanismos", "sub": ["CD4+ ativado produz citocinas que recrutam e ativam a resposta inata: Th1 secreta IFN-γ e ativa macrófagos; Th17 secreta IL-17 (e IL-22) e recruta neutrófilos.", "CD8+ destrói diretamente a célula-alvo.", "Quem causa a lesão é, em grande parte, a resposta inata estimulada pela adaptativa; o gatilho, e portanto o mecanismo definidor, é o linfócito T."]}, {"t": "Correção científica", "sub": ["Em aula afirmou-se que \"Th17 produz interferon-gama\". A Th17 produz IL-17 (e IL-22), que recruta neutrófilos; quem produz IFN-γ é a Th1, que ativa macrófagos. O slide traz a versão correta. (Abbas, Lichtman & Pillai, 9.ª ed.)"]}]}, {"titulo": "9. Para prova", "pontos": [{"t": "Pontos de cobrança", "sub": ["Classificar a doença pelo mecanismo (Graves, miastenia, LES, AR, EM, DM1).", "Diferença entre II e III.", "Papel de Th1 × Th17 no tipo IV."]}]}], "glossario": [{"termo": "Opsonização", "tecnica": "Hipersensibilidade tipo II", "definicao": "Revestimento de antígenos por anticorpos ou complemento, que facilita a fagocitose.", "slide": 3}, {"termo": "Imunocomplexo", "tecnica": "Hipersensibilidade tipo III", "definicao": "Anticorpo ligado a antígeno solúvel, próprio ou estranho, que se deposita nos tecidos.", "slide": 10}, {"termo": "Lúpus eritematoso sistêmico (LES)", "tecnica": "Hipersensibilidade tipo III", "definicao": "Doença autoimune crônica multissistêmica, com anticorpos antinucleares, predominante em mulheres.", "slide": 15}, {"termo": "Citrulinação", "tecnica": "Artrite reumatoide", "definicao": "Modificação de proteínas próprias, induzida por tabagismo e algumas infecções, que favorece a quebra de tolerância.", "slide": 23}, {"termo": "Células Th17", "tecnica": "Hipersensibilidade tipo IV", "definicao": "Subpopulação de T CD4+ que produz IL-17 e recruta neutrófilos.", "slide": 20}, {"termo": "Células β das ilhotas", "tecnica": "Diabetes tipo 1", "definicao": "Células produtoras de insulina, destruídas por processo imunomediado no diabetes tipo 1.", "slide": 25}, {"termo": "Doença de Graves", "tecnica": "Epônimo", "definicao": "Hipertireoidismo por anticorpo que ativa o receptor do TSH; tipo II de hipersensibilidade.", "slide": 5, "epônimo": "Graves"}], "caso": {"titulo": "Caso: lúpus e doença de Graves", "perfil": "Diferenciação dos mecanismos de lesão tipo II e tipo III.", "etapas": [{"titulo": "Etapa 1: lesão renal e cutânea", "texto": "Mulher de 26 anos com rash malar, artrite em mãos e joelhos, proteinúria e anemia hemolítica. O FAN é positivo. Biópsia renal mostra depósitos de imunoglobulina e complemento na membrana basal glomerular.", "perguntas": [{"pergunta": "Qual mecanismo de lesão melhor explica o quadro renal, segundo a aula?", "alts": ["Imunocomplexos depositados na membrana basal, com ativação do complemento", "Anticorpos contra receptores do TSH, sem inflamação do tecido", "Linfócitos T citotóxicos destruindo diretamente os podócitos", "Degranulação de mastócitos por IgE contra antígenos ambientais", "Anticorpos contra receptores da acetilcolina, com bloqueio da transmissão"], "erradas": ["Anticorpos contra receptor de TSH descrevem a doença de Graves.", "Destruição direta por T citotóxico é o mecanismo do tipo IV.", "Mastócitos e IgE são o mecanismo da hipersensibilidade tipo I.", "Anticorpos contra receptores da acetilcolina descrevem a miastenia grave."], "justificativa": "No LES, imunocomplexos se depositam na membrana basal dos glomérulos e ativam o complemento (slides 10 e 15)."}]}, {"titulo": "Etapa 2: taquicardia e bócio", "texto": "Mulher de 40 anos com perda de peso, taquicardia, tremor e bócio difuso. Os anticorpos anti-receptor de TSH são positivos. Não há inflamação tecidual relevante na biópsia.", "perguntas": [{"pergunta": "Qual é o mecanismo da doença desta paciente, segundo a aula?", "alts": ["Anticorpos ativam o receptor do folículo tireoidiano, sem inflamação", "Imunocomplexos depositam-se nos vasos da tireoide com inflamação", "Linfócitos Th17 recrutam neutrófilos para destruir o folículo", "Anticorpos contra receptores de acetilcolina bloqueiam a função", "Células Treg são destruídas, levando à destruição direta do tecido"], "erradas": ["Imunocomplexos e inflamação descrevem o tipo III, não esta doença.", "Th17 com neutrófilos descreve a inflamação mediada por citocinas, do tipo IV.", "Anticorpos contra receptores de acetilcolina descrevem a miastenia grave.", "Destruição de Treg não é o mecanismo descrito para a doença de Graves."], "justificativa": "Na doença de Graves, anticorpos ativam o receptor do folículo tireoidiano, sem inflamação ou dano tecidual (slides 5 e 6)."}]}]}, "questoes": [{"id": 1, "nivel": "muito_dificil", "enunciado": "Em um paciente com anemia hemolítica autoimune, o anticorpo IgG reveste a hemácia. Qual é o mecanismo principal de destruição?", "alternativas": ["Degranulação do mastócito sobre a hemácia, com liberação de histamina e de triptase no sangue periférico", "Formação de imunocomplexos solúveis que se depositam no endotélio e ativam a via alternativa do complemento", "Opsonização e fagocitose, com C3b e receptores Fc e de complemento no fagócito", "Ativação de linfócitos Th1 que produzem IFN-γ e destroem a hemácia por citotoxicidade direta do CD8+", "Bloqueio funcional do receptor de eritropoetina, que impede a maturação da hemácia na medula óssea"], "gabarito": "C", "justificativa": "No tipo II, IgG e C3b revestem a célula e funcionam como opsoninas. O fagócito reconhece pelos receptores Fc e de complemento e destrói a célula (resumo: Hipersensibilidade II, opsonização).", "tecnica": "Tipo II: opsonização", "slide": null}, {"id": 2, "nivel": "muito_dificil", "enunciado": "Na doença de Graves, o TSH sérico está suprimido. Por que o hormônio tireoidiano está elevado mesmo com TSH baixo?", "alternativas": ["O TSH inibe a produção de T3 e T4, mas o autoanticorpo bloqueia essa inibição e libera o hormônio", "O autoanticorpo estimula o receptor de TSH, e o folículo produz T3 e T4 independentemente do TSH", "O TSH é produzido pelo fígado, que deixa de sintetizar tireoglobulina e libera T3 sem controle", "O autoanticorpo destrói o TSH no sangue, o que aumenta a sensibilidade do folículo ao iodo circulante", "O TSH é reduzido pelo complemento, que ativa a via clássica e libera T3 pelos mastócitos da tireoide"], "gabarito": "B", "justificativa": "No Graves, o autoanticorpo é agonista do receptor de TSH. O folículo produz T3 e T4 sem depender do TSH, que fica suprimido pelo feedback negativo (resumo: Hipersensibilidade II, alteração funcional).", "tecnica": "Graves", "slide": null}, {"id": 3, "nivel": "muito_dificil", "enunciado": "Na miastenia gravis, a fraqueza piora com esforço repetido e melhora com repouso. Qual é o mecanismo do autoanticorpo que explica esse padrão?", "alternativas": ["Estimula o receptor nicotínico, que se dessensibiliza após o primeiro estímulo e deixa de responder ao sinal", "Destrói a acetilcolina no sangue, e o repouso restaura a concentração do neurotransmissor no músculo", "Bloqueia a calcineurina nos neurônios motores, o que impede a liberação de acetilcolina em qualquer intensidade", "Bloqueia o receptor nicotínico; a acetilcolina encontra menos receptores livres", "Inibe a acetilcolinesterase, o que aumenta a degradação do neurotransmissor na fenda sináptica do músculo"], "gabarito": "D", "justificativa": "Na miastenia, autoanticorpo bloqueia o receptor nicotínico. A acetilcolina é produzida, mas não encontra receptor livre. Com esforço, o déficit de receptores se acumula (resumo: Hipersensibilidade II; Farmacologia, colinérgicos).", "tecnica": "Miastenia gravis", "slide": null}, {"id": 4, "nivel": "muito_dificil", "enunciado": "Por que a piridostigmina melhora a miastenia gravis, mas não cura a doença?", "alternativas": ["Bloqueia a produção de autoanticorpos IgG pelos plasmócitos, e por isso o tratamento é definitivo", "Estimula a destruição de receptores nicotínicos pelos mastócitos, o que reduz a fraqueza muscular de forma permanente", "Aumenta a acetilcolina na fenda, mas não elimina os autoanticorpos, que exigem corticoide ou imunossupressor", "Inibe o complemento na junção neuromuscular, mas não atua sobre a produção de acetilcolina pelo neurônio motor", "Aumenta o número de receptores nicotínicos nas fibras musculares, mas não altera a presença de anticorpos"], "gabarito": "C", "justificativa": "Piridostigmina é anticolinesterásico: aumenta a acetilcolina na fenda. Não elimina autoanticorpos; o tratamento modificador é corticoide, imunossupressor ou timectomia (resumo: Farmacologia, miastenia; Imunologia, tipo II).", "tecnica": "Miastenia e tratamento", "slide": null}, {"id": 5, "nivel": "muito_dificil", "enunciado": "Na febre reumática, a proteína M do Streptococcus pyogenes é semelhante à miosina cardíaca. Qual é o nome desse fenômeno e qual é sua consequência clínica?", "alternativas": ["Imunodeficiência secundária, com queda de linfócitos T CD4+ e infecção de repetição após a faringite", "Mimetismo molecular, com miocardite e artrite após faringoamigdalite mal tratada", "Doença do soro, com complexos de penicilina e albumina depositados nos glomérulos renais", "Tolerância periférica, com perda de linfócitos T autorreativos no linfonodo regional da faringe", "Reação de hipersensibilidade tipo I, com IgE contra a miosina e degranulação de mastócitos cardíacos"], "gabarito": "B", "justificativa": "Mimetismo molecular: anticorpo contra a proteína M reage com a miosina cardíaca, causando miocardite e artrite entre 5 e 15 anos, após faringoamigdalite mal tratada (resumo: Hipersensibilidade II, febre reumática).", "tecnica": "Mimetismo molecular", "slide": null}, {"id": 6, "nivel": "muito_dificil", "enunciado": "Um paciente com lúpus tem nefrite por depósito de imunocomplexos na membrana basal glomerular. Qual é a sequência correta que leva à lesão renal?", "alternativas": ["Ativação do complemento pela via alternativa antes do depósito, seguida de apoptose direta do podócito pela IgE", "Degranulação de mastócitos renais por IgE, seguida de formação de imunocomplexos no interstício tubular", "Reconhecimento de células tubulares pelo linfócito CD8+, seguido de destruição direta por perforina e granzima", "Depósito, via clássica, C3a e C5a recrutam neutrófilos, que degranulam", "Ativação de linfócitos Th2 com produção de IL-4, seguida de troca de classe e deposição de IgA mesangial"], "gabarito": "D", "justificativa": "Depósito → via clássica → C3a/C5a recrutam neutrófilos → neutrófilo degranula sobre o complexo grande demais para fagocitose → lesão tecidual (resumo: Hipersensibilidade III, sequência).", "tecnica": "Tipo III: sequência de lesão", "slide": null}, {"id": 7, "nivel": "muito_dificil", "enunciado": "Na curva experimental da doença por imunocomplexos, por que o complemento é ativado pela via alternativa logo após a injeção do antígeno?", "alternativas": ["Ainda não há anticorpos; a via clássica só entra quando os complexos se formam", "Porque a via alternativa depende de IgE, que é produzida em grande quantidade logo após a injeção", "Porque a via clássica está inibida pelo antígeno solúvel, que bloqueia o sítio C1 nas primeiras horas", "Porque a via alternativa só se ativa em presença de linfócitos Th1, que surgem antes dos anticorpos", "Porque a via clássica depende de células NK, que chegam ao tecido apenas após a fase de equilíbrio"], "gabarito": "A", "justificativa": "No início não há anticorpos; o complemento é ativado pela via alternativa. A via clássica entra depois, quando os anticorpos aparecem e os complexos se formam (resumo: Hipersensibilidade III, pegadinha da curva).", "tecnica": "Tipo III: curva e via", "slide": null}, {"id": 8, "nivel": "muito_dificil", "enunciado": "A doença do soro por penicilina é transitória, enquanto o lúpus é crônico. Qual é a diferença mecanística que explica essa diferença de curso?", "alternativas": ["Na penicilina há ativação de IgE e no lúpus há ativação de IgG, que é sempre de curso longo", "Na penicilina o complemento não é ativado, e no lúpus o complemento é ativado somente pela via lectina", "Na penicilina o linfócito T é o efetor principal, e no lúpus o efetor principal é o mastócito tecidual", "Na penicilina o imunocomplexo é insolúvel, e no lúpus o imunocomplexo é sempre solúvel e circulante", "Na penicilina o antígeno é retirado e a doença cessa; no lúpus o autoantígeno não pode ser removido"], "gabarito": "E", "justificativa": "Doença do soro por penicilina é transitória porque o antígeno é retirado. A autoimunidade é crônica porque o autoantígeno não pode ser eliminado, apenas a produção de anticorpos é reduzida (resumo: Hipersensibilidade III).", "tecnica": "Transitória × crônica", "slide": null}, {"id": 9, "nivel": "muito_dificil", "enunciado": "Um paciente com Th1 hiperativa tem granuloma e destruição de tecido. Qual é o mecanismo efetor principal da hipersensibilidade tipo IV descrita em aula?", "alternativas": ["Th1 secreta IFN-γ, que ativa macrófagos, com lesão causada pela própria resposta inata", "Th2 secreta IL-4, que troca a classe para IgE e ativa mastócitos no tecido inflamado", "Linfócito B produz IgG que se deposita no endotélio e ativa o complemento pela via clássica", "Mastócito libera histamina pré-formada, que causa vasodilatação e edema no granuloma", "Neutrófilo libera triptase, que destrói a matriz extracelular e ativa diretamente a apoptose"], "gabarito": "A", "justificativa": "Tipo IV: Th1 secreta IFN-γ, que ativa o macrófago. Quem causa a lesão é, em grande parte, a resposta inata estimulada pela adaptativa. O gatilho definidor é o linfócito T (resumo: Hipersensibilidade IV).", "tecnica": "Tipo IV: Th1", "slide": null}, {"id": 10, "nivel": "muito_dificil", "enunciado": "Em aula foi afirmado que 'Th17 produz interferon-gama'. Qual correção está correta e qual é a função da Th17?", "alternativas": ["Th17 produz IFN-γ, que recruta neutrófilos; a Th1 produz IL-17, que ativa macrófagos", "Th17 produz IgE, que recruta mastócitos; a Th2 produz IFN-γ, que ativa neutrófilos", "Th17 produz IL-4, que troca a classe para IgG; a Th1 produz IL-5, que ativa eosinófilos", "Th17 produz IL-17, que recruta neutrófilos; quem produz IFN-γ é a Th1, que ativa macrófagos", "Th17 produz perforina, que destrói células-alvo; a Th1 produz granzima, que ativa o complemento"], "gabarito": "D", "justificativa": "Th17 secreta IL-17 (e IL-22), que recruta neutrófilos. Th1 secreta IFN-γ, que ativa macrófagos. O slide traz a versão correta (resumo: Hipersensibilidade IV, correção científica).", "tecnica": "Th1 × Th17", "slide": null}, {"id": 11, "nivel": "muito_dificil", "enunciado": "Por que o tipo II pode ser causado por três mecanismos distintos, e um deles não envolve inflamação?", "alternativas": ["Opsonização, inflamação e apoptose por perforina; a apoptose sempre ocorre sem envolvimento de anticorpos", "Degranulação, histamina e triptase; todos ocorrem com IgE e nenhum deles envolve o complemento em nenhuma forma", "Imunocomplexo, depósito e fagocitose; todos ocorrem com IgM e nenhum deles altera a função de receptores", "Citotoxicidade CD8+, ADCC e secreção de IL-17; todos envolvem apenas linfócitos T e nenhum anticorpo", "Opsonização, inflamação e alteração funcional, que não envolve inflamação"], "gabarito": "E", "justificativa": "Tipo II: (1) opsonização e fagocitose; (2) inflamação via complemento; (3) alteração funcional, sem inflamação, como no Graves e na miastenia (resumo: Hipersensibilidade II, três mecanismos).", "tecnica": "Tipo II: três mecanismos", "slide": null}, {"id": 12, "nivel": "muito_dificil", "enunciado": "No tipo II por alteração funcional, o autoanticorpo pode estimular ou bloquear um receptor. Qual par de doenças ilustra corretamente os dois efeitos opostos?", "alternativas": ["Miastenia gravis (estimula o receptor de TSH) e Graves (bloqueia o receptor nicotínico)", "Graves (estimula o receptor de TSH) e miastenia gravis (bloqueia o receptor nicotínico)", "Anemia hemolítica (estimula a hemácia) e febre reumática (bloqueia a miosina cardíaca)", "Lúpus (estimula o DNA) e artrite reumatoide (bloqueia a citrulina nas articulações)", "Esclerose múltipla (estimula a mielina) e diabetes tipo 1 (bloqueia a célula β pancreática)"], "gabarito": "B", "justificativa": "No Graves, o autoanticorpo é agonista do receptor de TSH. Na miastenia, é antagonista do receptor nicotínico da placa motora (resumo: Hipersensibilidade II, par de doenças).", "tecnica": "Tipo II: agonista × antagonista", "slide": null}, {"id": 13, "nivel": "muito_dificil", "enunciado": "Um paciente com febre reumática tem miocardite, mas o cultivo do miocárdio é negativo para o estreptococo. Qual é a explicação mais coerente?", "alternativas": ["A bactéria permanece viva no miocárdio, mas em forma L, que não cresce em meio de cultura comum", "O miocárdio é infectado por vírus, e a bactéria apenas desencadeia a infecção secundária no endotélio", "O dano é mediado por anticorpo reativo com a miosina, em reação cruzada, após a bactéria ser eliminada", "O cultivo é negativo porque o antibiótico aumentou a expressão de MHC de classe I, o que destrói a bactéria", "A febre reumática é imunodeficiência secundária, e o cultivo negativo indica queda de linfócitos T CD4+"], "gabarito": "C", "justificativa": "No mimetismo molecular o dano é causado por anticorpo contra a proteína M com reação cruzada à miosina. A bactéria não precisa estar presente no coração (resumo: Hipersensibilidade II, mimetismo).", "tecnica": "Febre reumática e cultura", "slide": null}, {"id": 14, "nivel": "muito_dificil", "enunciado": "Por que o tipo III é sistêmico, enquanto o tipo II costuma ser tecido-específico?", "alternativas": ["Porque o antígeno é fixo à membrana, o que confina o dano à célula que expressa o antígeno", "Porque o tipo III é mediado por IgE, que circula por todo o organismo e ativa mastócitos sistemicamente", "Porque o tipo II envolve apenas linfócitos T, que se restringem ao tecido linfoide secundário", "Porque o tipo III depende de células NK, que circulam em todos os tecidos com antígeno fixo na superfície", "Porque o antígeno é solúvel e circulante, e os imunocomplexos podem se depositar em qualquer tecido"], "gabarito": "E", "justificativa": "Regra da prova: antígeno fixo produz lesão localizada, tecido-específica; antígeno solúvel produz doença sistêmica, porque os imunocomplexos podem se depositar em qualquer lugar (resumo: Quadro das hipersensibilidades).", "tecnica": "Antígeno fixo × solúvel", "slide": null}, {"id": 15, "nivel": "muito_dificil", "enunciado": "Um paciente tem doença autoimune e marcadores de tipo II e tipo III simultaneamente. Qual é o exemplo clássico desse quadro misto em aula?", "alternativas": ["Lúpus, com anemia hemolítica e plaquetopenia de tipo II, e nefrite e vasculite de tipo III", "Miastenia gravis, com fraqueza de tipo III, e ptose e diplopia de tipo I por degranulação de mastócitos", "Doença do soro por penicilina, com urticária de tipo I, e anemia hemolítica de tipo IV por linfócitos T", "Febre reumática, com miocardite de tipo IV, e artrite de tipo I causada pela IgE contra a proteína M", "Diabetes tipo 1, com destruição de célula β de tipo II, e glomerulonefrite de tipo III por IgG"], "gabarito": "A", "justificativa": "O lúpus é modelo clássico de tipo III, mas sua anemia hemolítica e plaquetopenia são de tipo II. Um mesmo paciente pode ter dois tipos ao mesmo tempo (resumo: Quadro das hipersensibilidades).", "tecnica": "Hipersensibilidade mista", "slide": null}], "id": "imuno-thiago-08", "titulo": "Aula 8", "voltar": {"href": "#/agressao/thiago", "texto": "Professor Thiago"}, "manobras": [], "imagens": [], "casos_extremos": []};
window.AULAS["imuno-thiago-09"] = {"subtitulo": "Transplante e mecanismos de rejeição", "pdf": "pdf/thiago/aula-09.pdf", "abas": ["resumo", "glossario", "quiz", "tabela", "pdf"], "fontes": ["Aula 9 · Transplante e Mecanismos de Rejeição (Prof. Dr. Thiago Corrêa)", "Abbas, Lichtman e Pillai (2023); Relatório de Transplantes Realizados (Brasil, 2001–2023), citado nos slides", "Resumo integrado da Prova 2 (Agressão e Defesa II): conteúdo das aulas de Imunologia, Microbiologia e Farmacologia, lido página por página."], "tabela": {"titulo": "Sistema ABO (slide 18)", "colunas": ["", "A", "B", "AB", "O"], "linhas": [["Antígenos nos eritrócitos", "Antígeno A", "Antígeno B", "Antígenos A e B", "Sem antígenos A nem B"], ["Anticorpos no plasma", "Anti-B", "Anti-A", "Nenhum", "Anti-A e anti-B"], ["Pode doar para", "A e AB", "B e AB", "AB", "Todos"], ["Pode receber de", "A e O", "B e O", "Todos", "O"]]}, "resumo": [{"titulo": "1. O que é transplante e quais os tipos", "pontos": [{"t": "Definição", "sub": ["Transplante substitui órgão ou tecido não funcional por outro saudável. O doador fornece o enxerto; o receptor (hospedeiro) o recebe (slide 2).", "Tipos pelo grau de parentesco genético: autólogo (mesmo indivíduo), singênico (gêmeo idêntico), alogênico (mesma espécie, geneticamente diferente) e xenogênico (espécies diferentes) (slide 3)."]}, {"t": "Dado nacional", "sub": ["O Relatório de Transplantes Realizados (Ministério da Saúde, 2001 a 2023) mostra a evolução dos transplantes no Brasil (slide 2)."]}]}, {"titulo": "2. A base imunológica da rejeição", "pontos": [{"t": "MHC como antígeno principal", "sub": ["As moléculas de MHC são os principais antígenos de rejeição, por serem muito polimórficas. Humanos não consanguíneos diferem nos alelos herdados (slide 4).", "Quanto mais alelos de MHC compatíveis, maior a sobrevida do enxerto (slide 12)."]}, {"t": "Reconhecimento de aloantígenos", "sub": ["Direto: linfócitos T do receptor reconhecem o MHC intacto do doador, nas células do enxerto (slide 5). É a via mais forte na rejeição aguda.", "Indireto: peptídeos do MHC do doador são apresentados pelo MHC do receptor, em APCs do receptor (slide 6). É a via que predomina na rejeição crônica (Abbas)."]}]}, {"titulo": "3. Os tipos de rejeição", "pontos": [{"t": "Hiperaguda", "sub": ["Minutos a horas. Anticorpos pré-formados no receptor contra antígenos endoteliais do doador causam trombose e oclusão do enxerto (slide 8)."]}, {"t": "Celular aguda", "sub": ["Linfócitos T CD8+ (CTLs) eliminam células do parênquima e do endotélio; citocinas de T auxiliares causam inflamação (slide 9)."]}, {"t": "Aguda mediada por anticorpos", "sub": ["Aloanticorpos contra HLA nas células endoteliais causam lesão e trombose intravascular (slide 10)."]}, {"t": "Crônica", "sub": ["Oclusão arterial por proliferação de células musculares lisas da íntima. É a lesão dominante em enxertos vascularizados (slide 11)."]}]}, {"titulo": "4. Testes antes do transplante e imunossupressão", "pontos": [{"t": "Pré-transplante", "sub": ["Tipagem ABO, alelos de HLA e pesquisa de anticorpos pré-formados contra HLA (slide 12). Uma prova cruzada positiva contraindica o enxerto.", "Genotipagem por sequenciamento de nova geração compara os alelos (slide 13)."]}, {"t": "Fármacos", "sub": ["Ciclosporina e tacrolimo inibem a transcrição da IL-2 em células T (slide 14).", "Rapamicina inibe a proliferação de T mediada por fatores de crescimento (slide 14).", "Glicocorticoides agem na transcrição de genes inflamatórios (slide 15).", "A ciclosporina inaugurou a era moderna dos transplantes; antes dela, a maioria dos corações e fígados era rejeitada (slide 16)."]}]}, {"titulo": "5. Sistema ABO e transplante de células-tronco", "pontos": [{"t": "Sistema ABO", "sub": ["Antígenos ABO são carboidratos da superfície celular, sintetizados por glicosiltransferases polimórficas (slide 17).", "Tabela da aula: grupo O não tem antígenos A nem B e tem anticorpos anti-A e anti-B; por isso é doador universal de hemácias e receptor restrito (slide 18)."]}, {"t": "Transplante de CTH", "sub": ["Células T maduras do doador podem reconhecer e destruir células tumorais do receptor: efeito enxerto contra tumor (slide 19).", "Doença do enxerto contra o hospedeiro (GVHD): células T do enxerto reagem contra aloantígenos do receptor (slide 20)."]}, {"t": "GVHD crônica", "sub": ["Rash cutâneo, disfunção hepática, diarreia, vômito, trombocitopenia e trombose (slide 21)."]}]}, {"titulo": "6. Tipos de enxerto e o polimorfismo do MHC", "pontos": [{"t": "Tipos de enxerto", "sub": ["Autólogo: do próprio indivíduo para ele mesmo (ex.: pele da perna para o braço). Não há rejeição.", "Singênico: entre geneticamente idênticos (gêmeos monozigóticos). Não há relevância clínica; imunossupressão desnecessária.", "Alogênico: entre indivíduos da mesma espécie, não aparentados; é o mais comum. A rejeição sempre existe; a questão é a intensidade.", "Xenogênico: entre espécies diferentes; rejeição intensíssima. A edição gênica (CRISPR-Cas9) vem reduzindo a barreira."]}, {"t": "Moléculas que causam rejeição", "sub": ["As moléculas do MHC (HLA) são as que causam rejeição rápida e intensa, por serem extremamente polimórficas: diferem entre indivíduos em muitos nucleotídeos.", "O polimorfismo é vantajoso para a espécie (repertório amplo de apresentação), mas inviabiliza a compatibilidade perfeita. Contribuem também o sistema ABO e antígenos menores."]}, {"t": "Reconhecimento direto × indireto", "sub": ["Direto: a APC do doador, que veio com o órgão, apresenta a molécula de MHC alheia intacta, sem processamento.", "Indireto: a APC do receptor endocita, degrada e apresenta peptídeos derivados do MHC alheio no MHC próprio.", "Nos dois casos, linfócitos T ativados migram pelo sistema linfático até o enxerto e eliminam as células que exibem o MHC estranho."]}]}, {"titulo": "7. Os quatro tipos de rejeição", "pontos": [{"t": "Tabela-resumo", "sub": ["Hiperaguda (minutos a horas): anticorpos preexistentes se ligam ao endotélio do doador → complemento → inflamação; lesão endotelial, pró-coagulantes, oclusão trombótica.", "Aguda celular (dias a semanas): CTL CD8+ destroem parênquima e endotélio; citocinas de T auxiliares amplificam; endotelite, trombose, isquemia.", "Aguda humoral (dias a semanas): aloanticorpos novos, produzidos após o transplante, contra HLA endotelial; lesão endotelial e trombose intravascular.", "Crônica (meses a anos): inflamação arraigada; IL-1, IL-6 e TNF agem como fatores de crescimento sobre o músculo liso; proliferação da íntima → oclusão arterial progressiva → isquemia difusa."]}, {"t": "Pegadinha", "sub": ["Hiperaguda e aguda humoral têm o mesmo efetor (anticorpo contra endotélio). O que as separa é o momento: na hiperaguda o anticorpo já existia antes do transplante; na aguda humoral foi produzido depois, exigindo ativação de linfócitos B.", "A lesão crônica é oclusão por proliferação de músculo liso, não por trombo."]}]}, {"titulo": "8. Imunossupressão: fármacos e mecanismos", "pontos": [{"t": "Tabela", "sub": ["Ciclosporina e tacrolimo: inibem a calcineurina → bloqueiam a transcrição de IL-2 → sem IL-2 não há expansão clonal de linfócitos T. A ciclosporina inaugurou a era moderna dos transplantes.", "Rapamicina (sirolimo): inibe a via mTOR e bloqueia a proliferação de linfócitos T mediada por fatores de crescimento.", "Anti-receptor de IL-2: impede a ação biológica da IL-2, que continua sendo produzida.", "CTLA-4-Ig: liga-se ao B7 da APC e impede a coestimulação via CD28. É o inverso exato da imunoterapia antitumoral (ver aula 10).", "Glicocorticoides: ação ampla; inibem a produção de citocinas em várias células e induzem apoptose linfocitária; o efeito depende de dose e tempo de uso."]}, {"t": "Ênfase", "sub": ["A ciclosporina seletiva sobre linfócito T caiu na questão 2 do 1.º bimestre."]}]}, {"titulo": "9. ABO, anticorpos naturais e células-tronco", "pontos": [{"t": "Anticorpos naturais do sistema ABO", "sub": ["Por que quem é do tipo A tem anti-B sem nunca ter recebido sangue? Bactérias da microbiota intestinal expressam carboidratos semelhantes aos antígenos A e B e estimulam esses anticorpos (reação cruzada, o mesmo princípio da febre reumática).", "O indivíduo não produz anticorpo contra o próprio antígeno (tolerância). O tipo O não tem A nem B e produz ambos.", "Os carboidratos ABO também estão no endotélio, não só nas hemácias; por isso a incompatibilidade ABO causa rejeição hiperaguda de órgão sólido."]}, {"t": "Doença do enxerto contra o hospedeiro (DECH)", "sub": ["Na direção inversa: no transplante de células-tronco hematopoéticas, o linfócito T maduro do doador reconhece o receptor como estranho e o ataca.", "Manifestações: rash cutâneo, disfunção hepática, diarreia, vômitos e plaquetopenia.", "Prevenção: depletar ao máximo os linfócitos T maduros, isolando apenas as células-tronco. O professor sinalizou isso como possível questão aberta."]}, {"t": "Correlação clínica", "sub": ["Quimio ou radioterapia prévia abre espaço nos nichos medulares para as células infundidas e, quando a indicação é neoplásica, elimina as células tumorais.", "Quanto menos alelos HLA incompatíveis, maior a sobrevida do enxerto; mas em coração e fígado o tempo de isquemia e o risco de óbito em fila pesam mais.", "Genotipagem HLA: PCR seguido de sequenciamento (NGS), porque o PCR sozinho amplifica a região mas não revela qual nucleotídeo está presente."]}]}, {"titulo": "10. Para prova", "pontos": [{"t": "Pontos de cobrança", "sub": ["Tempo e mecanismo de cada rejeição: hiperaguda, aguda celular, aguda por anticorpo e crônica.", "Reconhecimento direto × indireto.", "GVHD × efeito enxerto contra tumor."]}]}], "glossario": [{"termo": "Aloantígeno", "tecnica": "Base da rejeição", "definicao": "Antígeno que difere entre indivíduos da mesma espécie, sobretudo moléculas de MHC.", "slide": 4}, {"termo": "Singênico", "tecnica": "Tipos de transplante", "definicao": "Transplante entre indivíduos geneticamente idênticos, como gêmeos idênticos.", "slide": 3}, {"termo": "Reconhecimento direto", "tecnica": "Apresentação de aloantígenos", "definicao": "Células T do receptor reconhecem moléculas de MHC intactas do enxerto.", "slide": 5}, {"termo": "Reconhecimento indireto", "tecnica": "Apresentação de aloantígenos", "definicao": "Fragmentos do MHC do doador são apresentados pelo MHC do receptor.", "slide": 6}, {"termo": "Rejeição hiperaguda", "tecnica": "Tipos de rejeição", "definicao": "Oclusão trombótica do enxerto por anticorpos pré-formados, em minutos a horas.", "slide": 8}, {"termo": "GVHD", "tecnica": "Transplante de CTH", "definicao": "Doença do enxerto contra o hospedeiro, em que linfócitos T do doador atacam tecidos do receptor.", "slide": 20}, {"termo": "Antígenos ABO", "tecnica": "Sistema ABO", "definicao": "Carboidratos da superfície dos eritrócitos, base da compatibilidade transfusional.", "slide": 17}, {"termo": "Reconhecimento direto e indireto", "tecnica": "Transplante", "definicao": "Direto: célula do doador apresenta MHC próprio ao receptor. Indireto: célula do receptor apresenta peptídeos do doador.", "slide": 1}, {"termo": "Ciclosporina e tacrolimo", "tecnica": "Imunossupressor", "definicao": "Inibem a calcineurina e a produção de IL-2, reduzindo a ativação de linfócitos T.", "slide": 1}], "caso": {"titulo": "Caso: transplante renal e compatibilidade", "perfil": "Pré-transplante, rejeição e imunossupressão.", "etapas": [{"titulo": "Etapa 1: prova cruzada positiva", "texto": "Mulher de 45 anos aguarda transplante renal. A prova cruzada com o doador é positiva, e há anticorpos pré-formados contra HLA do doador, com histórico de múltiplas gestações e transfusões.", "perguntas": [{"pergunta": "Qual tipo de rejeição esse achado pré-transplante sugere, segundo a aula?", "alts": ["Hiperaguda, mediada por anticorpos pré-formados contra o endotélio do doador", "Celular aguda, mediada por CTLs que eliminam células do parênquima", "Crônica, com proliferação das células musculares lisas da íntima", "Doença do enxerto contra o hospedeiro, mediada por T do doador", "Rejeição por reconhecimento indireto de aloantígenos sem anticorpos"], "erradas": ["Celular aguda é mediada por CTLs, não por anticorpos pré-formados.", "A crônica se caracteriza por oclusão arterial lenta, não por anticorpos pré-formados.", "GVHD ocorre no transplante de CTH, com células T do enxerto, não aqui.", "O reconhecimento indireto não é o mecanismo dos anticorpos pré-formados."], "justificativa": "Anticorpos pré-formados no receptor causam rejeição hiperaguda, com oclusão trombótica em minutos a horas (slide 8)."}]}, {"titulo": "Etapa 2: transplante de CTH", "texto": "Homem de 30 anos recebe transplante alogênico de células-tronco hematopoéticas. Após três semanas, apresenta rash cutâneo, diarreia e aumento de bilirrubina.", "perguntas": [{"pergunta": "Qual complicação é mais provável, segundo a aula?", "alts": ["Doença do enxerto contra o hospedeiro, pela reação de T maduros do doador", "Rejeição hiperaguda do enxerto, pela ativação de anticorpos pré-formados", "Efeito enxerto contra tumor, sem efeito sobre tecidos do receptor", "Rejeição crônica, por oclusão arterial da íntima do enxerto", "Hipersensibilidade tipo I, com degranulação de mastócitos cutâneos"], "erradas": ["Rejeição hiperaguda ocorre em minutos a horas, e não nessa evolução.", "Efeito enxerto contra tumor é benéfico e não causa esses sintomas.", "A rejeição crônica se caracteriza por oclusão arterial de enxertos vascularizados.", "Hipersensibilidade tipo I não explica o quadro hepático e digestivo."], "justificativa": "A GVHD crônica caracteriza-se por rash cutâneo, disfunção hepática e diarreia, com origem em T maduros do enxerto (slides 20 e 21)."}]}]}, "questoes": [{"id": 1, "nivel": "muito_dificil", "enunciado": "Um paciente recebe rim de doador com tipo sanguíneo incompatível e perde o enxerto em minutos. Qual é o tipo de rejeição mais compatível com esse quadro?", "alternativas": ["Aguda celular, por CTL CD8+ que destroem o parênquima após o sétimo dia de transplante", "Crônica, por proliferação da íntima e oclusão arterial progressiva ao longo de meses", "Aguda humoral, por aloanticorpos novos produzidos após o transplante, contra HLA endotelial", "Doença do enxerto contra o hospedeiro, por linfócitos T maduros do doador que atacam o receptor", "Hiperaguda, por anticorpos préformados contra o endotélio do doador"], "gabarito": "E", "justificativa": "Na hiperaguda, o anticorpo já existia antes do transplante e atinge o endotélio do doador em minutos a horas. A aguda humoral depende de anticorpo produzido depois (resumo: Transplante, tipos de rejeição).", "tecnica": "Hiperaguda", "slide": null}, {"id": 2, "nivel": "muito_dificil", "enunciado": "Por que a rejeição hiperaguda e a aguda humoral têm o mesmo efetor, mas se distinguem pelo momento?", "alternativas": ["Na hiperaguda o efetor é o linfócito T CD8+; na aguda humoral o efetor é o neutrófilo ativado pela IgE", "Na hiperaguda o anticorpo já existia; na aguda humoral foi produzido depois", "Na hiperaguda não há complemento; na aguda humoral o complemento é ativado somente pela via lectina", "Na hiperaguda a lesão é crônica e fibrótica; na aguda humoral a lesão é reversível em poucas horas", "Na hiperaguda o alvo é a íntima arterial; na aguda humoral o alvo é o parênquima renal e hepático"], "gabarito": "B", "justificativa": "Ambas têm anticorpo contra endotélio. A diferença é que na hiperaguda o anticorpo preexiste, e na aguda humoral é produzido depois, o que exige ativação de linfócitos B (resumo: Transplante, pegadinha).", "tecnica": "Hiperaguda × aguda humoral", "slide": null}, {"id": 3, "nivel": "muito_dificil", "enunciado": "Em uma biópsia de rim transplantado, há proliferação da íntima arterial e oclusão progressiva, após anos do transplante. Qual é a explicação mais coerente?", "alternativas": ["Rejeição hiperaguda: anticorpo préformado causa trombose maciça que obstrui a artéria renal", "Rejeição aguda celular: CTL CD8+ destroem a íntima e causam necrose tubular aguda reversível", "Rejeição crônica: citocinas como IL-1, IL-6 e TNF agem como fatores de crescimento sobre o músculo liso", "Doença do enxerto contra o hospedeiro: linfócitos T maduros do doador atacam a íntima arterial", "Infecção por citomegalovírus: vírus replica no endotélio e causa trombose sem qualquer participação imune"], "gabarito": "C", "justificativa": "Na rejeição crônica, a inflamação arraigada e citocinas como IL-1, IL-6 e TNF atuam como fatores de crescimento sobre o músculo liso, levando à oclusão arterial (resumo: Transplante, rejeição crônica).", "tecnica": "Rejeição crônica", "slide": null}, {"id": 4, "nivel": "muito_dificil", "enunciado": "Por que o polimorfismo do MHC é vantajoso para a espécie, mas dificulta a compatibilidade no transplante?", "alternativas": ["Permite apresentar um repertório amplo de antígenos, mas faz moléculas diferirem muito entre indivíduos", "Permite que todos os indivíduos tenham HLA idêntico, o que facilita o transplante entre quaisquer pessoas", "Impede a apresentação de peptídeos próprios, o que elimina a rejeição e a necessidade de imunossupressão", "Faz o MHC ser expresso apenas em hemácias, de modo que o endotélio não é alvo de linfócitos T", "Impede que o MHC seja reconhecido por linfócitos T, o que protege o enxerto contra qualquer rejeição"], "gabarito": "A", "justificativa": "As moléculas do MHC (HLA) são extremamente polimórficas. Esse polimorfismo amplia o repertório de apresentação da espécie, mas torna a compatibilidade perfeita inviável (resumo: Transplante, base imunológica).", "tecnica": "Polimorfismo do MHC", "slide": null}, {"id": 5, "nivel": "muito_dificil", "enunciado": "No reconhecimento direto de aloantígeno, quem apresenta o antígeno ao linfócito T e qual é a sua origem?", "alternativas": ["A APC do receptor, que endocita o órgão, degrada o MHC alheio e apresenta peptídeos próprios", "A APC do doador, que veio junto com o órgão, apresentando o MHC alheio intacto", "O linfócito B do receptor, que produz IgE contra o MHC alheio e o apresenta ao linfócito T", "O mastócito do enxerto, que libera histamina e apresenta o MHC alheio ao linfócito T CD8+", "A célula NK do receptor, que destrói o enxerto e apresenta o MHC alheio ao linfócito B"], "gabarito": "B", "justificativa": "No reconhecimento direto, a APC do doador, que vem com o órgão, apresenta o MHC alheio intacto, sem processamento. No indireto, a APC do receptor processa e apresenta peptídeos (resumo: Transplante, reconhecimento direto × indireto).", "tecnica": "Direto × indireto", "slide": null}, {"id": 6, "nivel": "muito_dificil", "enunciado": "A ciclosporina foi o marco da era moderna dos transplantes. Qual é o seu mecanismo molecular e por que ele é relativamente seletivo?", "alternativas": ["Inibe a via mTOR nos linfócitos B, bloqueando a produção de anticorpos contra o HLA do doador", "Liga-se ao B7 da APC e impede a coestimulação de linfócitos T por CD28 em qualquer célula", "Inibe a calcineurina e bloqueia a transcrição de IL-2, sem expansão de T", "Bloqueia o receptor de histamina H1 nos mastócitos, o que impede a degranulação no enxerto", "Inibe a fosfolipase A2 em todas as células do organismo, bloqueando a produção de leucotrienos"], "gabarito": "C", "justificativa": "Ciclosporina e tacrolimo inibem a calcineurina e bloqueiam a transcrição de IL-2, sem expansão clonal de T. Esse efeito é preferencialmente sobre linfócitos T (resumo: Transplante, imunossupressão).", "tecnica": "Ciclosporina", "slide": null}, {"id": 7, "nivel": "muito_dificil", "enunciado": "A rapamicina é usada em transplante por inibir a via mTOR. Qual é a diferença entre rapamicina e anti-receptor de IL-2 no efeito sobre os linfócitos T?", "alternativas": ["A rapamicina impede a produção de IL-2; o anti-receptor bloqueia a proliferação de linfócitos B de memória", "A rapamicina bloqueia o CD28; o anti-receptor inibe a calcineurina, que é necessária para a produção de IgE", "A rapamicina e o anti-receptor têm efeito idêntico, por ambos bloquearem a calcineurina de forma irreversível", "A rapamicina impede a migração do linfócito; o anti-receptor impede a degranulação do mastócito no enxerto", "Rapamicina bloqueia a proliferação via mTOR; anti-IL-2R bloqueia a ação da IL-2"], "gabarito": "E", "justificativa": "Rapamicina inibe mTOR e a proliferação de T mediada por fatores de crescimento. Anti-receptor de IL-2 impede a ação da IL-2, que continua sendo produzida (resumo: Transplante, imunossupressão).", "tecnica": "Rapamicina e anti-IL-2R", "slide": null}, {"id": 8, "nivel": "muito_dificil", "enunciado": "Um transplantado recebe CTLA-4-Ig para evitar rejeição. Por que esse fármaco é o oposto exato da imunoterapia antitumoral com bloqueio de CTLA-4?", "alternativas": ["CTLA-4-Ig estimula a coestimulação via CD28, enquanto o anti-CTLA-4 bloqueia o linfócito T de forma definitiva", "CTLA-4-Ig e anti-CTLA-4 atuam sobre o mastócito, sendo o primeiro estimulador e o segundo inibidor da degranulação", "CTLA-4-Ig impede a coestimulação via CD28, enquanto o anti-CTLA-4 libera o B7 para ativar o linfócito T", "CTLA-4-Ig bloqueia o TNF no endotélio, enquanto o anti-CTLA-4 libera IL-2 para as células NK do tumor", "CTLA-4-Ig atua apenas no fígado, e o anti-CTLA-4 atua somente no sistema linfático periférico do paciente"], "gabarito": "C", "justificativa": "CTLA-4-Ig liga-se ao B7 e impede a coestimulação via CD28, reduzindo a ativação de T. O anti-CTLA-4 faz o oposto: libera o B7 para o CD28 e ativa o linfócito T (resumo: Transplante e Imunologia dos tumores).", "tecnica": "CTLA-4-Ig × anti-CTLA-4", "slide": null}, {"id": 9, "nivel": "muito_dificil", "enunciado": "Um paciente recebe transplante de células-tronco e desenvolve rash cutâneo, diarreia e plaquetopenia. Qual é o diagnóstico e a principal medida preventiva?", "alternativas": ["Rejeição hiperaguda; administrar anticorpos antiendotélio do doador antes do transplante", "Imunodeficiência congênita; administrar imunoglobulina endovenosa mensal de longa duração", "Hipersensibilidade tipo I; administrar adrenalina e anti-H1 antes da infusão das células", "DECH; depletar ao máximo os linfócitos T maduros do inóculo, isolando as células-tronco", "Infecção por CMV; administrar antiviral profilático, sem qualquer medida de depleção celular"], "gabarito": "D", "justificativa": "Na DECH, linfócitos T maduros do doador atacam o receptor. Manifesta-se com rash, disfunção hepática, diarreia, vômitos e plaquetopenia. A prevenção é depletar os linfócitos T maduros (resumo: Transplante, DECH).", "tecnica": "DECH", "slide": null}, {"id": 10, "nivel": "muito_dificil", "enunciado": "Por que a incompatibilidade ABO causa rejeição hiperaguda de órgão sólido, mesmo sem exposição prévia a sangue do doador?", "alternativas": ["Carboidratos ABO no endotélio são alvo de anticorpos naturais estimulados por bactérias", "Porque o sistema ABO só se expressa em hemácias, e o endotélio do órgão sólido não contém nenhum antígeno ABO", "Porque anticorpos anti-A são produzidos apenas após o transplante, por ativação de células NK no fígado do doador", "Porque o tipo O produz anticorpos contra HLA, e a compatibilidade ABO não tem nenhuma relação com o endotélio", "Porque o tipo sanguíneo ABO é determinado pela IgE, que ativa mastócitos no endotélio do órgão doado"], "gabarito": "A", "justificativa": "Bactérias da microbiota expressam carboidratos semelhantes aos antígenos A e B e estimulam anticorpos naturais. Como os carboidratos ABO estão também no endotélio, a incompatibilidade causa rejeição hiperaguda (resumo: Transplante, ABO).", "tecnica": "ABO e rejeição", "slide": null}, {"id": 11, "nivel": "muito_dificil", "enunciado": "Por que o tipo O, que não tem antígeno A nem B, produz anticorpos anti-A e anti-B?", "alternativas": ["Porque o tipo O tem excesso de HLA, que induz a produção de IgE contra todos os antígenos do sistema ABO", "Porque o tipo O não tem MHC de classe II, e por isso o linfócito B não reconhece nenhum antígeno próprio", "Porque o tipo O é imunodeficiente congênito, e a falta de tolerância leva à autoimunidade contra o sistema ABO", "Porque o tipo O recebeu transfusão em toda a infância, e os anticorpos são memória de transfusões antigas", "Porque bactérias da microbiota expressam carboidratos semelhantes e estimulam os anticorpos naturais"], "gabarito": "E", "justificativa": "Os anticorpos naturais do sistema ABO surgem por estímulo de bactérias da microbiota que expressam carboidratos semelhantes. O tipo O, sem A nem B, produz ambos (resumo: Transplante, ABO e mimetismo).", "tecnica": "Anticorpos naturais ABO", "slide": null}, {"id": 12, "nivel": "muito_dificil", "enunciado": "Um professor afirma que o transplante de coração e fígado deve sempre buscar compatibilidade HLA máxima. Qual é a crítica mais precisa?", "alternativas": ["A compatibilidade HLA é irrelevante em todos os transplantes, porque o sistema ABO basta para a sobrevida", "A compatibilidade HLA é obrigatória em todos os órgãos, e o tempo de isquemia não tem nenhum impacto", "O HLA só importa em transplante de rim, porque o coração e o fígado não expressam MHC na superfície", "Em coração e fígado, o tempo de isquemia e o risco de óbito em fila pesam mais que a compatibilidade", "O HLA só importa em transplante autólogo, em que não há incompatibilidade possível entre doador e receptor"], "gabarito": "D", "justificativa": "Quanto menos alelos incompatíveis, maior a sobrevida do enxerto; mas em coração e fígado, a isquemia e o risco de óbito em fila podem pesar mais (resumo: Transplante, correlação clínica).", "tecnica": "HLA e órgão", "slide": null}, {"id": 13, "nivel": "muito_dificil", "enunciado": "Por que o PCR sozinho não é suficiente para a genotipagem HLA, exigindo sequenciamento de nova geração?", "alternativas": ["O PCR destrói o DNA do HLA durante a amplificação, e o sequenciamento é necessário para recuperá-lo", "O PCR amplifica a região, mas não revela qual nucleotídeo está presente naquela posição", "O PCR só funciona em células do sangue periférico, e o HLA precisa ser extraído da medula óssea", "O PCR detecta apenas proteínas, e o sequenciamento é necessário para identificar o MHC de classe II", "O PCR não amplifica DNA humano, e o sequenciamento é o único método capaz de reconhecer o HLA"], "gabarito": "B", "justificativa": "O PCR amplifica a região de interesse, mas não revela qual nucleotídeo está em cada posição. Por isso a genotipagem exige sequenciamento de nova geração (NGS) (resumo: Transplante, testes antes do transplante).", "tecnica": "Genotipagem HLA", "slide": null}, {"id": 14, "nivel": "muito_dificil", "enunciado": "Por que quimioterapia ou radioterapia prévia são usadas no transplante de células-tronco com indicação neoplásica?", "alternativas": ["Abrem espaço nos nichos medulares para as células infundidas e eliminam as células tumorais", "Estimulam a produção de IgE pelo receptor, que aumenta a degranulação de mastócitos na medula óssea", "Inibem a calcineurina na medula, impedindo que as células-tronco do doador sejam atacadas pelo receptor", "Induzem a expressão de MHC de classe I nas células tumorais, tornando-as visíveis ao linfócito NK", "Aumentam a produção de IL-2 nas células-tronco, para que elas se expandam com mais rapidez na medula"], "gabarito": "A", "justificativa": "Quimio ou radioterapia prévia abre espaço nos nichos medulares e, na indicação neoplásica, elimina as células tumorais (resumo: Transplante, correlação clínica).", "tecnica": "Condicionamento", "slide": null}, {"id": 15, "nivel": "muito_dificil", "enunciado": "Um transplantado em uso de glicocorticoide tem risco aumentado de infecção. Qual é o principal mecanismo desse fármaco sobre a resposta imune?", "alternativas": ["Ativa a calcineurina e aumenta a produção de IL-2, o que esgota os linfócitos T auxiliares", "Bloqueia o CD28 e impede a coestimulação dos linfócitos B, reduzindo a produção de anticorpos", "Inibe a fosfolipase C dos neutrófilos, impedindo a fagocitose de bactérias encapsuladas no tecido", "Inibe a produção de citocinas e induz apoptose de linfócitos", "Estimula a produção de IgE e de triptase pelos mastócitos, o que causa lesão tecidual difusa"], "gabarito": "D", "justificativa": "Glicocorticoides têm ação ampla: inibem citocinas em várias células e induzem apoptose de linfócitos. O efeito depende da dose e do tempo de uso (resumo: Transplante, imunossupressão).", "tecnica": "Glicocorticoide", "slide": null}], "id": "imuno-thiago-09", "titulo": "Aula 9", "voltar": {"href": "#/agressao/thiago", "texto": "Professor Thiago"}, "manobras": [], "imagens": [], "casos_extremos": []};
window.AULAS["imuno-thiago-10"] = {"subtitulo": "Imunologia dos tumores e imunoterapia", "pdf": "pdf/thiago/aula-10.pdf", "abas": ["resumo", "glossario", "quiz", "pdf"], "fontes": ["Aula 10 · Imunologia dos Tumores (Prof. Dr. Thiago Corrêa)", "Abbas, Lichtman e Pillai (2019); Boon et al. (2006); Khalil et al. (2016); Jorge (2019) (citados nos slides)", "Resumo integrado da Prova 2 (Agressão e Defesa II): conteúdo das aulas de Imunologia, Microbiologia e Farmacologia, lido página por página."], "resumo": [{"titulo": "1. Origem dos antígenos tumorais", "pontos": [{"t": "Neoantígenos", "sub": ["A maioria dos antígenos tumorais é neoantígeno: peptídeo novo gerado por genes mutados no clone tumoral. Células normais não expressam esses peptídeos (slide 3)."]}, {"t": "Antígenos de vírus oncogênicos", "sub": ["Proteínas virais estranhas, como as de vírus de DNA associados a câncer. A resposta é essencialmente antiviral (slide 4)."]}, {"t": "Alteração epigenética", "sub": ["Metilação de CpG marca genes silenciados (slide 5).", "CEA (cólon, pâncreas, estômago, mama) e alfa-fetoproteína (fígado, células germinativas) são expressos em gametas e trofoblasto e reaparecem em alguns tumores (slide 6)."]}, {"t": "Expressão aberrante", "sub": ["Amplificação gênica leva à superexpressão de uma proteína, como HER2/neu (slide 7)."]}]}, {"titulo": "2. Defesa antitumoral", "pontos": [{"t": "Linfócitos T CD8+", "sub": ["Principal mecanismo: eliminação de células tumorais por CTLs CD8+ (slide 9).", "Th1 intensifica a resposta de CD8+ e ativa macrófagos (slide 9)."]}, {"t": "Células NK", "sub": ["NK destroem muitos tumores. Normalmente o MHC-I da célula saudável inibe a NK; quando o tumor perde MHC-I, a inibição some e a NK ataca (slide 11).", "ADCC: NK ativada destrói células cobertas por anticorpos antitumorais (slide 12)."]}, {"t": "Imunovigilância", "sub": ["Vigilância imune: o sistema reconhece e elimina células transformadas (estudo dirigido, slide 25).", "O modelo de imunoedição (eliminação, equilíbrio e escape) é de Dunn, Old e Schreiber (2002). A aula cita a vigilância; as três fases não estão detalhadas no PDF."]}]}, {"titulo": "3. Escape tumoral e papel dos macrófagos", "pontos": [{"t": "Imunoevasão", "sub": ["Células tumorais produzem ligantes, como PD-L1, que engajam receptores inibitórios das células T; produzem também citocinas imunossupressoras (slide 15).", "Perda de MHC-I impede que a célula T CD8+ reconheça o tumor (slide 16)."]}, {"t": "Macrófagos", "sub": ["Podem inibir ou promover o tumor. Os pró-inflamatórios (TNF, IL-1, IL-6) combatem; os anti-inflamatórios (IL-10, TGF-beta) favorecem crescimento, angiogênese e imunossupressão (slide 13)."]}]}, {"titulo": "4. Imunoterapia e checkpoints", "pontos": [{"t": "Receptores inibitórios", "sub": ["CTLA-4 liga-se a CD80 e CD86 e inibe a célula T. Seu bloqueio com anticorpo intensifica a resposta antitumoral (slide 18).", "PD-1, expresso em T, liga-se a PD-L1 em células tumorais. O bloqueio com anticorpos intensifica a eliminação e contém cânceres avançados (slide 19)."]}, {"t": "Terapia celular", "sub": ["CAR-T: células T com receptores quiméricos contra antígenos tumorais (slides 20 e 21).", "Caso de remissão após terapia celular em estudo, citado no slide 22."]}, {"t": "Anticorpos monoclonais", "sub": ["Intensificam mecanismos efetores, interferem na sinalização de crescimento ou levam quimioterápico ao tumor (slide 23)."]}]}, {"titulo": "5. Antígenos tumorais: mecanismos, marcadores e vacina do HPV", "pontos": [{"t": "Mecanismos", "sub": ["Mutação: gera neoantígeno apresentado no MHC I; é intrínseco a toda célula tumoral e o mais frequente.", "Vírus oncogênico: a célula infectada produz proteínas virais; para o CD8+ tanto faz se a célula é infectada ou transformada. Exemplos: HPV (colo, vagina, ânus, orofaringe), EBV (linfomas), HBV (hepatocarcinoma).", "Alteração epigenética: desmetilação de genes silenciados após o nascimento, com reexpressão de proteínas embrionárias. Exemplos e marcadores: CEA (cólon, pâncreas, estômago, mama) e alfa-fetoproteína (fígado, células germinativas).", "Expressão aberrante: a proteína é normal; o anômalo é a quantidade (amplificação gênica causa superexpressão). Exemplo: HER2/neu e receptor do fator de crescimento epidérmico."]}, {"t": "Correlação clínica", "sub": ["A vacina contra HPV é prevenção primária de câncer: evita a infecção e reduz a prevalência dos tumores associados. Como é infecção sexualmente transmissível, vacina-se antes do início da vida sexual (cerca de 9–10 anos) e em ambos os sexos."]}]}, {"titulo": "6. Imunovigilância, imunoedição e o papel do CD8+", "pontos": [{"t": "Mecanismo efetor preponderante", "sub": ["Imunovigilância (anos 1950): monitoramento contínuo em busca de células transformadas. O mecanismo efetor preponderante é o linfócito T citotóxico CD8+.", "Ênfase do professor: \"o mecanismo efetor imunológico preponderante é a ativação de CD8. Não esqueçam disso\".", "Corolário no HIV: o paciente perde CD4+, mas como o CD4+ auxilia a ativação do CD8+, perde-se indiretamente a defesa antitumoral."]}, {"t": "Complementos: Th1, NK e ADCC", "sub": ["Th1 produz IFN-γ e ativa macrófagos.", "Célula NK atua onde o CD8+ falha: o CD8+ é restrito ao MHC; o tumor que perde MHC I fica invisível ao CD8+, mas a ausência de MHC I ativa a NK. Na presença de MHC I, a NK é inibida e o CD8+ trabalha.", "ADCC: a NK reconhece a porção Fc de IgG ligada à célula tumoral pelo receptor FcγR e libera perforinas e granzimas."]}, {"t": "Imunoedição (complemento externo)", "sub": ["Refina a imunovigilância em três fases: eliminação (imunovigilância clássica); equilíbrio (clones residuais sobrevivem sob pressão e são selecionados os menos imunogênicos); escape (proliferam variantes com perda de antígeno, perda de MHC I e expressão de PD-L1).", "Os três mecanismos de evasão são o resultado da fase de escape. (Dunn, Old & Schreiber, Immunity, 2004; Abbas, 9.ª ed.)"]}]}, {"titulo": "7. Macrófago M1 × M2 e o tumor", "pontos": [{"t": "Dupla face do macrófago", "sub": ["M1 (clássica): pró-inflamatório (TNF, IL-1, IL-6); microbicida e antitumoral.", "M2 (alternativa): anti-inflamatório (IL-10, TGF-β); reparo tecidual, angiogênese (VEGF) e imunomodulação; favorece o tumor, porque VEGF nutre a massa e metaloproteases degradam a matriz e abrem caminho para metástase.", "O M2 tem razão fisiológica (limpar tecido morto e reconstruir a matriz). O problema é o contexto: ativado de forma aguda, repara; ativado cronicamente, favorece o tumor.", "O estado que mantém o M2 hiperativado é a inflamação crônica de baixo grau (obesidade, infecções persistentes). O tumor \"coopta\" o sistema imune, nas palavras do professor."]}, {"t": "Conecta com a prova passada", "sub": ["A questão 13 do 1.º bimestre descrevia paciente obesa com infecções de repetição e contagens linfocitárias normais; a resposta correta era inflamação metabólica crônica de baixo grau comprometendo a função imune. É o mesmo eixo: obesidade, infecção e câncer."]}]}, {"titulo": "8. Evasão tumoral e imunoterapia detalhada", "pontos": [{"t": "Três estratégias de escape", "sub": ["Ligantes de receptores inibitórios: a célula tumoral produz PD-L1, que se liga ao PD-1 do linfócito T e o inibe; somam-se citocinas imunossupressoras (IL-10, TGF-β). Pior cenário: ↑PD-L1 com ↓B7 (muito sinal inibitório, pouca coestimulação).", "Deixar de produzir antígeno tumoral: sem peptídeo estranho, o linfócito T passa ao largo. Pior desfecho para o paciente oncológico.", "Deixar de expressar MHC de classe I: escapa do CD8+, mas fica exposto à NK."]}, {"t": "Terapias", "sub": ["Anti-CTLA-4: o CTLA-4 compete com o CD28 pelo B7 da APC, com afinidade maior. Bloquear o CTLA-4 libera o B7 para o CD28 → coestimulação → linfócito T ativado. Caiu na questão 17 do 1.º bimestre pelo avesso: haploinsuficiência de CTLA-4 causa quadro linfoproliferativo e autoimune.", "Anti-PD-1 / anti-PD-L1: bloqueiam o freio periférico; tanto faz bloquear receptor ou ligante. Usados em tumores avançados.", "CAR-T: linfócito T do próprio paciente, modificado por vetor viral para expressar receptor quimérico que reconhece o antígeno tumoral sem restrição ao MHC; devolvido ao paciente, sem rejeição. Usado em leucemias, linfomas e mieloma; alto custo e complexidade.", "Anticorpos monoclonais: intensificam mecanismos efetores (anti-CD20 opsoniza a célula B e a NK executa por ADCC); interferem na sinalização de crescimento (anti-HER2); ou entregam quimioterápico conjugado. Mais específicos que a quimioterapia; anti-CD20 também elimina células B saudáveis."]}, {"t": "Pegadinha: efeito adverso dos checkpoints", "sub": ["O bloqueio de checkpoint retira o freio da resposta imune e, com ele, parte da tolerância periférica. O paciente pode desenvolver reações autoimunes. Não é falha do tratamento; é extensão lógica do mecanismo.", "A analogia do freio é didática, mas CTLA-4 e PD-1 não freiam mecanicamente: reduzem a sinalização intracelular de ativação."]}]}, {"titulo": "9. Para prova", "pontos": [{"t": "Pontos de cobrança", "sub": ["Origem de cada tipo de antígeno tumoral (mutação, vírus, epigenética, superexpressão).", "Função de CTLA-4 × PD-1 e por que o bloqueio ajuda.", "NK com perda de MHC-I e ADCC."]}]}], "glossario": [{"termo": "Neoantígeno", "tecnica": "Origem dos antígenos tumorais", "definicao": "Antígeno novo produzido por genes mutantes nas células tumorais.", "slide": 3}, {"termo": "CEA e alfa-fetoproteína", "tecnica": "Antígenos por alteração epigenética", "definicao": "Antígenos expressos em gametas e trofoblasto, reativados em alguns cânceres.", "slide": 6}, {"termo": "HER2/neu", "tecnica": "Expressão aberrante", "definicao": "Proteína superexpressa por amplificação gênica em alguns tumores.", "slide": 7}, {"termo": "ADCC", "tecnica": "Defesa antitumoral", "definicao": "Citotoxicidade celular dependente de anticorpo: NK destrói células cobertas por anticorpos.", "slide": 12}, {"termo": "PD-1 / PD-L1", "tecnica": "Imunoterapia com receptores inibitórios", "definicao": "Receptor inibitório de T (PD-1) e seu ligante (PD-L1), usados como alvos de bloqueio.", "slide": 19}, {"termo": "CTLA-4", "tecnica": "Imunoterapia com receptores inibitórios", "definicao": "Receptor inibitório de T cujo bloqueio intensifica a resposta antitumoral.", "slide": 18}, {"termo": "CAR-T", "tecnica": "Imunoterapia celular", "definicao": "Células T modificadas para expressar receptores quiméricos contra antígenos tumorais.", "slide": 21}, {"termo": "PD-1 e PD-L1", "tecnica": "Checkpoint", "definicao": "Receptor inibitório da célula T e seu ligante no tumor. Bloqueá-los restaura a resposta antitumoral.", "slide": 19}, {"termo": "Imunovigilância", "tecnica": "Conceito", "definicao": "Reconhecimento e eliminação contínua de células transformadas pelo sistema imune.", "slide": 1}], "caso": {"titulo": "Caso: melanoma avançado e escolha da imunoterapia", "perfil": "Imunoevasão e alvos de imunoterapia.", "etapas": [{"titulo": "Etapa 1: escape tumoral", "texto": "Homem de 60 anos com melanoma metastático. A biópsia mostra alta expressão de PD-L1 nas células tumorais, e os linfócitos T infiltrantes estão inibidos. A equipe discute um bloqueador de receptor inibitório.", "perguntas": [{"pergunta": "Qual mecanismo de escape tumoral é o mais compatível com esse achado, segundo a aula?", "alts": ["Produção de ligantes como PD-L1 para receptores inibitórios das células T", "Perda total de antígenos tumorais, sem reconhecimento possível", "Estímulo de linfócitos B que produzem IgE contra o tumor", "Ativação de mastócitos que liberam histamina no microambiente", "Excesso de MHC de classe I, que ativa as células NK inibidas"], "erradas": ["A aula descreve escape por ligantes inibitórios, não por perda total de antígenos.", "IgE e mastócitos são mecanismos da hipersensibilidade tipo I.", "Excesso de MHC de classe I inibe NK, e não as ativa.", "Aumento de MHC-I não é o escape descrito para PD-L1."], "justificativa": "Células tumorais produzem ligantes, como PD-L1, para receptores inibitórios das células T (slide 15)."}]}, {"titulo": "Etapa 2: leucemia refratária", "texto": "Paciente com leucemia refratária a várias linhas de tratamento. A equipe considera terapia com células T geneticamente modificadas para reconhecer um antígeno tumoral.", "perguntas": [{"pergunta": "Qual é a terapia descrita, segundo a aula?", "alts": ["CAR-T, células T com receptores quiméricos contra antígenos tumorais", "Transfusão de linfócitos B de memória com IgE específica", "Vacina conjugada contra antígenos tumorais de polissacarídeo", "Transplante alogênico de CTH sem modificação das células T", "Anticorpo anti-CTLA-4 administrado em dose única por via oral"], "erradas": ["Linfócitos B de memória com IgE não são a terapia descrita.", "Vacina conjugada é de prevenção infecciosa, não de terapia celular tumoral.", "Transplante de CTH não envolve receptores quiméricos.", "Anticorpo anti-CTLA-4 é administrado por via intravenosa, não oral."], "justificativa": "A terapia celular com CAR-T usa células T com receptores quiméricos contra antígenos tumorais (slides 20 e 21)."}]}]}, "questoes": [{"id": 1, "nivel": "muito_dificil", "enunciado": "Um tumor de cólon expressa um peptídeo fetal reexpresso após desmetilação de genes silenciados. Qual mecanismo de geração de antígeno tumoral está envolvido?", "alternativas": ["Mutação pontual, que gera neoantígeno exclusivo e apresentado apenas em MHC de classe II", "Vírus oncogênico, com proteína viral produzida pela célula infectada e apresentada no MHC II", "Alteração epigenética, com reexpressão de proteína embrionária usada como marcador, como o CEA", "Expressão aberrante por amplificação gênica, com superexpressão de uma proteína normal do organismo", "Perda de MHC de classe I, que torna o tumor invisível ao linfócito T CD8+ por ausência de apresentação"], "gabarito": "C", "justificativa": "Desmetilação de genes silenciados após o nascimento reexpressa proteínas embrionárias, como CEA e alfa-fetoproteína, usados como marcadores (resumo: Imunologia dos tumores, origem dos antígenos).", "tecnica": "Alteração epigenética", "slide": null}, {"id": 2, "nivel": "muito_dificil", "enunciado": "Um tumor de colo do útero expressa proteína viral. Por que a resposta é, na prática, antiviral, mesmo sem a célula estar infectada no momento da detecção?", "alternativas": ["Porque o HPV ativa diretamente células NK, que ignoram o MHC e destroem toda célula com proteína viral", "Para o CD8+, o que importa é o peptídeo estranho no MHC I, seja a célula infectada ou transformada", "Porque a IgE é específica para o capsídeo viral e reconhece a célula transformada independentemente de MHC", "Porque o linfócito B reconhece o DNA viral integrado e produz anticorpos que destroem a célula tumoral", "Porque o HPV não se integra ao genoma, e a célula tumoral mantém a proteína viral apenas na membrana"], "gabarito": "B", "justificativa": "O CD8+ reconhece o peptídeo estranho apresentado no MHC I. Assim, a célula infectada ou transformada produz a mesma resposta (resumo: Imunologia dos tumores, vírus oncogênico).", "tecnica": "Vírus oncogênico", "slide": null}, {"id": 3, "nivel": "muito_dificil", "enunciado": "Por que a imunovigilância depende principalmente do linfócito T citotóxico CD8+, segundo o professor?", "alternativas": ["Porque o CD8+ é o único linfócito capaz de produzir anticorpos IgG", "É o mecanismo efetor preponderante contra células transformadas", "Porque o CD8+ atua somente sobre células NK, que são as células tumorais", "Porque o CD8+ é inibido por todas as citocinas produzidas pelo macrófago M1", "Porque o CD8+ não depende de MHC, reconhecendo qualquer célula sem apresentação"], "gabarito": "B", "justificativa": "A imunovigilância (anos 1950) é o monitoramento contínuo em busca de células transformadas. O mecanismo efetor preponderante é o CD8+, ênfase do professor (resumo: Imunologia dos tumores).", "tecnica": "CD8+ e imunovigilância", "slide": null}, {"id": 4, "nivel": "muito_dificil", "enunciado": "Um tumor perde o MHC de classe I. Por que isso o torna visível à célula NK, mas invisível ao CD8+?", "alternativas": ["A NK reconhece peptídeo no MHC II; sem MHC I, a NK perde o sinal e não consegue destruir o tumor", "O CD8+ reconhece o complemento na superfície; sem MHC I, o complemento se torna invisível ao linfócito", "O CD8+ reconhece peptídeo no MHC I; sem MHC I não há apresentação, e a ausência de MHC I ativa a NK", "A NK e o CD8+ reconhecem o mesmo peptídeo em MHC I, e a perda do MHC os torna inativos", "O CD8+ só reconhece células com MHC II; a NK só reconhece células sem nenhum MHC expresso"], "gabarito": "C", "justificativa": "O CD8+ depende do MHC I para reconhecer o antígeno. A ausência de MHC I inibe o sinal de bloqueio da NK e a ativa, por isso ela assume a defesa (resumo: Imunologia dos tumores, NK).", "tecnica": "NK e perda de MHC I", "slide": null}, {"id": 5, "nivel": "muito_dificil", "enunciado": "Em um paciente com aids, por que o câncer é mais prevalente, se o HIV reduz diretamente o CD4+ e não o CD8+?", "alternativas": ["Porque o HIV infecta o CD8+ e impede sua maturação no timo, eliminando a única defesa antitumoral possível", "Porque o HIV aumenta a IgE, que bloqueia a expressão de MHC I nas células epiteliais de todo o organismo", "Porque o HIV estimula a produção de IL-10 pelo CD8+, que passa a inibir a própria atividade citotóxica", "Porque o HIV reduz as células NK, que são as únicas células capazes de destruir tumores de origem epitelial", "Porque o CD4+ auxilia a ativação do CD8+, e a perda do CD4+ enfraquece indiretamente a defesa antitumoral"], "gabarito": "E", "justificativa": "O CD4+ auxilia a ativação do CD8+. Com a perda de CD4+, a defesa antitumoral cai indiretamente, o que explica a alta prevalência de tumores na aids (resumo: Imunologia dos tumores e Imunodeficiências secundárias).", "tecnica": "HIV e tumor", "slide": null}, {"id": 6, "nivel": "muito_dificil", "enunciado": "Os macrófagos M2 favorecem o tumor por meio de VEGF e metaloproteases. Qual é o contexto que transforma o M2 de benéfico em nocivo?", "alternativas": ["Ativação aguda após uma lesão tecidual, em que o M2 limpa o tecido morto e reconstrói a matriz", "Ausência total de IL-10 e TGF-β no microambiente, o que impede a supressão da resposta antitumoral", "Presença de IFN-γ em alta concentração, que converte o M2 em M1 e estimula o crescimento tumoral", "Ativação crônica, mantida por inflamação de baixo grau", "Presença de anticorpos IgE contra o tumor, que bloqueiam a fagocitose e favorecem a metástase"], "gabarito": "D", "justificativa": "M2 existe por razão fisiológica (reparo). Ativado de forma aguda, repara; ativado cronicamente, favorece o tumor. O estado que o mantém é a inflamação crônica de baixo grau (resumo: Imunologia dos tumores, macrófago).", "tecnica": "M1 × M2", "slide": null}, {"id": 7, "nivel": "muito_dificil", "enunciado": "Um tumor evade o sistema imune produzindo PD-L1 e reduzindo B7. Qual é o pior cenário, segundo a aula?", "alternativas": ["Pouco sinal inibitório e muita coestimulação, com ↓PD-L1 e ↑B7, que ativa o linfócito T", "Ausência total de MHC de classe II, o que impede a apresentação de qualquer antígeno tumoral", "Excesso de IFN-γ, que converte o linfócito T CD8+ em célula regulatória produtora de IL-10", "Muito sinal inibitório e pouca coestimulação, com ↑PD-L1 e ↓B7", "Excesso de IgE, que bloqueia o receptor de TNF nos macrófagos e impede a fagocitose"], "gabarito": "D", "justificativa": "Ligação de PD-L1 ao PD-1 inibe o T. Com ↑PD-L1 e ↓B7 há muito sinal inibitório e pouca coestimulação. É o pior cenário (resumo: Imunologia dos tumores, evasão).", "tecnica": "Evasão e checkpoint", "slide": null}, {"id": 8, "nivel": "muito_dificil", "enunciado": "Um paciente recebe anti-CTLA-4. Por que o CTLA-4 é um alvo tão útil, e o que caiu na prova do 1.º bimestre sobre ele?", "alternativas": ["CTLA-4 compete com CD28 pelo B7; haploinsuficiência causa linfoproliferação e autoimunidade", "CTLA-4 ativa o CD28 e a haploinsuficiência causa imunodeficiência de células B com ausência de IgG", "CTLA-4 é uma citocina de Th2 e a haploinsuficiência causa asma grave por excesso de IgE sérica", "CTLA-4 é receptor de TNF e a haploinsuficiência causa tuberculose disseminada por falha do granuloma", "CTLA-4 é receptor de histamina no endotélio e a haploinsuficiência causa edema angioneurótico recorrente"], "gabarito": "A", "justificativa": "O CTLA-4 compete com o CD28 pelo B7 com afinidade maior. Bloqueá-lo libera o B7 para o CD28. A haploinsuficiência de CTLA-4 causa quadro linfoproliferativo e autoimune (questão 17 do 1.º bimestre; resumo: Imunologia dos tumores).", "tecnica": "CTLA-4", "slide": null}, {"id": 9, "nivel": "muito_dificil", "enunciado": "Um paciente em tratamento com checkpoint inibitor desenvolve doença autoimune. Qual explicação é a mais correta?", "alternativas": ["O anticorpo monoclonal ativa IgE contra o tumor, e a reação alérgica se espalha para o tecido sadio", "O bloqueio retira parte da tolerância periférica, e a reação autoimune é extensão lógica do mecanismo", "O checkpoint destrói as células NK, que são as únicas capazes de conter a autoimunidade no organismo", "O bloqueio ativa o complemento pela via lectina, que destrói a mielina e os receptores de insulina", "O checkpoint aumenta a produção de histamina, que induz hipersensibilidade tardia contra o tecido sadio"], "gabarito": "B", "justificativa": "O bloqueio de checkpoint retira o freio da resposta imune e parte da tolerância periférica. A autoimunidade é previsível, não falha do tratamento (resumo: Imunologia dos tumores, pegadinha).", "tecnica": "Efeito adverso dos checkpoints", "slide": null}, {"id": 10, "nivel": "muito_dificil", "enunciado": "Por que o CAR-T não sofre restrição ao MHC, e por que não há rejeição nesse tratamento?", "alternativas": ["O receptor quimérico reconhece IgE, e o linfócito é de um doador compatível escolhido por HLA", "O linfócito é modificado para expressar MHC de classe II, e por isso ignora o complemento do paciente", "O CAR-T é uma célula NK de doador, que não expressa MHC e portanto não é reconhecida pelo paciente", "O CAR-T é um anticorpo monoclonal de origem animal, que se liga ao CD20 e não ao MHC do paciente", "O receptor quimérico reconhece o antígeno tumoral sem MHC, e o linfócito é do próprio paciente"], "gabarito": "E", "justificativa": "O CAR-T é um linfócito T do próprio paciente, modificado por vetor viral para expressar receptor quimérico que reconhece o antígeno sem restrição ao MHC. Por ser do próprio paciente, não há rejeição (resumo: Imunologia dos tumores, CAR-T).", "tecnica": "CAR-T", "slide": null}, {"id": 11, "nivel": "muito_dificil", "enunciado": "Um anticorpo anti-CD20 é usado no tratamento de linfoma. Como ele atua, e qual é o efeito adverso mais previsível?", "alternativas": ["Opsoniza a célula B e a NK executa ADCC; elimina também células B saudáveis", "Bloqueia o receptor de IL-2 e impede a expansão de T; causa imunossupressão de células NK", "Inibe a calcineurina nos linfócitos B; causa nefrotoxicidade, sem efeito sobre o tumor", "Ativa o complemento pela via lectina e causa anafilaxia por liberação de histamina", "Libera IFN-γ no tumor; causa febre e hipotensão por ação direta sobre o hipotálamo"], "gabarito": "A", "justificativa": "Anti-CD20 intensifica o efeito efetor: opsoniza a célula B e a NK executa ADCC. Também elimina células B saudáveis, por ser pouco específico para a célula tumoral (resumo: Imunologia dos tumores, monoclonais).", "tecnica": "Monoclonais", "slide": null}, {"id": 12, "nivel": "muito_dificil", "enunciado": "Um paciente recebe anticorpo anti-HER2. Qual é a finalidade desse tipo de monoclonal, segundo a aula?", "alternativas": ["Ativar a via clássica do complemento sobre a célula tumoral", "Liberar perforina e granzima diretamente no citosol tumoral", "Bloquear a apresentação antigênica pelo MHC de classe II", "Interferir na sinalização de crescimento do tumor", "Inibir a calcineurina e reduzir a produção de IL-2 nos linfócitos"], "gabarito": "D", "justificativa": "Monoclonais têm três finalidades: intensificar mecanismos efetores, interferir na sinalização de crescimento (anti-HER2) ou entregar quimioterápico conjugado (resumo: Imunologia dos tumores, monoclonais).", "tecnica": "Anti-HER2", "slide": null}, {"id": 13, "nivel": "muito_dificil", "enunciado": "Na imunoedição, a fase de equilíbrio descreve clones residuais sob pressão imune. Qual é o resultado dessa fase?", "alternativas": ["Eliminação completa de todas as células transformadas, sem nenhum clone residual no tecido", "Aumento da expressão de MHC de classe I em todos os clones tumorais, tornando-os mais visíveis", "Seleção dos clones menos imunogênicos, que seguem para a fase de escape", "Formação imediata de metástases, por ausência total de linfócitos T CD8+ no microambiente", "Transformação do macrófago M2 em M1, que elimina os clones tumorais com perfil de IL-10"], "gabarito": "C", "justificativa": "Na fase de equilíbrio, os clones residuais sobrevivem sob pressão e são selecionados os menos imunogênicos, que seguem para o escape (resumo: Imunologia dos tumores, imunoedição).", "tecnica": "Imunoedição", "slide": null}, {"id": 14, "nivel": "muito_dificil", "enunciado": "Por que a vacina contra HPV é considerada prevenção primária de câncer, e não tratamento?", "alternativas": ["Porque evita a infecção viral e, assim, reduz a prevalência dos tumores associados ao vírus", "Porque reduz o tamanho de tumores já formados, pela ativação de linfócitos T CD8+ específicos do tumor", "Porque bloqueia o PD-1 de linfócitos T e impede a progressão de tumores de colo do útero já estabelecidos", "Porque age sobre o macrófago M2, convertendo-o em M1 e impedindo a angiogênese nos tumores de orofaringe", "Porque é feita apenas em adultos com câncer diagnosticado, como adjuvante após a cirurgia de remoção"], "gabarito": "A", "justificativa": "A vacina contra o HPV evita a infecção, e portanto reduz a prevalência dos tumores associados. É feita antes do início da vida sexual e em ambos os sexos (resumo: Imunologia dos tumores, correlação clínica).", "tecnica": "Prevenção primária", "slide": null}, {"id": 15, "nivel": "muito_dificil", "enunciado": "Um tumor escapa do sistema imune por perda de antígeno. Qual é a consequência clínica mais grave, segundo a aula?", "alternativas": ["O tumor se torna mais visível para a NK, que destrói o tumor por ADCC com eficácia máxima", "O paciente desenvolve doença do soro, com imunocomplexos depositados nos glomérulos renais", "O paciente desenvolve tuberculose disseminada, por falha do granuloma tumoral no pulmão", "O paciente desenvolve imunodeficiência congênita, com ausência de linfócitos T ao nascimento", "Sem peptídeo estranho, o linfócito T passa ao largo, o que é o pior desfecho para o paciente"], "gabarito": "E", "justificativa": "Sem antígeno tumoral, o linfócito T não reconhece a célula. Para o paciente oncológico, essa é a pior estratégia de escape, pois o sistema imune fica sem alvo (resumo: Imunologia dos tumores, evasão).", "tecnica": "Escape por perda de antígeno", "slide": null}], "id": "imuno-thiago-10", "titulo": "Aula 10", "voltar": {"href": "#/agressao/thiago", "texto": "Professor Thiago"}, "manobras": [], "imagens": [], "casos_extremos": []};
window.INDICE_AGRESSAO = window.INDICE_AGRESSAO || {};
window.INDICE_AGRESSAO["thiago"] = [{"id": "imuno-thiago-01", "titulo": "Aula 1", "subtitulo": "Revisitando a imunologia básica"}, {"id": "imuno-thiago-02", "titulo": "Aula 2", "subtitulo": "Diagnóstico imunológico"}, {"id": "imuno-thiago-03", "titulo": "Aula 3", "subtitulo": "Imunodeficiências congênitas (erros inatos da imunidade)"}, {"id": "imuno-thiago-04", "titulo": "Aula 4", "subtitulo": "Imunodeficiências secundárias (HIV, desnutrição, obesidade e imunossupressão)"}, {"id": "imuno-thiago-05", "titulo": "Aula 5", "subtitulo": "Tolerância e mecanismos de autoimunidade"}, {"id": "imuno-thiago-06", "titulo": "Aula 6", "subtitulo": "Imunização por vacinas virais e bacterianas"}, {"id": "imuno-thiago-07", "titulo": "Aula 7", "subtitulo": "Hipersensibilidade tipo I (alergia)"}, {"id": "imuno-thiago-08", "titulo": "Aula 8", "subtitulo": "Reações de hipersensibilidade tipo II, III e IV"}, {"id": "imuno-thiago-09", "titulo": "Aula 9", "subtitulo": "Transplante e mecanismos de rejeição"}, {"id": "imuno-thiago-10", "titulo": "Aula 10", "subtitulo": "Imunologia dos tumores e imunoterapia"}];
